fun mult(a: Array<DoubleArray>, b: Array<DoubleArray>): Array<DoubleArray>? {
    if (a.size == 0) return arrayOf(doubleArrayOf())
    if (a[0].size!= b.size) return null //invalid dims

    val n = a[0].size
    val m = a.size
    val p = b[0].size

    val ans = Array(m) { DoubleArray(p) }

    for (i in 0 until m) {
        for (j in 0 until p) {
            for (k in 0 until n) {
                ans[i][j] += a[i][k] * b[k][j]
            }
        }
    }
    return ans
}

