import java.util.Calendar
import java.util.GregorianCalendar

fun lastFridays(year: Int) {
    for (month in 1..12) {
        val lastFriday = (1..Calendar.WEDNESDAY).maxBy {
            val calendar = GregorianCalendar(year, month - 1, it)
            calendar.get(Calendar.DAY_OF_WEEK)
        }
        println("$year-${month.toString().padStart(2, '0')}-${lastFriday.toString().padStart(2, '0')}")
    }
}

import kotlin.system.measureTimeMillis
 
fun sieve(sv: BooleanArray) {
    var n = 0
    val s = IntArray(8)
    for (a in 0..1) {
        for (b in 0..9) {
            s[0] = a + b
            for (c in 0..9) {
                s[1] = s[0] + c
                for (d in 0..9) {
                    s[2] = s[1] + d
                    for (e in 0..9) {
                        s[3] = s[2] + e
                        for (f in 0..9) {
                            s[4] = s[3] + f
                            for (g in 0..9) {
                                s[5] = s[4] + g
                                for (h in 0..9) {
                                    s[6] = s[5] + h
                                    for (i in 0..9) {
                                        s[7] = s[6] + i
                                        for (j in 0..9) {
                                            sv[s[7] + j + n++] = true
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}
 
fun main() {
    var count = 0
    val time = measureTimeMillis {
        val sv = BooleanArray(2 * 1000000000 + 9 * 9 + 1)
        sieve(sv)
        println("The first 50 self numbers are:")
        for (i in sv.indices) {
            if (!sv[i]) {
                if (++count <= 50) println(i)
                if (count == 100 * 1000000) {
                    println("\nThe 100 millionth self number is $i")
                    break
                }
            }
        }
    }
    println("Took $time seconds.")
}

