using namespace std;
 
//------------------------------------------------------------------------------
class stooge
{
public:
    void sort( int* arr, int start, int end )
    {
        if( arr[start] > arr[end - 1] ) swap( arr[start], arr[end - 1] );
	int n = end - start; if( n > 2 )
	{
	    n /= 3; sort( arr, start, end - n );
	    sort( arr, start + n, end ); sort( arr, start, end - n );
        }
    }
};
//------------------------------------------------------------------------------
int main( int argc, char* argv[] )
{
    srand( static_cast<unsigned int>( time( NULL ) ) ); stooge s; int a[80], m = 80; 
    cout << "before:\n";
    for( int x = 0; x < m; x++ ) { a[x] = rand() % 40 - 20;  cout << a[x] << " "; }
    s.sort( a, 0, m ); cout << "\n\nafter:\n"; 
    for( int x = 0; x < m; x++ ) cout << a[x] << " "; cout << "\n\n"; 
    return system( "pause" );
}

import java.util.ArrayList
import java.util.function.Consumer
 
fun <T> ArrayList<T>.toString(): String {
    val sb = StringBuilder()
    sb.append("[")
    if (this.size > 0) {
        sb.append(this[0])
    }
    for (i in 1 until this.size) {
        sb.append(", ").append(this[i])
    }
    sb.append("]")
    return sb.toString()
}
 
fun kosaraju(g: ArrayList<ArrayList<Int>>): ArrayList<Int> {
    // 1. For each vertex u of the graph, mark u as unvisited. Let l be empty.
    val size = g.size
    val vis = BooleanArray(size) // all false by default
    val l = IntArray(size) // all zero by default
    var x = size // index for filling l in reverse order
    val t = ArrayList<ArrayList<Int>>(size) // transpose graph
 
    // Recursive subroutine 'visit':
    val visit = Consumer<Int> { u ->
        if (!vis[u]) {
            vis[u] = true
            for (v in g[u]) {
                visit.accept(v)
                t[v].add(u) // construct transpose
            }
            l[--x] = u
        }
    }
 
    // 2. For each vertex u of the graph do visit(u)
    for (i in 0 until g.size) {
        visit.accept(i)
    }
    val c = IntArray(size) // used for component assignment
 
    // Recursive subroutine 'assign':
    val assign = Consumer<Int> { u: Int, root: Int ->
        if (vis[u]) { // repurpose vis to mean 'unassigned'
            vis[u] = false
            c[u] = root
            for (v in t[u]) {
                assign.accept(v, root)
            }
        }
    }
 
    // 3: For each element u of l in order, do assign(u, u)
    for (u in l) {
        assign.accept(u, u)
    }
 
    return ArrayList(c.asList())
}
 
val g = arrayListOf(
