import java.util.Arrays
 
class Sum(var x: Int, var y: Int, var value: Long)
 
fun main(args: Array<String>) {
	val cube = LongArray(2007)
	var nCubes = 0
	val pq = arrayOfNulls<Sum>(2007)
	var pqLen = 0
	var pqCap = 0
 
	fun addCube() {
		val x = nCubes++
		cube[nCubes] = nCubes * nCubes * nCubes.toLong()
		if (x < 2) return // x = 0 or 1 is useless
 
		if (++pqLen >= pqCap) {
			if (pqCap == 0) pqCap = 2
			else pqCap *= 2
			pq.copyOf(pqCap)
		}
 
		val tmp = Sum(x, 1, cube[x] + 1)
		// upheap
		var i: Int
		var j: Int
		for (i = pqLen; i >= 1 && pq[j = i shr 1]!!.value > tmp.value; i = j)
			pq[i] = pq[j]
 
		pq[i] = tmp
	}
 
fun nextSum() {
	while (pqLen == 0 || pq[1]!!.value >= cube[nCubes]) addCube()
 
		val tmp = pq[0] = pq[1] // pq[0] always stores last seen value
		if (++tmp.y >= tmp.x) { // done with this x; throw it away
			tmp = pq[pqLen--]
			if (pqLen == 0) return // refill empty heap
		} else
			tmp.value += cube[tmp.y] - cube[tmp.y - 1]
 
		var i: Int
		var j: Int
		// downheap
		for (i = 1; (j = i shl 1) <= pqLen; pq[i] = pq[j], i = j) {
			if (j < pqLen && pq[j + 1]!!.value < pq[j]!!.value) ++j
			if (pq[j]!!.value >= tmp.value) break
		}
		pq[i] = tmp
	}
 
fun nextTaxi(hist: Array<Sum>): Int {
	do nextSum() while (pq[0]!!.value!= pq[1]!!.value)
 
		var len = 1
		hist[0] = pq[0]
		do {
			hist[len++] = pq[1]
			nextSum()
		} while (pq[0]!!.value == pq[1]!!.value)
 
		return len
	}
 
	var i: Int
	var l: Int
	val x = arrayOfNulls<Sum>(10)
	for (i = 1; i <= 2006; i++) {
		l = nextTaxi(x)
		if (25 < i && i < 2000) continue
		print(String.format("%4d:%10d", i, x[0]!!.value))
		while (l-- > 0) print(String.format(" = %4d^3 + %4d^3", x[l]!!.x, x[l]!!.y))
		println()
	}
}

