    var v0 = 0
    var a: Int
    var b: Int
    var c: Int
    var a0 = 0
    var b0 = 0
    var c0 = 0
    for (a in 0..10)
        for (b in 0..(a * 5 + 3 * 50))
            for (c in 0..(a * 25 + b * 15 + 2 * 250) / 2)
                if (v0 < (v = a * 30 + b * 18 + c * 25))
                {
                    v0 = v
                    a0 = a
                    b0 = b
                    c0 = c
                    //Console.WriteLine("{0,5} {1,5} {2,5} {3,5}", v, a, b, c);
                }
