}
 
fun items1(): Array<Int>  // 0,22 µs
{
    var v: Int
    var v0 = 0
    var a: Int
    var b: Int
    var c: Int
    var a0 = 0
    var b0 = 0
    var c0 = 0
    var c1: Int
    for (a in 0..10)
        for (b in 0..(a * 5 + 3 * 50))
        {
            c = (250 - a * 25 - b * 15) / 2
            c1 = (250 - a * 3 - b * 2) / 20
            if (c1 < c) c = c1
            if (v0 < (v = a * 30 + b * 18 + c * 25))
            {
                v0 = v
                a0 = a
                b0 = b
                c0 = c
            }
        }
    return arrayOf(a0, b0, c0)
}

