fun add12hours(dateString: String): Date? {
    // Get the parts of the date string
    val parts = dateString.split("\\s+".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()
    val date = parts[1]
    val month = parts[0]
    val year = parts[2]
    val time = parts[3]
    val hr = time.split(":".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()[0].toInt()
    val min = time.split(":".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()[1].replace("\\D".toRegex(), "").toInt()
    val ampm = time.split("(?=\\p{Lower})".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()[1]
    val zone = parts[4].toUpperCase()
    val months = arrayOf("January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December")
    val zones = mapOf("EST" to 300, "AEST" to -600)
    // Convert month name to number, zero indexed. Return if invalid month
    val month = months.indexOf(month)
    if (month == -1) {
        return null
    }
    // Add 12 hours as specified. Add another 12 if pm for 24hr time
    var hr = hr
    hr += if (ampm.toLowerCase() == "pm") 24 else 12
    // Create a date object in local zone
    val localTime = Date(year.toInt(), month, date.toInt())
    localTime.setHours(hr, min, 0, 0)
    // Adjust localTime minutes for the time zones so it is now a local date
    // representing the same moment as the source date plus 12 hours
    localTime.setMinutes(localTime.getMinutes() + zones[zone]!! - localTime.getTimezoneOffset())
    return localTime
}
 
