package main
 
import "fmt"
 
type Deck struct {
	Cards []int
	length int
}
 
fun NewDeck(deckSize: Int): Deck {
	if (deckSize % 2!= 0) {
		throw IllegalArgumentException("Deck size must be even")
	}
	val res = Deck()
	res.Cards = IntArray(deckSize)
	res.length = deckSize
	for (i in 0 until deckSize) {
		res.Cards[i] = i
	}
	return res
}
 
fun Deck.shuffleDeck() {
	val tmp = IntArray(length)
	for (i in 0 until length / 2) {
		tmp[i * 2] = Cards[i]
		tmp[i * 2 + 1] = Cards[length / 2 + i]
	}
	Cards = tmp
}
 
fun Deck.isEqualTo(c: Deck): Boolean {
	if (length!= c.length) {
		throw IllegalArgumentException("Decks aren't equally sized")
	}
	var res = true
	for (i in 0 until length) {
		if (Cards[i]!= c.Cards[i]) {
			res = false
		}
	}
	return res
}
 
fun main(args: Array<String>) {
	for (v in arrayOf(8, 24, 52, 100, 1020, 1024, 10000)) {
		println("Cards count: $v, shuffles required: ${ShufflesRequired(v)}")
	}
}
 
fun ShufflesRequired(deckSize: Int): Int {
	val deck = NewDeck(deckSize)
	val Ref = deck
	deck.shuffleDeck()
	var res = 1
	while (!deck.isEqualTo(Ref)) {
		deck.shuffleDeck()
		res++
	}
	return res
}

