const val MAXSIZE = 2048
 
val bitmap = Array(MAXSIZE) { BooleanArray(MAXSIZE) }
var oldColor: Boolean = false
var newColor: Boolean = false
var width: Int = 0
var height: Int = 0
 
fun floodFill(i: Int, j: Int) {
    if (0 <= i && i < height && 0 <= j && j < width && bitmap[i][j] == oldColor) {
        bitmap[i][j] = newColor
        floodFill(i - 1, j)
        floodFill(i + 1, j)
        floodFill(i, j - 1)
        floodFill(i, j + 1)
    }
}
 
fun skipLine(file: InputStream) {
    while (!file.read().toChar().isWhitespace()) {
    }
}
 
fun skipCommentLines(file: InputStream) {
    var c: Int
    var comment = '#'
    while (c = file.read().toChar(), c == comment) {
        skipLine(file)
    }
    file.unread(c)
}
 
fun readPortableBitMap(file: InputStream) {
    skipLine(file)
    skipCommentLines(file)
    width = Scanner(file).nextInt()
    skipCommentLines(file)
    height = Scanner(file).nextInt()
    skipCommentLines(file)
    if (width <= MAXSIZE && height <= MAXSIZE) {
        for (i in 0 until height) {
            for (j in 0 until width) {
                bitmap[i][j] = Scanner(file).nextInt() == 1
            }
        }
    } else {
        throw Exception("Image size is too big")
    }
}
 
fun writePortableBitMap(file: OutputStream) {
    file.write("P1\n".toByteArray())
    file.write("$width $height\n".toByteArray())
    for (i in 0 until height) {
        for (j in 0 until width) {
            file.write(if (bitmap[i][j]) "1" else "0")
        }
        file.write("\n".toByteArray())
    }
}
 
fun main(args: Array<String>) {
    oldColor = true
    newColor =!oldColor
    readPortableBitMap(FileInputStream(File(args[0])))
    floodFill(height / 2, width / 2)
    writePortableBitMap(FileOutputStream(File(args[1])))
}

fun to_roman(value: Int): String {
    val romandata = arrayOf(1000, "M", 900, "CM", 500, "D", 400, "CD", 100, "C", 90, "XC", 50, "L", 40, "XL", 10, "X", 9, "IX", 5, "V", 4, "IV", 1, "I", 0, null)
    var result = ""
    var current = 0
    while (romandata[current].value > 0) {
        while (value >= romandata[current].value) {
            result += romandata[current].numeral
            value -= romandata[current].value
        }
        current++
    }
    return result
}
 
fun main(args: Array<String>) {
    for (i in 1..4000) {
        println(to_roman(i))
    }
}

