import java.util.*
 
fun main(args: Array<String>) {
    val input = arrayOf("44 Solomon", "42 Jason", "42 Errol", "41 Garry", "41 Bernard", "41 Barry", "39 Stephen")
    val len = input.size
 
    val map = TreeMap<String, IntArray> { a, b -> b.compareTo(a) }
    for (i in 0 until len) {
        val key = input[i].split("\\s+".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()[0]
        var arr: IntArray? = map[key]
        if (arr == null)
            arr = intArrayOf(i, 0)
        arr[1]++
        map[key] = arr
    }
    val groups = map.values.toTypedArray()
 
    standardRanking(len, groups)
    modifiedRanking(len, groups)
    denseRanking(len, groups)
    ordinalRanking(len)
    fractionalRanking(len, groups)
}
 
private fun standardRanking(len: Int, groups: Array<IntArray>) {
    println("\nStandard ranking")
    var rank = 0
    var group = 0
    for (i in 0 until len) {
        if (group < groups.size && i == groups[group][0]) {
            rank = i + 1
            group++
        }
        println(String.format("%d %s", rank, input[i]))
    }
}
 
private fun modifiedRanking(len: Int, groups: Array<IntArray>) {
    println("\nModified ranking")
    var rank = 0
    var group = 0
    for (i in 0 until len) {
        if (group < groups.size && i == groups[group][0])
            rank += groups[group++][1]
        println(String.format("%d %s", rank, input[i]))
    }
}
 
private fun denseRanking(len: Int, groups: Array<IntArray>) {
    println("\nDense ranking")
    var rank = 0
    for (i in 0 until len) {
        if (rank < groups.size && i == groups[rank][0])
            rank++
        println(String.format("%d %s", rank, input[i]))
    }
}
 
private fun ordinalRanking(len: Int) {
    println("\nOrdinal ranking")
    for (i in 0 until len)
        println(String.format("%d %s", i + 1, input[i]))
}
 
private fun fractionalRanking(len: Int, groups: Array<IntArray>) {
    println("\nFractional ranking")
    var rank = 0f
    var tmp = 0
    var group = 0
    for (i in 0 until len) {
        if (group < groups.size && i == groups[group][0]) {
            tmp += groups[group++][1]
            rank = (i + 1 + tmp) / 2.0f
        }
        println(String.format("%2.1f %s", rank, input[i]))
    }
}

import java.math.BigInteger
 
fun p(n: Int, p: Int): BigInteger {
    var r = BigInteger.ONE
    var k = n - p
    while (n > k)
        r *= n--
    return r
}
 
fun c(n: Int, k: Int): BigInteger {
    var r = p(n, k)
    while (k > 0)
        r /= k--
    return r
}
 
fun main(args: Array<String>) {
    for (i in 1..11)
        println("P(12, $i) = ${p(12, i)}")
    for (i in 10..50 step 10)
        println("C(60, $i) = ${c(60, i)}")
}

