class Matrix(val rows: Int, val cols: Int, val data: Array<DoubleArray>) {
    operator fun get(row: Int, col: Int): Double = data[row][col]
    operator fun set(row: Int, col: Int, value: Double) {
        data[row][col] = value
    }
 
    fun elementWise(operator: (Double, Double) -> Double, other: Matrix): Matrix {
        val result = Matrix(rows, cols, Array(rows) { DoubleArray(cols) })
        for (row in 0 until rows) {
            for (col in 0 until cols) {
                result[row, col] = operator(this[row, col], other[row, col])
            }
        }
        return result
    }
 
    override fun toString(): String {
        val sb = StringBuilder()
        for (row in 0 until rows) {
            for (col in 0 until cols) {
                sb.append(this[row, col]).append(" ")
            }
            sb.append("\n")
        }
        return sb.toString()
    }
 
    companion object {
        fun build(rows: Int, cols: Int, init: (Int, Int) -> Double): Matrix {
            val data = Array(rows) { DoubleArray(cols) }
            for (row in 0 until rows) {
                for (col in 0 until cols) {
                    data[row][col] = init(row, col)
                }
            }
            return Matrix(rows, cols, data)
        }
    }
}
 
fun main() {
    val m1 = Matrix(2, 3, { row, col -> (row + 1) * 10 + col + 1 })
    val m2 = Matrix(2, 3, { row, col -> (row + 1) * 10 + col + 1 })
    println("m1: $m1\nm2: $m2\n")
 
    val operators = arrayOf("+", "-", "*", "/", "fdiv", "**", "%")
    for (op in operators) {
        println("m1 %-4s m2  =  ${m1.elementWise(getOperator(op), m2)}")
    }
}
 
fun getOperator(op: String): (Double, Double) -> Double {
    return when (op) {
        "+" -> Double::plus
        "-" -> Double::minus
        "*" -> Double::times
        "/" -> Double::div
        "fdiv" -> { a, b -> a / b }
        "**" -> { a, b -> a.pow(b) }
        "%" -> { a, b -> a % b }
        else -> throw IllegalArgumentException("Unknown operator: $op")
    }
}

import java.util.ArrayList
import java.util.Arrays
 
typealias Tree = Long
 
val list = ArrayList<Tree>()
var cap = 0
var len = 0
val offset = IntArray(32)
 
fun append(t: Tree) {
	if (len == cap) {
		cap = if (cap == 0) 2 else cap * 2
		list.ensureCapacity(cap)
	}
	list.add(1 or (t shl 1))
	len++
}
 
fun show(t: Tree, len: Int) {
	for (i in 0 until len) {
		print(if (t and 1 == 1L) "(" else ")")
		t shr= 1
	}
}
 
fun listtrees(n: Int) {
	for (i in offset[n] until offset[n + 1]) {
		show(list[i], n * 2)
		println()
	}
}
 
/* assemble tree from subtrees
	n:   length of tree we want to make
	t:   assembled parts so far
	sl:  length of subtree we are looking at
	pos: offset of subtree we are looking at
	rem: remaining length to be put together
*/
fun assemble(n: Int, t: Tree, sl: Int, pos: Int, rem: Int) {
	if (rem == 0) {
		append(t)
		return
	}
 
	if (sl > rem) // need smaller subtrees
		pos = offset[sl] = rem
	else if (pos >= offset[sl + 1]) {
		// used up sl-trees, try smaller ones
		if (--sl == 0) return
		pos = offset[sl]
	}
 
	assemble(n, t shl (2 * sl) or list[pos], sl, pos, rem - sl)
	assemble(n, t, sl, pos + 1, rem)
}
 
fun mktrees(n: Int) {
	if (offset[n + 1]!= 0) return
	if (n > 0) mktrees(n - 1)
 
	assemble(n, 0, n - 1, offset[n - 1], n - 1)
	offset[n + 1] = len
}
 
fun main(args: Array<String>) {
	var n = 5
	if (args.size > 0) {
		n = args[0].toInt()
	}
	if (n <= 0 || n > 25) n = 5
 
	// init 1-tree
	append(0)
 
	mktrees(n)
	System.err.printf("Number of %d-trees: %d\n", n, offset[n + 1] - offset[n])
	listtrees(n)
}

