fun expI(b: Int, p: Int): Pair<Int, String?> {
    if (p < 0) {
        return Pair(0, "negative power not allowed")
    }
    var r = 1
    for (i in 1..p) {
        r *= b
    }
    return Pair(r, null)
}
 
fun expF(b: Float, p: Int): Float {
    var neg = false
    if (p < 0) {
        neg = true
        p = -p
    }
    var r = 1f
    var pow = b
    while (p > 0) {
        if (p and 1 == 1) {
            r *= pow
        }
        p = p shr 1
        pow *= pow
    }
    if (neg) {
        r = 1f / r
    }
    return r
}
 
fun main(args: Array<String>) {
    val ti = { b: Int, p: Int ->
        println(String.format("%d^%d: ", b, p))
        val (e, err) = expI(b, p)
        if (err!= null) {
            println(err)
        } else {
            println(e)
        }
    }
 
    println("expI tests")
    ti(2, 10)
    ti(2, -10)
    ti(-2, 10)
    ti(-2, 11)
    ti(11, 0)
 
    println("overflow undetected")
    ti(10, 10)
 
    val tf = { b: Float, p: Int ->
        println(String.format("%g^%d: %g", b, p, expF(b, p)))
    }
 
    println("\nexpF tests:")
    tf(2f, 10)
    tf(2f, -10)
    tf(-2f, 10)
    tf(-2f, 11)
    tf(11f, 0)
 
    println("disallowed in expI, allowed here")
    tf(0f, -1)
 
    println("other interesting cases for 32 bit float type")
    tf(10f, 39)
    tf(10f, -39)
    tf(-10f, 39)
}

fun Array<Int>.beadsort(): List<Int> {
    return map { IntArray(it).map { 1 } }.columns().columns().map { it.size }
}
 
fun Array<IntArray>.columns(): Array<IntArray> {
    val y = size
    val x = map { it.size }.max()!!
    return Array(x) { row ->
        IntArray(y) { column ->
            this[column][row]
        }.filterNotNull() // Remove nulls.
    }
}

import kotlin.math.pow
import kotlin.math.roundToInt
 
fun identity(size: Int): Array<DoubleArray> {
    val matrix = Array(size) { DoubleArray(size) }
    for (i in 0 until size) matrix[i][i] = 1.0
    return matrix
}
 
fun multiply(left: Array<DoubleArray>, right: Array<DoubleArray>): Array<DoubleArray> {
    if (left.size!= right.size) throw IllegalArgumentException()
    val m = Array(left.size) { DoubleArray(right.size) }
    for (row in 0 until m.size) {
        for (column in 0 until m.size) {
            m[row][column] = (0 until m.size).sumOf { i -> left[row][i] * right[i][column] }
        }
    }
    return m
}
 
fun pow(matrix: Array<DoubleArray>, exp: Int): Array<DoubleArray> {
    if (matrix.size!= matrix[0].size) throw IllegalArgumentException("Matrix must be square.")
    var accumulator = identity(matrix.size)
    for (i in 0 until exp) {
        accumulator = multiply(accumulator, matrix)
    }
    return accumulator
}
 
fun print(m: Array<DoubleArray>) {
    for (row in m) {
        println("[ ${row.joinToString("   ")} ]")
    }
    println()
}
 
