}

import java.util.Collections
import java.util.Random
 
fun <T : Comparable<T>> List<T>.isSorted(): Boolean {
    if (this.size <= 1) return true
    for (i in 1..this.size - 1)
        if (this[i] < this[i - 1]) return false
    return true
}
 
fun <T> List<T>.shuffle() {
    val rand = Random()
    for (i in 0..this.size - 1) {
        val swapIndex = rand.nextInt(this.size)
        val temp = this[swapIndex]
        this[swapIndex] = this[i]
        this[i] = temp
    }
}
 
fun <T : Comparable<T>> List<T>.bogoSort() {
    while (!this.isSorted()) {
        this.shuffle()
    }
}
 
fun main(args: Array<String>) {
    val testList = listOf(3, 4, 1, 8, 7, 4, -2)
    testList.bogoSort()
    println(testList)
}

