// Constants
val a1 = intArrayOf(0, 1403580, -810728)
val m1 = 2.0.pow(32.0) - 209
//
val a2 = intArrayOf(527612, 0, -1370589)
val m2 = 2.0.pow(32.0) - 22853
//
val d = m1 + 1
 
class MRG32k3a() {
 
    var x1 = intArrayOf(0, 0, 0)
    var x2 = intArrayOf(0, 0, 0)
 
    fun seed(seed_state: Int) {
        assert(seed_state > 0 && seed_state < d) { "Out of Range 0 x < $d" }
        x1 = intArrayOf(seed_state, 0, 0)
        x2 = intArrayOf(seed_state, 0, 0)
    }
 
    fun next_int(): Int {
        "return random int in range 0..d"
        val x1i = (a1[0] * x1[0] + a1[1] * x1[1] + a1[2] * x1[2]) % m1
        val x2i = (a2[0] * x2[0] + a2[1] * x2[1] + a2[2] * x2[2]) % m2
        x1 = intArrayOf(x1i, x1[0], x1[1])
        x2 = intArrayOf(x2i, x2[0], x2[1])
 
        val z = (x1i - x2i) % m1
        val answer = (z + 1)
 
        return answer
    }
 
    fun next_float(): Double {
        "return random float between 0 and 1"
        return next_int() / d
    }
}
 
fun main() {
    val random_gen = MRG32k3a()
    random_gen.seed(1234567)
    for (i in 0..4) {
        println(random_gen.next_int())
    }
 
    random_gen.seed(987654321)
    val hist = IntArray(5)
    for (i in 0..99_999) {
        hist[random_gen.next_float() * 5.0] += 1
    }
    println(hist.toList())
}

fun runCode(code: String) {
    val c_len = code.length
    var accumulator = 0
    var bottles = 0
    for (i in 0 until c_len) {
        when (code[i]) {
            'Q' -> println(code)
            'H' -> println("Hello, world!")
            '9' -> {
                bottles = 99
                do {
                    println("$bottles bottles of beer on the wall")
                    println("$bottles bottles of beer")
                    println("Take one down, pass it around")
                    println(--bottles.toString() + " bottles of beer on the wall")
                } while (bottles > 0)
            }
            '+' -> accumulator++
        }
    }
}

import kotlin.random.Random
import kotlin.system.exitProcess
 
val N = 3
val board = Array(N) { IntArray(N) }
 
fun setbits(count: Int = 1) {
    for (i in 0 until count) {
        board[Random.nextInt(N)][Random.nextInt(N)] = 1
    }
}
 
fun shuffle(count: Int = 1) {
    for (i in 0 until count) {
        if (Random.nextBoolean()) {
            fliprow(Random.nextInt(N))
        } else {
            flipcol(Random.nextInt(N))
        }
    }
}
 
fun pr(comment: String = "") {
    println(comment)
    print("     ")
    for (i in 0 until N) {
        print(" ${'a' + i}")
    }
    println()
    for (i in 0 until N) {
        print("  ${i + 1}")
        for (j in 0 until N) {
            print(" ${board[i][j]}")
        }
        println()
    }
}
 
fun init(): Array<IntArray> {
    setbits(Random.nextInt(N) + 1)
    val target = board.copyOf()
    while (target.contentDeepEquals(board)) {
        shuffle(2 * N)
    }
    return target
}
 
fun fliprow(i: Int) {
    for (j in 0 until N) {
        board[i][j] = 1 - board[i][j]
    }
}
 
fun flipcol(i: Int) {
    for (j in 0 until N) {
        board[j][i] = 1 - board[j][i]
    }
}
 
fun main() {
    println("Translate this\n" +
            "Given a %i by %i sqare array of zeroes or ones in an initial\n" +
            "configuration, and a target configuration of zeroes and ones\n" +
            "The task is to transform one to the other in as few moves as \n" +
            "possible by inverting whole numbered rows or whole lettered \n" +
            "columns at once.\n" +
            "In an inversion any 1 becomes 0 and any 0 becomes 1 for that\n" +
            "whole row or column.\n" +
            "\n", N, N)
    val target = init()
    pr("Target configuration is:")
    println()
    var turns = 0
    while (!board.contentDeepEquals(target)) {
        turns++
        pr("$turns:")
        val ans = readLine()
        if (ans.isNullOrEmpty()) {
            continue
        }
        val ch = ans[0]
        if (ch in 'a'..'a' + N - 1) {
            flipcol(ch - 'a')
        } else if (ch in '1'..'1' + N - 1) {
            fliprow(ch - '1')
        } else if (ch == 'T') {
            pr("Target configuration is:")
            turns--
        } else if (ch == 'X') {
            break
        } else {
            println("  I don't understand %r... Try again. " +
                    "(X to exit or T to show target)\n", ans)
            turns--
        }
    }
    println("\nWell done!\nBye.")
}

