data class Item(val name: String, val weight: Int, val value: Int)
 
val items = arrayOf(
    Item("map", 9, 150),
    Item("compass", 13, 35),
    Item("water", 153, 200),
    Item("sandwich", 50, 160),
    Item("glucose", 15, 60),
    Item("tin", 68, 45),
    Item("banana", 27, 60),
    Item("apple", 39, 40),
    Item("cheese", 23, 30),
    Item("beer", 52, 10),
    Item("suntan cream", 11, 70),
    Item("camera", 32, 30),
    Item("T-shirt", 24, 15),
    Item("trousers", 48, 10),
    Item("umbrella", 73, 40),
    Item("waterproof trousers", 42, 70),
    Item("waterproof overclothes", 43, 75),
    Item("note-case", 22, 80),
    Item("sunglasses", 7, 20),
    Item("towel", 18, 12),
    Item("socks", 4, 50),
    Item("book", 30, 10)
)
 
fun knapsack(items: Array<Item>, n: Int, w: Int): IntArray {
    val m = Array(n + 1) { IntArray(w + 1) }
    for (i in 1..n) {
        for (j in 0..w) {
            if (items[i - 1].weight > j) {
                m[i][j] = m[i - 1][j]
            } else {
                val a = m[i - 1][j]
                val b = m[i - 1][j - items[i - 1].weight] + items[i - 1].value
                m[i][j] = if (a > b) a else b
            }
        }
    }
    val s = IntArray(n)
    for (i in n downTo 1) {
        if (m[i][w] > m[i - 1][w]) {
            s[i - 1] = 1
            w -= items[i - 1].weight
        }
    }
    return s
}
 
fun main() {
    val n = items.size
    val s = knapsack(items, n, 400)
    var tw = 0
    var tv = 0
    for (i in 0 until n) {
        if (s[i] == 1) {
            println(String.format("%-22s %5d %5d", items[i].name, items[i].weight, items[i].value))
            tw += items[i].weight
            tv += items[i].value
        }
    }
    println(String.format("%-22s %5d %5d", "totals:", tw, tv))
}

fun hofstadterQ(): (Int) -> Int {
    val memo = arrayOf(1, 1, 1)
    val Q = { n: Int ->
        var result = memo[n]
        if (result!is Int) {
            result = Q(n - Q(n - 1)) + Q(n - Q(n - 2))
            memo[n] = result
        }
        result
    }
    return Q
}
 
fun main(args: Array<String>) {
    val hofstadterQ = hofstadterQ()
    for (i in 1..10) {
        println("Q($i) = ${hofstadterQ(i)}")
    }
    println("Q(1000) = ${hofstadterQ(1000)}")
}

fun sum(array: List<Int>): Int {
    return array.reduce { a, b -> a + b }
}
 
fun square(x: Int): Int {
    return x * x
}
 
fun mean(array: List<Int>): Int {
    return sum(array) / array.size
}
 
fun averageSquareDiff(a: Int, predictions: List<Int>): Int {
    return mean(predictions.map { x -> square(x - a) })
}
 
fun diversityTheorem(truth: Int, predictions: List<Int>): Map<String, Int> {
    val average = mean(predictions)
    return mapOf(
        "average-error" to averageSquareDiff(truth, predictions),
        "crowd-error" to square(truth - average),
        "diversity" to averageSquareDiff(average, predictions)
    )
}
 
fun main(args: Array<String>) {
    println(diversityTheorem(49, listOf(48, 47, 51)))
    println(diversityTheorem(49, listOf(48, 47, 51, 42)))
}

import java.util.Arrays
 
fun nextInCycle(self: IntArray, index: Int): Int {
    return self[index % self.size]
}
 
fun kolakoski(self: IntArray, len: Int): IntArray {
    val s = IntArray(len)
    var i = 0
    var k = 0
    while (i < len) {
        s[i] = nextInCycle(self, k)
        if (s[k] > 1) {
            var j = 0
            while (j < s[k] - 1) {
                if (++i == len) return s
                s[i] = s[i - 1]
                j++
            }
        }
        if (++i == len) return s
        k++
    }
    return s
}
 
fun possibleKolakoski(self: IntArray): Boolean {
    val rle = IntArray(self.size)
    var prev = self[0]
    var count = 1
    var pos = 0
    for (i in 1 until self.size) {
        if (self[i] == prev) {
            count++
        } else {
            rle[pos++] = count
            count = 1
            prev = self[i]
        }
    }
    // no point adding final 'count' to rle as we're not going to compare it anyway
    for (i in 0 until pos) {
        if (rle[i]!= self[i]) {
            return false
        }
    }
    return true
}
 
fun main(args: Array<String>) {
    val ias = arrayOf(
        intArrayOf(1, 2),
        intArrayOf(2, 1),
        intArrayOf(1, 3, 1, 2),
        intArrayOf(1, 3, 2, 1)
    )
    val lens = intArrayOf(20, 20, 30, 30)
 
    for (i in ias.indices) {
        val len = lens[i]
        val kol = kolakoski(ias[i], len)
 
        println("First $len members of the sequence generated by ${Arrays.toString(ias[i])}: ")
        println(Arrays.toString(kol))
        println("Possible Kolakoski sequence? ${possibleKolakoski(kol)}\n")
    }
}

import kotlin.math.sqrt
 
fun main() {
    val MU_MAX = 1000000
    val mu = IntArray(MU_MAX + 1)
    val sqroot = sqrt(MU_MAX.toDouble()).toInt()
 
    for (i in 0 until MU_MAX) {
        mu[i] = 1
    }
 
    for (i in 2..sqroot) {
        if (mu[i] == 1) {
            for (j in i..MU_MAX step i) {
                mu[j] *= -i
            }
            for (j in i * i..MU_MAX step i * i) {
                mu[j] = 0
            }
        }
    }
 
    for (i in 2..MU_MAX) {
        if (mu[i] == i) {
            mu[i] = 1
        } else if (mu[i] == -i) {
            mu[i] = -1
        } else if (mu[i] < 0) {
            mu[i] = 1
        } else if (mu[i] > 0) {
            mu[i] = -1
        }
    }
 
    println("First 199 terms of the möbius function are as follows:\n    ")
    for (i in 1..199) {
        print(String.format("%2d  ", mu[i]))
        if ((i + 1) % 20 == 0) {
            println()
        }
    }
}

import kotlin.collections.*
import kotlin.math.*
import kotlin.sequences.*
import kotlin.text.*
 
// Generates a lookup table for the checksums of all 8-bit values.
fun generate_crc_lookup_table(): Array<UInt> {
  val reversed_polynomial = 0xEDB88320uL
 
  // This is a function object that calculates the checksum for a value,
  // then increments the value, starting from zero.
  class byte_checksum {
    operator fun invoke(): UInt {
      val checksum = n++
 
      for (i in 0..7)
        checksum = (checksum shr 1) xor ((checksum and 0x1u) * reversed_polynomial)
 
      return checksum
    }
 
    var n = 0u
  }
 
  val table = Array<UInt>(256) { 0u }
  for (i in 0..255)
    table[i] = byte_checksum()()
 
  return table
}
 
// Calculates the CRC for any sequence of values. (You could use type traits and a
// static assert to ensure the values can be converted to 8 bits.)
fun <T> crc(first: Int, last: Int, values: Array<T>): UInt {
  // Generate lookup table only on first use then cache it - this is thread-safe.
  val table = generate_crc_lookup_table()
 
  // Calculate the checksum - make sure to clip to 32 bits, for systems that don't
  // have a true (fast) 32-bit type.
  return 0xFFFFFFFFu and
    values.slice(first..last).fold(0xFFFFFFFFu and 0u) { checksum, value ->
      table[(checksum xor value.toString().toInt()) and 0xFFu] xor (checksum shr 8)
    }
}
 
fun main() {
  val s = "The quick brown fox jumps over the lazy dog"
 
  println("%08X".format(crc(0, s.length - 1, s.toCharArray())))
}

import java.util.*
 
fun main(args: Array<String>) {
	var w = 0
	var h = 0
	var pix: ByteArray? = null
	fun refresh(x: Int, y: Int) {
		var i: Int
		var j: Int
		var k: Int
		print("\u001B[H")
		for (i in 0..h - 1) {
			for (j in 0..w - 1) {
				k = i * w + j
				print(if (pix!![k]!= 0.toByte()) '#' else'')
			}
			println()
		}
	}
	fun walk() {
		var dx = 0
		var dy = 1
		var i: Int
		var k: Int
		var x = w / 2
		var y = h / 2
		pix = ByteArray(w * h)
		print("\u001B[H\u001B[J")
		while (true) {
			i = y * w + x
			if (pix!![i]!= 0.toByte()) {
				k = dx
				dx = -dy
				dy = k
			} else {
				k = dy
				dy = -dx
				dx = k
			}
			pix!![i] = (pix!![i] xor 1).toByte()
			print("\u001B[" + (y + 1) + ";" + (x + 1) + "H" + if (pix!![i]!= 0.toByte()) '#' else'')
			x += dx
			y += dy
			k = 0
			if (x < 0) {
				System.arraycopy(pix, 1, pix, 0, w * h - 1)
				for (i in 0..w * h - 1 step w) {
					pix!![i] = 0
				}
				x++
				k = 1
			} else if (x >= w) {
				System.arraycopy(pix, 1, pix, 0, w * h - 1)
				for (i in w - 1..w * h - 1 step w) {
					pix!![i] = 0
				}
				x--
				k = 1
			}
			if (y >= h) {
				System.arraycopy(pix, w, pix, 0, w * (h - 1))
				Arrays.fill(pix, w * (h - 1), w * h, 0.toByte())
				y--
				k = 1
			} else if (y < 0) {
				System.arraycopy(pix, w, pix, 0, w * (h - 1))
				Arrays.fill(pix, 0, w, 0.toByte())
				y++
				k = 1
			}
			if (k == 1) {
				refresh(x, y)
			}
			print("\u001B[" + (y + 1) + ";" + (x + 1) + "H\u001B[31m@\u001B[m")
			System.out.flush()
			Thread.sleep(10)
		}
	}
	if (args.size > 0) {
		w = Integer.parseInt(args[0])
	}
	if (args.size > 1) {
		h = Integer.parseInt(args[1])
	}
	if (w < 40) {
		w = 40
	}
	if (h < 25) {
		h = 25
	}
	walk()
}

fun main(args: Array<String>) {
    for (n in arrayOf(12, 1048576, 9e18, -2, 0)) {
        println(say(n))
    }
}
 
val small = arrayOf("zero", "one", "two", "three", "four", "five", "six",
        "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen",
        "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen")
val tens = arrayOf("", "", "twenty", "thirty", "forty",
        "fifty", "sixty", "seventy", "eighty", "ninety")
val illions = arrayOf("", " thousand", " million", " billion",
        " trillion", " quadrillion", " quintillion")
 
fun say(n: Long): String {
    var t = ""
    if (n < 0) {
        t += "negative "
        // Note, for math.MinInt64 this leaves n negative.
        n = -n
    }
    when {
        n < 20 -> t += small[n.toInt()]
        n < 100 -> {
            t += tens[n.toInt() / 10]
            val s = n % 10
            if (s > 0) {
                t += "-" + small[s.toInt()]
            }
        }
        n < 1000 -> {
            t += small[n.toInt() / 100] + " hundred"
            val s = n % 100
            if (s > 0) {
                t += " " + say(s)
            }
        }
        else -> {
            // work right-to-left
            var sx = ""
            var i = 0
            while (n > 0) {
                val p = n % 1000
                n /= 1000
                if (p > 0) {
                    val ix = say(p) + illions[i]
                    if (sx!= "") {
                        ix += " " + sx
                    }
                    sx = ix
                }
                i++
            }
            t += sx
        }
    }
    return t
}

fun montyhall(tests: Int = 1000, doors: Int = 3): Map<String, String> {
    var prizeDoor: Int
    var chosenDoor: Int
    var shownDoor: Int
    var switchDoor: Int
    var chosenWins = 0
    var switchWins = 0
    fun pick(excludeA: Int, excludeB: Int): Int {
        var door: Int
        do {
            door = (Math.random() * doors).toInt()
        } while (door == excludeA || door == excludeB)
        return door
    }
    for (i in 0..tests) {
        prizeDoor = pick(0, 0)
        chosenDoor = pick(0, 0)
        shownDoor = pick(prizeDoor, chosenDoor)
        switchDoor = pick(chosenDoor, shownDoor)
        if (chosenDoor == prizeDoor) {
            chosenWins++
        } else if (switchDoor == prizeDoor) {
            switchWins++
        }
    }
    return mapOf("stayWins" to chosenWins.toString() + " " + (100 * chosenWins / tests).toString() + "%", "switchWins" to switchWins.toString() + " " + (100 * switchWins / tests).toString() + "%")
}

import java.util.HashMap
import java.util.Scanner
 
class Data(var ptr: Int, var cells: HashMap<Int, Int>)
 
fun incPtr(nextCmd: (Data) -> Data): (Data) -> Data = { data -> nextCmd(data.copy(ptr = data.ptr + 1)) }
 
fun decPtr(nextCmd: (Data) -> Data): (Data) -> Data = { data -> nextCmd(data.copy(ptr = data.ptr - 1)) }
 
fun incCell(nextCmd: (Data) -> Data): (Data) -> Data = { data -> nextCmd(data.copy(cells = data.cells.plus(data.ptr to (data.cells[data.ptr]?: 0) + 1))) }
 
fun decCell(nextCmd: (Data) -> Data): (Data) -> Data = { data -> nextCmd(data.copy(cells = data.cells.plus(data.ptr to (data.cells[data.ptr]?: 0) - 1))) }
 
fun outputCell(nextCmd: (Data) -> Data): (Data) -> Data = { data -> nextCmd(data).also { print(data.cells[data.ptr]?: 0) } }
 
fun inputCell(nextCmd: (Data) -> Data): (Data) -> Data = { data -> nextCmd(data.copy(cells = data.cells.plus(data.ptr to readLine()!!.toInt()))) }
 
fun ifLoop(nextCmd: (Data) -> Data, loopCmd: (Data) -> Data): (Data) -> Data = { data -> nextCmd(data.copy(cells = data.cells.plus(data.ptr to (data.cells[data.ptr]?: 0)))) }
 
fun terminate(data: Data): Data = data
 
fun splitCmds(cmds: String): Pair<String, String> {
    var loopCmds = ""
    var i = 0
    while (i < cmds.length) {
        when (cmds[i]) {
            '[' -> {
                val (cmd, loopCmd) = splitCmds(cmds.substring(i + 1))
                i += cmd.length + 1
                loopCmds += "$cmd[$loopCmd]"
            }
            ']' -> return cmds.substring(i + 1) to loopCmds
            else -> loopCmds += cmds[i]
        }
        i++
    }
    throw Exception("invalid commands: missing ]")
}
 
fun compileCmds(cmds: String): (Data) -> Data = { data ->
    if (cmds.isEmpty()) terminate(data)
    else when (cmds[0]) {
        '>' -> incPtr(compileCmds(cmds.substring(1)))(data)
        '<' -> decPtr(compileCmds(cmds.substring(1)))(data)
        '+' -> incCell(compileCmds(cmds.substring(1)))(data)
        '-' -> decCell(compileCmds(cmds.substring(1)))(data)
        '.' -> outputCell(compileCmds(cmds.substring(1)))(data)
        ',' -> inputCell(compileCmds(cmds.substring(1)))(data)
        '[' -> {
            val (cmd, loopCmd) = splitCmds(cmds.substring(1))
            ifLoop(compileCmds(cmd), compileCmds(loopCmd))(data)
        }
        ']' -> throw Exception("invalid commands: missing [")
        else -> compileCmds(cmds.substring(1))(data)
    }
}
 
fun compileAndRun(cmds: String, input: List<Int>) {
    var data = Data(0, hashMapOf())
    var i = 0
    while (i < input.size) {
        data = data.copy(cells = data.cells.plus(data.ptr to input[i]))
        i++
    }
    val compiledCmds = compileCmds(cmds)
    compiledCmds(data)
    println()
    println(data.cells.values.joinToString())
