fun main(args: Array<String>) {
    val shift: Int = try {
        args[0].toInt()
    } catch (e: NumberFormatException) {
        exitErr("No shift provided", 2)
    }
 
    val plain = getInput()?: exitErr("No input provided", 3)
 
    val cipher = plain.map {
        val case = if (it.isUpperCase()) 'A' else 'a'
        if (it.isLetter()) ((it - case + shift) % 26 + case).toChar() else it
    }.joinToString("")
 
    println("Cipher text: $cipher")
}
 
