    cocktailSort(a)
    println("after: " + Arrays.toString(a))
}
 
fun cocktailSort(a: Array<Int>) {
    val last = a.size - 1
    while (true) {
        var swapped = false
        for (i in 0 until last) {
            if (a[i] > a[i + 1]) {
                val temp = a[i]
                a[i] = a[i + 1]
                a[i + 1] = temp
                swapped = true
            }
        }
        if (!swapped) {
            return
        }
        swapped = false
        for (i in last - 1 downTo 0) {
            if (a[i] > a[i + 1]) {
                val temp = a[i]
                a[i] = a[i + 1]
                a[i + 1] = temp
                swapped = true
            }
        }
        if (!swapped) {
            return
        }
    }
}

import java.util.Arrays
 
fun merge(a: IntArray, n: Int, m: Int) {
    var i = 0
    var j = m
    var k = 0
    val x = IntArray(n)
    while (k < n) {
        x[k] = if (j == n) {
            a[i++]
        } else if (i == m) {
            a[j++]
        } else if (a[j] < a[i]) {
            a[j++]
        } else {
            a[i++]
        }
        k++
    }
    for (i in 0 until n) {
        a[i] = x[i]
    }
}
 
fun mergeSort(a: IntArray, n: Int) {
    if (n < 2) {
        return
    }
    val m = n / 2
    mergeSort(a, m)
    mergeSort(a.copyOfRange(m, n), n - m)
    merge(a, n, m)
}
 
