    }
  }
}

import java.util.ArrayList
import java.util.List

class Bell {
    private class BellTriangle {
        private val arr: List<Int>

        constructor(n: Int) {
            val length = n * (n + 1) / 2
            arr = ArrayList(length)
            for (i in 0 until length) {
                arr.add(0)
            }

            set(1, 0, 1)
            for (i in 2..n) {
                set(i, 0, get(i - 1, i - 2))
                for (j in 1 until i) {
                    val value = get(i, j - 1) + get(i - 1, j - 1)
                    set(i, j, value)
                }
            }
        }

        private fun index(row: Int, col: Int): Int {
            if (row > 0 && col >= 0 && col < row) {
                return row * (row - 1) / 2 + col
            } else {
                throw IllegalArgumentException()
            }
        }

        fun get(row: Int, col: Int): Int {
            val i = index(row, col)
            return arr[i]
        }

        fun set(row: Int, col: Int, value: Int) {
            val i = index(row, col)
            arr[i] = value
        }
    }

    companion object {
        @JvmStatic
        fun main(args: Array<String>) {
            val rows = 15
            val bt = BellTriangle(rows)

            println("First fifteen Bell numbers:")
            for (i in 0 until rows) {
                println(String.format("%2d: %d", i + 1, bt.get(i + 1, 0)))
            }

            for (i in 1..10) {
                print(bt.get(i, 0))
                for (j in 1 until i) {
                    print(String.format(", %d", bt.get(i, j)))
                }
                println()
            }
        }
    }
}

