	println("Unsorted: " + Arrays.toString(a))
	val sorted = pSort(a)
	println("Sorted: " + Arrays.toString(sorted))
}
 
fun pSort(a: IntArray): IntArray {
	val list = ArrayList<IntArray>()
	permute(a, a.size, list)
	for (x in list) {
		if (isSorted(x)) {
			return x
		}
	}
	return a
}
 
private fun permute(a: IntArray, n: Int, list: MutableList<IntArray>) {
	if (n == 1) {
		val b = IntArray(a.size)
		System.arraycopy(a, 0, b, 0, a.size)
		list.add(b)
		return
	}
	for (i in 0 until n) {
		swap(a, i, n - 1)
		permute(a, n - 1, list)
		swap(a, i, n - 1)
	}
}
 
private fun isSorted(a: IntArray): Boolean {
	for (i in 1 until a.size) {
		if (a[i - 1] > a[i]) {
			return false
		}
	}
	return true
}
 
private fun swap(arr: IntArray, i: Int, j: Int) {
	val temp = arr[i]
	arr[i] = arr[j]
	arr[j] = temp
}

fun <T> knuthShuffle(begin: RandomAccessIterator<T>, end: RandomAccessIterator<T>) {
    for (n in end - begin - 1 downTo 1) {
        val k = rand() % (n + 1)
        if (k!= n) {
            begin.iter_swap(k, n)
        }
    }
}

data class Point(val x: Int, val y: Int) {
    fun shoelace(other: Point) = x * other.y - y * other.x
}

class Polygon(vararg coords: Pair<Int, Int>) {
    private val points = coords.map { Point(it.first, it.second) }

    fun area(): Double {
        val points = points + points.first()
        return points.windowed(2).sumByDouble { it[0].shoelace(it[1]).toDouble() }.absoluteValue / 2
    }
}

