fun ffr(n: Int): Int {
    if (n < 1 || n!is Int) throw IllegalArgumentException("n must be an int >= 1")
    return try {
        ffr.r[n]
    } catch (e: IndexOutOfBoundsException) {
        val r = ffr.r
        val s = ffs.s
        val ffr_n_1 = ffr(n - 1)
        val lastr = r[r.lastIndex]
        // extend s up to, and one past, last r
        s += (s.last() + 1 until lastr).toList()
        if (s.last() < lastr) s += lastr + 1
        // access s[n-1] temporarily extending s if necessary
        val len_s = s.size
        val ffs_n_1 = if (len_s > n) s[n - 1] else (n - len_s) + s.last()
        val ans = ffr_n_1 + ffs_n_1
        r += ans
        ans
    }
}

val ffr.r: MutableList<Int>
    get() = mutableListOf(null, 1)

fun ffs(n: Int): Int {
    if (n < 1 || n!is Int) throw IllegalArgumentException("n must be an int >= 1")
    return try {
        ffs.s[n]
    } catch (e: IndexOutOfBoundsException) {
        val r = ffr.r
        val s = ffs.s
        for (i in r.size until n + 2) {
            ffr(i)
            if (s.size > n) return s[n]
        }
        throw Exception("Whoops!")
    }
}

val ffs.s: MutableList<Int>
    get() = mutableListOf(null, 2)

fun main() {
    val first10 = (1..10).map { ffr(it) }
    assert(first10 == listOf(1, 3, 7, 12, 18, 26, 35, 45, 56, 69)) { "ffr() value error(s)" }
    println("ffr(n) for n = [1..10] is $first10")
    //
    val bin = mutableListOf(null) + MutableList(1000) { 0 }
    for (i in 40 downTo 1) bin[ffr(i)]++
    for (i in 960 downTo 1) bin[ffs(i)]++
    if (bin.subList(1, 1000).all { it == 1 }) println("All Integers 1..1000 found OK")
    else println("All Integers 1..1000 NOT found only once: ERROR")
}

class ZigZagMatrix(n: Int) : Matrix(n, n) {
    init {
        var i = 1
        var j = 1
        for (e in 0 until n * n) {
            mtx[i - 1][j - 1] = e
            if ((i + j) % 2 == 0) {
                // Even stripes
                if (j < n) j++ else i += 2
                if (i > 1) i--
            } else {
                // Odd stripes
                if (i < n) i++ else j += 2
                if (j > 1) j--
            }
        }
    }
}
 
