import java.util.regex.Pattern
import java.util.regex.Matcher
 
fun is_repstring(teststring: String, repunit: String): Boolean {
    val regex = "^(.+)\\1+(.*)$"
    val e = Pattern.compile(regex)
    val what = e.matcher(teststring)
    if (what.matches()) {
        val firstbracket = what.group(1)
        val secondbracket = what.group(2)
        if (firstbracket.length >= secondbracket.length && firstbracket.contains(secondbracket)) {
            repunit = firstbracket
        }
    }
    return!repunit.isEmpty()
}
 
fun main(args: Array<String>) {
    val teststrings = arrayOf("1001110011", "1110111011", "0010010010", "1010101010", "1111111111", "0100101101", "0100100", "101", "11", "00", "1")
    var theRep = ""
    for (myString in teststrings) {
        if (is_repstring(myString, theRep)) {
            println(myString + " is a rep string! Here is a repeating string:")
            println(theRep)
        } else {
            println(myString + " is no rep string!")
        }
        theRep = ""
    }
}

