fun main() {
    println("Calculating the first $NUMBER_OF_CUBAN_PRIMES cuban primes and the $LAST_CUBAN_PRIME th cuban prime...")
    val elapsed = measureTimeMillis {
        val cubanPrimes = IntStream.iterate(1, { it + 1 })
           .map { it.toLong() }
           .map { it.pow(3) - (it - 1).pow(3) }
           .filter { it.isPrime() }
           .limit(LAST_CUBAN_PRIME.toLong())
           .toList()
 
        println("THE $NUMBER_OF_CUBAN_PRIMES FIRST CUBAN PRIMES:")
        cubanPrimes.stream()
           .limit(NUMBER_OF_CUBAN_PRIMES.toLong())
           .map { it.toString() }
           .collect(Collectors.joining("\t"))
           .chunked(COLUMNS)
           .forEach { println(it) }
 
        println("The $LAST_CUBAN_PRIME th cuban prime number is ${cubanPrimes.last()}")
    }
    println("Elapsed time: $elapsed ms")
}
 
fun Long.isPrime(): Boolean {
    if (this <= 1) return false
    if (this <= 3) return true
    if (this % 2 == 0L || this % 3 == 0L) return false
    var i = 5
    while (i * i <= this) {
        if (this % i == 0L || this % (i + 2) == 0L) return false
        i += 6
    }
    return true
}
 
fun Long.pow(n: Long): Long {
    var result = 1L
    var base = this
    var exponent = n
    while (exponent > 0) {
        if (exponent % 2 == 1L) result *= base
        exponent /= 2
        base *= base
    }
    return result
}

