fun digitalRoot(n: Int): Pair<Int, Int> {
    var ap = 0
    var n = Math.abs(n)
    while (n >= 10) {
        n = n.toString().sumBy { it.toString().toInt() }
        ap++
    }
    return Pair(ap, n)
}
 
