val Sedol_char = "0123456789BCDFGHJKLMNPQRSTVWXYZ"
val Sedolweight = intArrayOf(1, 3, 1, 7, 3, 9)
 
fun char2value(c: Char): Int {
    if (!Sedol_char.contains(c)) {
        throw IllegalArgumentException("Invalid char $c")
    }
    return parseInt(c.toString(), 36)
}
 
fun checksum(sedol: String): String {
    if (sedol.length!= Sedolweight.size) {
        throw IllegalArgumentException("Invalid length")
    }
    val sum = IntStream.range(0, sedol.length)
           .map { char2value(sedol[it]) * Sedolweight[it] }
           .sum()
    return format("%d", floorMod(10 - sum % 10, 10))
}
 
