    println("Done")
}
 
fun doEncDec(source: String, target: String, isEncrypt: Boolean) {
    val trans: ITransform = if (isEncrypt) Encrypt() else Decrypt()
    val sfi = File(source)
    val sstream = FileInputStream(sfi)
    val sr = Scanner(sstream, StandardCharsets.UTF_8)
    val tfi = File(target)
    val tstream = FileOutputStream(tfi)
    val tw = TransformWriter(tstream, trans)
    val sw = tw.writer()
    while (sr.hasNextLine()) {
        sw.write(sr.nextLine())
    }
    sw.close()
}
 
interface ITransform {
    fun transform(ch: Byte): Byte
}
 
class Encrypt : ITransform {
    companion object {
        const val str = "xyfagchbimpourvnqsdewtkjzl"
    }
 
    override fun transform(ch: Byte): Byte {
        return if (ch.isLowerCase()) str[ch - 'a'.toByte()].toByte() else ch
    }
}
 
class Decrypt : ITransform {
    companion object {
        const val str = "xyfagchbimpourvnqsdewtkjzl"
    }
 
    override fun transform(ch: Byte): Byte {
        return if (ch.isLowerCase()) (str.indexOf(ch.toChar()) + 'a'.toInt()).toByte() else ch
    }
}
 
class TransformWriter(outs: OutputStream, private val trans: ITransform) : OutputStream() {
    private val outs: OutputStream = outs
 
    override fun write(buf: ByteArray, off: Int, len: Int) {
        for (i in off until off + len) {
            buf[i] = trans.transform(buf[i])
        }
        outs.write(buf, off, len)
    }
 
    override fun flush() {
        outs.flush()
    }
 
    override fun close() {
        outs.close()
    }
 
    fun writer(charset: Charset = StandardCharsets.UTF_8): Writer {
        return outs.writer(charset)
    }
}

