fun egcd(a: Long, b: Long): Triple<Long, Long, Long> {
    return if (a == 0L) Triple(b, 0L, 1L) else {
        val (g, x, y) = egcd(b % a, a)
        Triple(g, y - (b / a) * x, x)
    }
}
 
fun modInv(x: Long, n: Long): Long? {
    val (g, x, _) = egcd(x, n)
    return if (g == 1L) (x % n + n) % n else null
}
 
fun chineseRemainder(residues: LongArray, modulii: LongArray): Long? {
    val prod = modulii.fold(1L) { acc, i -> acc * i }
 
    var sum = 0L
 
    for (i in residues.indices) {
        val p = prod / modulii[i]
        sum += residues[i] * modInv(p, modulii[i])!! * p
    }
 
    return sum % prod
}
 
fun main() {
    val modulii = longArrayOf(3, 5, 7)
    val residues = longArrayOf(2, 3, 2)
 
    val sol = chineseRemainder(residues, modulii)
    println(sol)
}

