import kotlin.math.sqrt
 
fun solvePell(n: Int): Pair<Long, Long> {
    var x = sqrt(n.toDouble()).toInt()
 
    if (x * x == n) {
        // n is a perfect square - no solution other than 1,0
        return Pair(1, 0)
    }
 
    // there are non-trivial solutions
    var y = x
    var z = 1
    var r = 2 * x
    var e = Pair(1, 0)
    var f = Pair(0, 1)
    var a = 0L
    var b = 0L
 
    while (true) {
        y = r * z - y
        z = (n - y * y) / z
        r = (x + y) / z
        e = Pair(f.second, r * f.second + e.second)
        f = Pair(f.second, r * f.second + f.second)
        a = e.second + x * f.second
        b = f.second
        if (a * a - n * b * b == 1L) {
            break
        }
    }
 
    return Pair(a, b)
}
 
fun test(n: Int) {
    val r = solvePell(n)
    println("x^2 - ${"%3d".format(n)} * y^2 = 1 for x = ${"%21d".format(r.first)} and y = ${"%21d".format(r.second)}")
}
 
