fun gcd(n: Int, k: Int): Int {
    if (n < k || k < 1) {
        throw IllegalArgumentException("Need n >= k and k >= 1")
    }

    var s = 1
    while (n and 1 == 0 && k and 1 == 0) {
        n = n shr 1
        k = k shr 1
        s = s shl 1
    }

    var t = n
    if (n and 1!= 0) {
        t = -k
    }
    while (t!= 0) {
        while (t and 1 == 0) {
            t = t shr 1
        }
        if (t > 0) {
            n = t
        } else {
            k = -t
        }
        t = n - k
    }
    return n * s
}

fun totient(n: Int): Int {
    var tot = 0
    for (k in 1..n) {
        if (gcd(n, k) == 1) {
            tot++
        }
    }
    return tot
}

fun main(args: Array<String>) {
    val perfect = mutableListOf<Int>()
    for (n in 1..Int.MAX_VALUE step 2) {
        var tot = n
        var sum = 0
        while (tot!= 1) {
            tot = totient(tot)
            sum += tot
        }
        if (sum == n) {
            perfect.add(n)
        }
        if (perfect.size == 20) {
            break
        }
    }
    println("The first 20 perfect totient numbers are:")
    println(perfect)
}

import kotlin.system.exitProcess
 
val HIST = mutableMapOf<String, MutableList<Any>>()
 
fun trace(frame: Any, event: String, arg: Any): Any {
    val locals = frame.javaClass.getDeclaredField("f_locals").get(frame) as Map<String, Any>
    for ((name, val) in locals) {
        if (name!in HIST) {
            HIST[name] = mutableListOf()
        } else {
            if (HIST[name]!!.last() == val) {
                continue
            }
        }
        HIST[name]!!.add(val)
    }
    return ::trace
}
 
fun undo(name: String): Any {
    HIST[name]!!.removeAt(HIST[name]!!.lastIndex)
    return HIST[name]!![HIST[name]!!.lastIndex]
}
 
