fun getPairs(max: Int): List<Pair<Int, Int>> {
    val divsums = IntArray(max + 1)
    for (i in 0..max) {
        divsums[i] = properDivisors(i).sum()
    }
    val pairs = ArrayList<Pair<Int, Int>>()
    for (i in 1..max) {
        val sum = divsums[i]
        if (i < sum && sum <= max && divsums[sum] == i) {
            pairs.add(Pair(i, sum))
        }
    }
    return pairs
}
 
fun properDivisors(number: Int): List<Int> {
    val divisors = ArrayList<Int>()
    for (divisor in 1..number / 2) {
        if (number % divisor == 0) {
            divisors.add(divisor)
        }
    }
    return divisors
}

import java.awt.Color
import java.awt.image.BufferedImage
import java.io.File
import java.util.*
import javax.imageio.ImageIO
 
const val w = 400     // image width
const val h = 300     // image height
const val n = 15000   // number of particles to add
const val frost = 255 // white
 
var g: BufferedImage? = null
 
fun main(args: Array<String>) {
    g = BufferedImage(w, h, BufferedImage.TYPE_BYTE_GRAY)
    // off center seed position makes pleasingly asymetrical tree
    g!!.setRGB(w/3, h/3, Color.WHITE.rgb)
generate:
    for (a in 0 until n) {
        // generate random position for new particle
        val rp = RandomPosition()
        if (g!!.getRGB(rp.x, rp.y) == Color.WHITE.rgb) {
            // position is already set.  find a nearby free position.
            while (true) {
                rp.x += Random.nextInt(3) - 1
                rp.y += Random.nextInt(3) - 1
                // execpt if we run out of bounds, consider the particle lost.
                if (!rp.inBounds()) {
                    continue@generate
                }
                if (g!!.getRGB(rp.x, rp.y)!= Color.WHITE.rgb) {
                    break
                }
            }
        } else {
            // else particle is in free space.  let it wander
            // until it touches tree
            while (!hasNeighbor(rp)) {
                rp.x += Random.nextInt(3) - 1
                rp.y += Random.nextInt(3) - 1
                // but again, if it wanders out of bounds consider it lost.
                if (!rp.inBounds()) {
                    continue@generate
                }
            }
        }
        // x, y now specify a free position toucing the tree.
        g!!.setRGB(rp.x, rp.y, Color.WHITE.rgb)
        a++
        // progress indicator
        if (a % 100 == 0) {
            println("$a of $n")
        }
    }
    ImageIO.write(g, "png", File("tree.png"))
}
 
val n8 = arrayOf(
    intArrayOf(-1, -1), intArrayOf(-1, 0), intArrayOf(-1, 1),
    intArrayOf(0, -1), intArrayOf(0, 1),
    intArrayOf(1, -1), intArrayOf(1, 0), intArrayOf(1, 1))
 
fun hasNeighbor(p: RandomPosition): Boolean {
    for (n in n8) {
        val o = p.add(n)
        if (o.inBounds() && g!!.getRGB(o.x, o.y) == Color.WHITE.rgb) {
            return true
        }
    }
    return false
}
 
class RandomPosition {
    var x: Int = 0
    var y: Int = 0
 
    init {
        x = Random.nextInt(w)
        y = Random.nextInt(h)
    }
 
    fun add(n: IntArray): RandomPosition {
        val p = RandomPosition()
        p.x = x + n[0]
        p.y = y + n[1]
        return p
    }
 
    fun inBounds(): Boolean {
        return x >= 0 && x < w && y >= 0 && y < h
    }
}

fun time2deg(t: String): Double {
    val m = Regex("^(\\d\\d):(\\d\\d):(\\d\\d)$").matchEntire(t)
    if (m == null) {
        throw IllegalArgumentException("invalid time")
    }
    val hh = m.groupValues[1].toInt()
    val mm = m.groupValues[2].toInt()
    val ss = m.groupValues[3].toInt()
    if (!(0..23).contains(hh) && (0..59).contains(mm) && (0..59).contains(ss)) {
        throw IllegalArgumentException("invalid time")
    }
    return (hh * 3600 + mm * 60 + ss) * 360 / 86400.0
}
 
fun deg2time(d: Double): String {
    val sec = (d % 360) * 86400 / 360.0
    return "%02d:%02d:%02d".format(sec / 3600, (sec % 3600) / 60, sec % 60)
}
 
fun mean_time(times: List<String>): String {
    return deg2time(mean_angle(times.map { time2deg(it) }))
}
 
