fun main(args: Array<String>) {
    val recip = Rat()
    val max = 1 shl 19
    for (candidate in 2 until max) {
        var sum = Rat(1, candidate)
        val max2 = Math.sqrt(candidate.toDouble()).toInt()
        for (factor in 2..max2) {
            if (candidate % factor == 0) {
                sum = sum.add(recip.setFrac64(1, factor))
                if (factor * factor!= candidate) {
                    sum = sum.add(recip.setFrac64(1, candidate / factor))
                }
            }
        }
        if (sum.denom().toLong() == 1L) {
            var perfectstring = ""
            if (sum.num().toLong() == 1L) {
                perfectstring = "perfect!"
            }
            println("Sum of recipr. factors of $candidate = ${sum.num().toLong()} exactly $perfectstring")
        }
    }
}

fun fib(a: Int): Int {
