val CHR = arrayOf("ABCDEFGHIJKLMNOPQRSTUVWXYZ", "abcdefghijklmnopqrstuvwxyz", "0123456789", "!\"#$%&'()*+,-./:;<=>?@[]^_{|}~")
val UNS = "O0l1I5S2Z"
 
fun createPW(len: Int, safe: Boolean): String {
    val pw = StringBuilder()
    var t: Char
    for (x in 0 until len step 4) {
        for (y in x until x + 4 && y < len) {
            do {
                t = CHR[y % 4][Random().nextInt(CHR[y % 4].length)]
            } while (safe && UNS.indexOf(t)!= -1)
            pw.append(t)
        }
    }
    pw.shuffle()
    return pw.toString()
}
 
fun generate(len: Int, count: Int, safe: Boolean) {
    for (c in 0 until count) {
        println(createPW(len, safe))
    }
    println("\n\n")
}

import java.io.File
import java.io.FileNotFoundException
import java.util.*
 
const val FILENAME = "readings.txt"
const val READINGS = 24 // per line
const val FIELDS = READINGS * 2 + 1 // per line
 
fun main(args: Array<String>) {
	val file = File(FILENAME)
	var badRun = 0
	var maxRun = 0
	var badDate = ""
	var maxDate = ""
	var fileSum = 0.0
	var fileAccept = 0
	try {
		Scanner(file).use { scanner ->
			while (scanner.hasNextLine()) {
				val f = scanner.nextLine().split(" ")
				if (f.size!= FIELDS) {
					throw RuntimeException("unexpected format, ${f.size} fields.")
				}
				var accept = 0
				var sum = 0.0
				for (i in 1 until FIELDS step 2) {
					val flag = f[i + 1].toInt()
					if (flag <= 0) { // value is bad
						if (++badRun == 1) {
							badDate = f[0]
						}
					} else { // value is good
						if (badRun > maxRun) {
							maxRun = badRun
							maxDate = badDate
						}
						badRun = 0
						val value = f[i].toDouble()
						sum += value
						accept++
					}
				}
				println("Line: ${f[0]}  Reject ${READINGS - accept}  Accept: $accept  Line_tot: ${"%9.3f".format(sum)}")
				if (accept > 0) {
					println("  Line_avg: ${"%8.3f".format(sum / accept)}")
				}
				fileSum += sum
				fileAccept += accept
			}
		}
	} catch (e: FileNotFoundException) {
		e.printStackTrace()
	}
	if (badRun > maxRun) {
		maxRun = badRun
		maxDate = badDate
	}
	println("\nFile     = $FILENAME")
	println("Total    = ${"%.3f".format(fileSum)}")
	println("Readings = $fileAccept")
	if (fileAccept > 0) {
		println("Average  = ${"%.3f".format(fileSum / fileAccept)}")
	}
	if (maxRun == 0) {
		println("\nAll data valid.")
	} else {
		println("\nMax data gap = $maxRun, beginning on line $maxDate.")
	}
}

fun mcnugget(limit: Int): Int {
    val sv = (0..limit).toList()

    (0..limit).step(6).forEach { s ->
        (0..limit).step(9).forEach { n ->
            (0..limit).step(20).forEach { t ->
                sv.remove(s + n + t)
            }
        }
    }

    return sv.max()!!
}

