fun main(args: Array<String>) {
    val input = """49927398716
49927398717
1234567812345678
1234567812345670"""
    val t = intArrayOf(0, 2, 4, 6, 8, 1, 3, 5, 7, 9)
    fun luhn(s: String): Boolean {
        var odd = s.length and 1
        var sum = 0
        for (i in 0 until s.length) {
            if (s[i] < '0' || s[i] > '9') {
                return false
            }
            if (i and 1 == odd) {
                sum += t[s[i] - '0']
            } else {
                sum += s[i] - '0'
            }
        }
        return sum % 10 == 0
    }
    for (s in input.split("\n")) {
        println(s + " " + luhn(s))
    }
}

