//Helpers
fun <T> Iterable<T>.permutations(): Sequence<List<T>> =
        if (count() == 1)
            sequenceOf(this.toList())
        else
            this.flatMap { v -> this.minus(v).permutations().map { p -> p.plus(v) } }
 
fun <T> Iterable<T>.combinations(): Sequence<List<T>> =
        if (count() == 1)
            sequenceOf(this.toList())
        else
            this.flatMap { v -> this.combinations().map { p -> p.plus(v) } }
 
fun <T> Iterable<T>.combinations(numItems: Int): Sequence<List<T>> =
        this.combinations().filter { it.count() == numItems }
 
fun <T> Iterable<T>.toSingleton(): Iterable<T> = listOf(this)

