fun floyd(n: Int) {
    println("Floyd $n:")
    val lowerLeftCorner = n * (n - 1) / 2 + 1
    var lastInColumn = lowerLeftCorner
    var lastInRow = 1
    for (i in 1..n * n) {
        val w = lowerLeftCorner.toString().length
        if (i < lastInRow) {
            print(i.toString().padStart(w) + " ")
            lastInColumn++
        } else {
            println(i.toString().padStart(w))
            lastInRow += ++lastInRow
            lastInColumn = lowerLeftCorner
        }
    }
}

