fun binarySearch(nums: IntArray, check: Int): Int {
    return binarySearch(nums, check, 0, nums.size - 1)
}
 
fun binarySearch(nums: IntArray, check: Int, lo: Int, hi: Int): Int {
    if (hi < lo) {
        return -1
    }
    val guess = (lo + hi) ushr 1 // from OpenJDK
    return if (nums[guess] > check) {
        binarySearch(nums, check, lo, guess - 1)
    } else if (nums[guess] < check) {
        binarySearch(nums, check, guess + 1, hi)
    } else {
        guess
    }
}
 
