    }
}

fun isPrime(n: Int): Boolean {
    if (n < 2) {
        return false
    }
    if (n % 2 == 0) {
        return n == 2
    }
    if (n % 3 == 0) {
        return n == 3
    }
 
    var d = 5
    while (d * d <= n) {
        if (n % d == 0) {
            return false
        }
        d += 2
 
        if (n % d == 0) {
            return false
        }
        d += 4
    }
    return true
}
 
fun generatePrimes(): Sequence<Int> {
    yield(2)
    yield(3)
 
    var p = 5
    while (p > 0) {
        if (isPrime(p)) {
            yield(p)
        }
        p += 2
        if (isPrime(p)) {
            yield(p)
        }
        p += 4
    }
}
 
val transMap = mutableMapOf<Pair<Int, Int>, Int>()
var prev: Int? = null
val limit = 1000000
for (i in 0 until limit) {
    val prime = generatePrimes().iterator().next()
    if (prev!= null) {
        val transition = Pair(prev, prime % 10)
        val count = transMap.getOrPut(transition, { 0 })
        transMap[transition] = count + 1
    }
    prev = prime % 10
}
 
println("First ${limit} primes. Transitions prime % 10 > next-prime % 10.")
for (trans in transMap.keys.sorted()) {
    val count = transMap[trans]
    println("${trans.first} -> ${trans.second} count ${count} frequency: ${100.0 * count / limit}%")
}

import java.util.TreeSet
 
class Chess960 {
    private val set = TreeSet<String>()
 
    fun invoke(b: String, e: String) {
        if (e.length <= 1) {
            val s = b + e
            if (is_valid(s)) { set.add(s) }
        } else {
            for ((i, c) in e.withIndex()) {
                val b = b + c
                val e = e.substring(0, i) + e.substring(i + 1)
                invoke(b, e)
            }
        }
    }
 
    private fun is_valid(s: String): Boolean {
        val k = s.indexOf('K')
        return k > s.indexOf('R') && k < s.lastIndexOf('R') && s.indexOf('B') % 2!= s.lastIndexOf('B') % 2
    }
}
 
// Program entry point.
fun main(args: Array<String>) {
    val chess960 = Chess960()
    chess960.invoke("", "KQRRNNBB")
 
    for ((i, p) in chess960.set.withIndex()) {
        println("$i: $p")
    }
}

