fun mod(n: Int, m: Int): Int {
    return ((n % m) + m) % m
}
 
fun isPrime(n: Int): Boolean {
    if (n < 2) return false
    if (n % 2 == 0) return n == 2
    if (n % 3 == 0) return n == 3
    var d = 5
    while (d * d <= n) {
        if (n % d == 0) return false
        d += 2
        if (n % d == 0) return false
        d += 4
    }
    return true
}
 
fun carmichael(p1: Int) {
    for (h3 in 2 until p1) {
        for (d in 1 until h3 + p1) {
            if ((h3 + p1) * (p1 - 1) % d == 0 && mod(-p1 * p1, h3) == d % h3) {
                val p2 = 1 + (p1 - 1) * (h3 + p1) / d
                if (!isPrime(p2)) continue
                val p3 = 1 + p1 * p2 / h3
                if (!isPrime(p3)) continue
                if (p2 * p3 % (p1 - 1)!= 1) continue
                val c = p1 * p2 * p3
                println("%2d   %4d   %5d     %d".format(p1, p2, p3, c))
            }
        }
    }
}
 
fun main(args: Array<String>) {
    println("The following are Carmichael munbers for p1 <= 61:\n")
    println("p1     p2      p3     product")
    println("==     ==      ==     ========")
 
    for (p1 in 2..61) {
        if (isPrime(p1)) carmichael(p1)
    }
}

