import kotlin.math.max
 
fun lcs(a: String, b: String): String {
    val n = a.length
    val m = b.length
    val c = Array(n + 1) { IntArray(m + 1) }
    for (i in 1..n) {
        for (j in 1..m) {
            if (a[i - 1] == b[j - 1]) {
                c[i][j] = c[i - 1][j - 1] + 1
            } else {
                c[i][j] = max(c[i - 1][j], c[i][j - 1])
            }
        }
    }
    val s = CharArray(c[n][m])
    for (i in n downTo 1) {
        for (j in m downTo 1) {
            if (a[i - 1] == b[j - 1]) {
                s[c[i][j] - 1] = a[i - 1]
                i--
                j--
            } else if (c[i][j - 1] > c[i - 1][j]) {
                j--
            } else {
                i--
            }
        }
    }
    return String(s)
}

