import kotlin.text.*
 
fun match(s: String, p: String, overlap: Int): Int {
        var c = 0
        val l = p.length
 
        for (i in 0..s.length - 1) {
                if (s.substring(i, i + l)!= p) continue
                if (overlap == 0) i += l - 1
                c++
        }
        return c
}
 
fun main(args: Array<String>) {
        println(match("the three truths", "th", 0))
        println("overlap:" + match("abababababa", "aba", 1))
        println("not:    " + match("abababababa", "aba", 0))
}

fun lookandsay(number: String): String {
    val result = StringBuilder()
    var repeat = number[0]
    var times = 1
    for (actual in number.substring(1) + " ") {
        if (actual!= repeat) {
            result.append(times.toString() + repeat)
            times = 1
            repeat = actual
        } else {
            times += 1
        }
    }
    return result.toString()
}

