class Graph(s: String, edges: Array<IntArray>) {
    val vertices: Array<String>
    val adjacency: Array<BooleanArray>
    val numVertices: Int
 
    init {
        vertices = s.split(",".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()
        numVertices = vertices.size
        adjacency = Array(numVertices) { BooleanArray(numVertices) }
 
        for (edge in edges)
            adjacency[edge[0]][edge[1]] = true
    }
 
    fun topoSort(): List<String>? {
        val result = ArrayList<String>()
        val todo = LinkedList<Int>()
 
        for (i in 0 until numVertices)
            todo.add(i)
 
        try {
            outer@ while (todo.isNotEmpty()) {
                for (r in todo) {
                    if (!hasDependency(r, todo)) {
                        todo.remove(r)
                        result.add(vertices[r])
                        // no need to worry about concurrent modification
                        continue@outer
                    }
                }
                throw Exception("Graph has cycles")
            }
        } catch (e: Exception) {
            println(e)
            return null
        }
 
        return result
    }
 
    fun hasDependency(r: Int, todo: List<Int>): Boolean {
        for (c in todo) {
            if (adjacency[r][c])
                return true
        }
        return false
    }
}

fun main() {
    val in = BufferedReader(InputStreamReader(System.`in`))
    val blankLine = "\n"
    val printLongest: (String) -> String = { candidate: String ->
        var longest = candidate
        var s: String
        var err: Throwable? = null
        try {
            s = in.readLine()
        } catch (e: IOException) {
            err = e
        }
        try {
            blankLine[0]
            try {
                longest[s.length]
                longest = s
            } catch (e: IndexOutOfBoundsException) {
                longest = printLongest(longest)
                try {
                    s[longest.length]
                    s = ""
                } catch (e: IndexOutOfBoundsException) {
                    throw e
                }
            }
        } catch (e: IndexOutOfBoundsException) {
            throw e
        }
        System.out.print(blankLine)
        blankLine = ""
        longest
    }
    printLongest("")
}

import kotlin.math.pow
import kotlin.math.sqrt
 
fun chiDistance(dataset: List<Int>): Double {
    val expected = dataset.sum() / dataset.size.toDouble()
    return dataset.fold(0.0) { acc, elt -> acc + (elt - expected).toDouble().pow(2.0) } / expected
}
 
fun chi2Probability(dof: Double, distance: Double): Double {
    return 1.0 - gammaLi(dof * 0.5, distance * 0.5)
}
 
fun chi2Uniform(dataset: List<Int>, significance: Double): Boolean {
    val d = chiDistance(dataset)
    return chi2Probability(dataset.size.toDouble() - 1.0, d) > significance
}
 
