        print("Distance: %.6f ".format(d))
        print("Chi2 probability: %.6f ".format(chi2Probability(ds.size.toDouble() - 1.0, d)))
        print("Uniform? ${chi2Uniform(ds, 0.05)}\n")
    }
}

import java.math.BigInteger
 
class PiCalc {
    private val FOUR = BigInteger.valueOf(4)
    private val SEVEN = BigInteger.valueOf(7)
    private val TEN = BigInteger.valueOf(10)
    private val THREE = BigInteger.valueOf(3)
    private val TWO = BigInteger.valueOf(2)
 
    private var k = BigInteger.ONE
    private var l = BigInteger.valueOf(3)
    private var n = BigInteger.valueOf(3)
    private var q = BigInteger.ONE
    private var r = BigInteger.ZERO
    private var t = BigInteger.ONE
 
    fun calcPiDigits() {
        var nn: BigInteger
        var nr: BigInteger
        var first = true
        while (true) {
            if (FOUR * q + r - t < n * t) {
                print(n)
                if (first) {
                    print(".")
                    first = false
                }
                nr = TEN * (r - n * t)
                n = TEN * (THREE * q + r) / t - TEN * n
                q *= TEN
                r = nr
            } else {
                nr = (TWO * q + r) * l
                nn = (q * (SEVEN * k) + TWO + r * l) / (t * l)
                q *= k
                t *= l
                l += TWO
                k += BigInteger.ONE
                n = nn
                r = nr
            }
        }
    }
}
 
fun main(args: Array<String>) {
    PiCalc().calcPiDigits()
}

import java.math.BigInteger
import kotlin.math.abs
import kotlin.math.pow
import kotlin.math.sqrt
 
fun IntSqRoot(valu: BigInteger, guess: BigInteger): BigInteger {
    var term: BigInteger
    do {
        term = valu / guess
        if (abs(term - guess) <= 1) break
        guess += term
        guess = guess shr 1
    } while (true)
    return guess
}
 
fun ISR(term: BigInteger, guess: BigInteger): BigInteger {
    var valu = term * guess
    do {
        if (abs(term - guess) <= 1) break
        guess += term
        guess = guess shr 1
        term = valu / guess
    } while (true)
    return guess
}
 
fun CalcAGM(lam: BigInteger, gm: BigInteger, z: BigInteger, ep: BigInteger): BigInteger {
    var am: BigInteger
    var zi: BigInteger
    var n: Long = 1
    do {
        am = (lam + gm) shr 1
        gm = ISR(lam, gm)
        val v = am - lam
        if ((zi = v * v * n) < ep) break
        z -= zi
        n = n shl 1
        lam = am
    } while (true)
    return am
}
 
fun BIP(exp: Int, man: Long = 1L): BigInteger {
    var rv = BigInteger.valueOf(10.0.pow(exp).toLong())
    return if (man == 1L) rv else rv * BigInteger.valueOf(man)
}
 
fun main(args: Array<String>) {
    var d = 25000
    if (args.size > 0) {
        d = args[0].toInt()
        if (d < 1 || d > 999999) d = 25000
    }
    val st = System.currentTimeMillis()
    val am = BIP(d)
    val gm = IntSqRoot(BIP(d + d - 1, 5), BIP(d - 15, (sqrt(0.5) * 1e+15).toLong()))
    var z = BIP(d + d - 2, 25)
    val agm = CalcAGM(am, gm, z, BIP(d + 1))
    val pi = agm * agm * BIP(d - 2) / z
    println("Computation time: ${(System.currentTimeMillis() - st) / 1000.0} seconds ")
    val s = pi.toString()
    println("${s[0]}.${s.substring(1)}")
}

//makes outputting a table possible in environments 
//that don't support console.table() 
fun console_table(xs: List<Map<String, Any>>) {
    fun pad(n: Int, s: String): String {
        var res = s
        for (i in s.length until n)
            res += " "
        return res
    }

    if (xs.size == 0)
        println("No data")
    else {
        val widths = mutableListOf<Int>()
        val cells = mutableListOf<MutableList<String>>()
        for (i in 0..xs.size)
            cells.add(mutableListOf())

        for (s in xs[0].keys) {
            var len = s.length
            cells[0].add(s)

            for (i in 0 until xs.size) {
                val ss = xs[i][s].toString()
                len = Math.max(len, ss.length)
                cells[i + 1].add(ss)
            }
            widths.add(len)
        }
        var s = ""
        for (x in 0 until cells.size) {
            for (y in 0 until widths.size)
                s += "|" + pad(widths[y], cells[x][y])
            s += "|\n"
        }
        println(s)
    }
}

//returns the entropy of a string as a number 
fun entropy(s: String): Double {
    //create an object containing each individual char
	//and the amount of iterations per char 
    fun prob(s: String): Map<Char, Int> {
        val h = mutableMapOf<Char, Int>()
        s.forEach { c ->
            h[c] = h[c]?.plus(1)?: 1
        }
        return h
    }

    var e = 0.0
    val l = s.length
    val h = prob(s)

    for (i in h.keys) {
        val p = h[i]!!.toDouble() / l
        e -= p * Math.log(p) / Math.log(2)
    }
    return e
}

//creates Fibonacci Word to n as described on Rosetta Code
//see rosettacode.org/wiki/Fibonacci_word
fun fibWord(n: Int) {
    var wOne = "1"
    var wTwo = "0"
    val wNth = mutableListOf(wOne, wTwo)
    var w = ""
    val o = mutableListOf<Map<String, Any>>()

    for (i in 0 until n) {
        if (i == 0 || i == 1) {
            w = wNth[i]
        } else {
            w = wNth[i - 1] + wNth[i - 2]
            wNth.add(w)
        }
        val l = w.length
        val e = entropy(w)

        if (l <= 21) {
            o.add(mapOf(
                "N" to i + 1,
                "Length" to l,
                "Entropy" to e,
                "Word" to w
            ))
        } else {
            o.add(mapOf(
                "N" to i + 1,
                "Length" to l,
                "Entropy" to e,
                "Word" to "..."
            ))
        }
    }

    try {
        console_table(o)
    } catch (err: Exception) {
        console_table(o)
    }
}

