import java.lang.Integer.parseInt
import java.lang.Math.pow
import java.util.*
 
class TwentyFourGame {
    companion object {
        val EXPRESSIONS = arrayOf(
            "((%dr %s %dr) %s %dr) %s %dr",
            "(%dr %s (%dr %s %dr)) %s %dr",
            "(%dr %s %dr) %s (%dr %s %dr)",
            "%dr %s ((%dr %s %dr) %s %dr)",
            "%dr %s (%dr %s (%dr %s %dr))"
        )
        val OPERATORS = arrayOf(
            arrayOf("+", "-", "*", "/"),
            arrayOf("+", "-", "/", "*"),
            arrayOf("+", "*", "-", "/"),
            arrayOf("+", "*", "/", "-"),
            arrayOf("+", "/", "-", "*"),
            arrayOf("+", "/", "*", "-"),
            arrayOf("-", "+", "*", "/"),
            arrayOf("-", "+", "/", "*"),
            arrayOf("-", "*", "+", "/"),
            arrayOf("-", "*", "/", "+"),
            arrayOf("-", "/", "+", "*"),
            arrayOf("-", "/", "*", "+"),
            arrayOf("*", "+", "-", "/"),
            arrayOf("*", "+", "/", "-"),
            arrayOf("*", "-", "+", "/"),
            arrayOf("*", "-", "/", "+"),
            arrayOf("*", "/", "+", "-"),
            arrayOf("*", "/", "-", "+"),
            arrayOf("/", "+", "-", "*"),
            arrayOf("/", "+", "*", "-"),
            arrayOf("/", "-", "+", "*"),
            arrayOf("/", "-", "*", "+"),
            arrayOf("/", "*", "+", "-"),
            arrayOf("/", "*", "-", "+")
        )
        fun solve(digits: IntArray): List<String> {
            val solutions = ArrayList<String>()
            val perms = digits.permutations().distinct()
            for (perm in perms) {
                for (op in OPERATORS) {
                    for (expr in EXPRESSIONS) {
                        val text = expr.format(perm[0], op[0], perm[1], op[1], perm[2], op[2], perm[3])
                        val value = eval(text)
                        if (value == 24) {
                            solutions.add(text.replace("r", ""))
                        }
                    }
                }
            }
            return solutions
        }
        private fun eval(text: String): Double {
            val stack = Stack<Double>()
            val tokens = text.split(" ")
            for (token in tokens) {
                if (token == "+") {
                    val b = stack.pop()
                    val a = stack.pop()
                    stack.push(a + b)
                } else if (token == "-") {
                    val b = stack.pop()
                    val a = stack.pop()
                    stack.push(a - b)
                } else if (token == "*") {
                    val b = stack.pop()
                    val a = stack.pop()
                    stack.push(a * b)
                } else if (token == "/") {
                    val b = stack.pop()
                    val a = stack.pop()
                    stack.push(a / b)
                } else {
                    stack.push(token.toDouble())
                }
            }
            return stack.pop()
        }
    }
}
 
fun main(args: Array<String>) {
    val digits = args.map {
        try {
            parseInt(it)
        } catch (e: NumberFormatException) {
            throw IllegalArgumentException("error: not an integer: '$it'")
        }
    }
    if (digits.size!= 4) {
        throw IllegalArgumentException("error: need 4 digits, only have ${digits.size}")
    }
    val solutions = TwentyFourGame.solve(digits.toIntArray())
    if (solutions.isEmpty()) {
        println("no solutions")
    } else {
        println("found ${solutions.size} solutions, including ${solutions.first()}")
        println(solutions.sorted())
    }
}
 
fun <T> Array<T>.permutations(): List<Array<T>> {
    val result = ArrayList<Array<T>>()
    if (size == 1) {
        result.add(this)
    } else {
        for (i in indices) {
            val sub = toMutableList()
            val e = sub.removeAt(i)
            sub.permutations().forEach { p ->
                result.add(arrayOf(e) + p)
            }
        }
    }
    return result
}

