val deck = IntStream.range(0, 3).boxed().flatMap { i1 ->
    IntStream.range(0, 3).boxed().flatMap { i2 ->
        IntStream.range(0, 3).boxed().flatMap { i3 ->
            IntStream.range(0, 3).boxed().map { i4 ->
                intArrayOf(i1, i2, i3, i4)
            }
        }
