fun printCard(card: IntArray) {
    for (i in 0..3) {
        print(features[i][card[i]] + " ")
    }
    println()
}
 
fun getDeal(dealt: Int = dealt): List<IntArray> {
    val random = Random()
    val deal = ArrayList<IntArray>()
    for (i in 0 until dealt) {
        deal.add(deck[random.nextInt(deck.size)])
    }
    return deal
}
 
fun getSets(deal: List<IntArray>): List<List<IntArray>> {
    val goodFeatureCount = setOf(1, 3)
    val sets = ArrayList<List<IntArray>>()
    for (i in 0 until deal.size - 2) {
        for (j in i + 1 until deal.size - 1) {
            for (k in j + 1 until deal.size) {
                val comb = listOf(deal[i], deal[j], deal[k])
                if (comb.all { feature ->
                    goodFeatureCount.contains(feature.toSet().size)
                }) {
                    sets.add(comb)
                }
            }
        }
    }
    return sets
}
 
fun printIt(deal: List<IntArray>, sets: List<List<IntArray>>) {
    println("Dealt ${deal.size} cards:")
    deal.forEach { printCard(it) }
    println("\nFound ${sets.size} sets:")
    sets.forEach {
        it.forEach { printCard(it) }
        println()
    }
}
 
fun main(args: Array<String>) {
    while (true) {
        val deal = getDeal()
        val sets = getSets(deal)
        if (sets.size == dealt / 2) {
            printIt(deal, sets)
            break
        }
    }
}

import java.util.stream.IntStream
import java.util.stream.Stream
import kotlin.math.sqrt
 
fun Int.isPrime(): Boolean {
    if (this < 2) return false
    if (this == 2) return true
    if (this % 2 == 0) return false
    for (i in 3..sqrt(this.toDouble()).toInt() step 2) {
        if (this % i == 0) return false
    }
    return true
}
 
fun Int.isSafePrime(): Boolean {
    return (this - 1) / 2.isPrime()
}
 
fun formatParts(n: Int): String {
    val partitions = IntStream.range(0, n).filter { it.isPrime() }.partition { it.isSafePrime() }
    return "There are ${partitions.first.count()} safes and ${partitions.second.count()} unsafes below $n."
}
 
fun main() {
    println("First 35 safe-primes:")
    println(IntStream.iterate(0, Int::inc).filter { it.isSafePrime() }.limit(35).toList())
    println(formatParts(1_000_000), "\n")
    println("First 40 unsafe-primes:")
    println(IntStream.iterate(0, Int::inc).filter {!it.isSafePrime() }.limit(40).toList())
    println(formatParts(10_000_000))
}

import java.math.BigInteger
import java.util.*
import java.util.stream.Collectors.joining
import java.util.stream.Collectors.toList
import kotlin.streams.asSequence
import kotlin.streams.toList
 
fun rank(x: IntArray): BigInteger {
    val s = x.asSequence().map { it.toString() }.collect(joining("F"))
    return BigInteger(s, 16)
}
 
fun unrank(n: BigInteger): List<BigInteger> {
    val sixteen = BigInteger.valueOf(16)
    var s = ""
    var n = n
    while (!n.equals(BigInteger.ZERO)) {
        s = "0123456789ABCDEF".elementAt(n.mod(sixteen).toInt()) + s
        n = n.divide(sixteen)
    }
    return s.split("F").map { BigInteger(it) }.toList()
}
 
fun main(args: Array<String>) {
    val s = intArrayOf(1, 2, 3, 10, 100, 987654321)
    println(Arrays.toString(s))
    println(rank(s))
    println(unrank(rank(s)))
}

