import kotlin.math.roundToInt
 
class Guess(val value: String) {
    companion object {
        fun play() {
            val nums = Array(4) { (1..9).random() }
            while (true) {
                val result = get(nums).evaluate()
                if (result == 24.0) {
                    println("You win!")
                    break
                }
                println("Try again! That gives $result!")
            }
        }
 
        fun get(nums: Array<Int>): Guess {
            while (true) {
                print("\nEnter a guess using ${nums.contentToString()}: ")
                val input = readLine()!!
                val guess = Guess(input)
                if (guess.validate(nums)) {
                    return guess
                }
            }
        }
 
        fun validate(guess: Guess, nums: Array<Int>): Boolean {
            val name = when {
                guess.value.any {!it.isDigit() && it!='' } -> "invalid character"
                guess.value.map { it.toString().toInt() }.sorted()!= nums.sorted() -> "wrong number"
                guess.value.any { it.isDigit() && it.toString().toInt() > 9 } -> "multi-digit number"
                else -> return true
            }
            println("Invalid input of a(n) $name!")
            return false
        }
    }
 
    fun evaluate(): Double {
        val asRat = value.replace(Regex("([0-9])"), "$1r")
        return eval(asRat).toDouble()
    }
 
    private fun eval(str: String): Int {
        val stack = Stack<Int>()
        var i = 0
        while (i < str.length) {
            val c = str[i]
            if (c.isDigit()) {
                stack.push(c.toString().toInt())
            } else {
                val b = stack.pop()
                val a = stack.pop()
                stack.push(when (c) {
                    '+' -> a + b
                    '-' -> a - b
                    '*' -> a * b
                    '/' -> a / b
                    '^' -> a.toDouble().pow(b).roundToInt()
                    else -> throw IllegalArgumentException("Unknown operator: $c")
                })
            }
            i++
        }
        return stack.pop()
    }
}
 
fun main() {
    Guess.play()
}

