import java.util.Arrays
import java.util.Collections
 
class jortSort {
    fun <T> jort_sort(o: Array<T>, s: Int): Boolean {
        val n = copy_array(o, s)
        sort_array(n, s)
        var r = false
 
        if (n!= null) {
            r = check(o, n, s)
        }
        return r
    }
 
    private fun <T> copy_array(o: Array<T>, s: Int): Array<T>? {
        val z = Arrays.copyOf(o, s)
        return z
    }
 
    private fun <T> sort_array(n: Array<T>, s: Int) {
        Arrays.sort(n)
    }
 
    private fun <T> check(n: Array<T>, o: Array<T>, s: Int): Boolean {
        for (x in 0..s - 1) {
            if (n[x]!= o[x]) return false
        }
        return true
    }
}
 
val js = jortSort()
 
fun <T> displayTest(o: Array<T>, s: Int) {
    for (x in 0..s - 1) {
        print(o[x].toString() + " ")
    }
    print(": -> The array is " + if (js.jort_sort(o, s)) "sorted!" else "not sorted!")
    println()
}
 
fun main(args: Array<String>) {
    val s = 5
    val oStr = arrayOf("5", "A", "D", "R", "S")
