    Collections.swap(Arrays.asList(oStr), 0, 1)
    displayTest(oStr, s)
 
    val oInt = intArrayOf(1, 2, 3, 4, 5)
    displayTest(oInt, s)
    Collections.swap(Arrays.asList(oInt), 0, 1)
