fun combSort(input: IntArray): IntArray {
    var gap = input.size
    var swaps = true
    while (gap > 1 || swaps) {
        gap /= 1.247330950103979
        if (gap < 1) {
            gap = 1.0
        }
        var i = 0
        swaps = false
        while (i + gap < input.size) {
            val igap = i + gap.toInt()
            if (input[i] > input[igap]) {
                val swap = input[i]
                input[i] = input[igap]
                input[igap] = swap
                swaps = true
            }
            i++
        }
    }
    return input
}

