fun shellSort(a: IntArray): IntArray {
    var h = a.size
    while (h > 0) {
        h = h / 2
        for (i in h until a.size) {
            val k = a[i]
            var j = i
            while (j >= h && k < a[j - h]) {
                a[j] = a[j - h]
                j -= h
            }
            a[j] = k
        }
    }
    return a
}

