import java.math.BigInteger
 
val MAX_N = 500
val BRANCH = 4
 
fun tree(br: Int, n: Int, l: Int = n, sum: BigInteger = BigInteger.ONE, cnt: BigInteger = BigInteger.ONE) {
    for (b in br + 1..BRANCH) {
        val sum = sum + n
        if (sum >= MAX_N) return
        // prevent unneeded long math
        if (l * 2 >= sum && b >= BRANCH) return
        val c = if (b == br + 1) {
            ra[n] * cnt
        } else {
            c * (ra[n] + (b - br - 1)) / (b - br)
        }
        unrooted[sum] += c
        if (l * 2 < sum) continue
        if (b >= BRANCH) continue
        for (m in 1 until n) {
            tree(b, m, l, sum, c)
        }
    }
}
 
fun bicenter(s: Int) {
    if (s.rem(2)!= 0) return
    val aux = ra[s / 2]
    unrooted[s] += aux * (aux + BigInteger.ONE) / 2
}
 
val ra = Array(MAX_N) { BigInteger.ZERO }
val unrooted = Array(MAX_N) { BigInteger.ZERO }
 
ra[0] = ra[1] = unrooted[0] = unrooted[1] = BigInteger.ONE
for (n in 1 until MAX_N) {
    tree(0, n)
    bicenter(n)
    println("$n: ${unrooted[n]}")
}

