val hh = arrayOf(
    "1115dd800feaacefdf481f1f9070374a2a81e27880f187396db67958b207cbad",
    "3a7bd3e2360a3d29eea436fcfb7e44c735d117c42d1c1835420b6b9942dd4f1b",
    "74e1bb62f8dabb8125a58852b63bdf6eaef667cb56ac7f7cdba6d7305c50a22f"
)
 
fun main() {
    val hd = Array(hh.size) { BigInteger(hh[it], 16) }
    val wg = CountDownLatch(26)
    for (c in 'a'..'z') {
        thread {
            bf4(c, hd, wg)
        }
    }
    wg.await()
}
 
fun bf4(c: Char, hd: Array<BigInteger>, wg: CountDownLatch) {
    val p = CharArray(5) { 'a' }
    p[0] = c
    val p1 = p.copyOfRange(1, 5)
    while (true) {
        val ph = MessageDigest.getInstance("SHA-256").digest(p.toByteArray()).toBigInteger(1, 16)
        for (i in hd.indices) {
            if (hd[i] == ph) {
                println("${String(p)} ${hh[i]}")
            }
        }
        for (i in p1.indices) {
            if (p1[i] < 'z') {
                p1[i]++
                continue
            }
            p1[i] = 'a'
        }
        wg.countDown()
        return
    }
}

import java.util.Arrays
import java.util.HashSet
import java.util.Set
 
fun main(args: Array<String>) {
    val setA = HashSet<String>(Arrays.asList("John", "Serena", "Bob", "Mary", "Serena"))
    val setB = HashSet<String>(Arrays.asList("Jim", "Mary", "John", "Jim", "Bob"))
 
    // Present our initial data set
    println("In set A: $setA")
    println("In set B: $setB")
 
    // Option 1: union of differences
    // Get our individual differences.
    val notInSetA = HashSet<String>(setB)
    notInSetA.removeAll(setA)
    val notInSetB = HashSet<String>(setA)
    notInSetB.removeAll(setB)
 
    // The symmetric difference is the concatenation of the two individual differences
    val symmetricDifference = HashSet<String>(notInSetA)
    symmetricDifference.addAll(notInSetB)
 
    // Option 2: union minus intersection
    // Combine both sets
    val union = HashSet<String>(setA)
    union.addAll(setB)
 
    // Get the intersection
    val intersection = HashSet<String>(setA)
    intersection.retainAll(setB)
 
    // The symmetric difference is the union of the 2 sets minus the intersection
    val symmetricDifference2 = HashSet<String>(union)
    symmetricDifference2.removeAll(intersection)
 
    // Present our results
    println("Not in set A: $notInSetA")
    println("Not in set B: $notInSetB")
    println("Symmetric Difference: $symmetricDifference")
    println("Symmetric Difference 2: $symmetricDifference2")
}

class PowIt {
	var next: Int = 1
}
 
class SquareIt : PowIt() {
	override fun next(): Int {
		val result = this.next.toDouble().pow(2.0).toInt()
		this.next++
		return result
	}
}
 
class CubeIt : PowIt() {
	override fun next(): Int {
		val result = this.next.toDouble().pow(3.0).toInt()
		this.next++
		return result
	}
}
 
fun main(args: Array<String>) {
	val squares = mutableListOf<Int>()
	val hexponents = mutableListOf<Int>()
	val squit = SquareIt()
	val cuit = CubeIt()
	var s = squit.next()
	var c = cuit.next()
	while (squares.size < 30 || hexponents.size < 3) {
		if (s < c) {
			if (squares.size < 30) {
				squares.add(s)
			}
			s = squit.next()
		} else if (s == c) {
			if (hexponents.size < 3) {
				hexponents.add(s)
			}
			s = squit.next()
			c = cuit.next()
		} else {
			c = cuit.next()
		}
	}
	println("Squares:")
	println(squares.joinToString(" "))
	println("Square-and-cubes:")
	println(hexponents.joinToString(" "))
}

task_description:
Jensen's Device

You are encouraged to solve this task according to the task description, using any language you may know.
This task is an exercise in call by name.

Jensen's Device is a computer programming technique devised by Danish computer scientist Jørn Jensen after studying the ALGOL 60 Report.

The following program was proposed to illustrate the technique. It computes the 100th harmonic number:

begin
   integer i;
   real procedure sum (i, lo, hi, term);
      value lo, hi;
      integer i, lo, hi;
      real term;
      comment term is passed by-name, and so is i;
   begin
      real temp;
      temp := 0;
      for i := lo step 1 until hi do
         temp := temp + term;
      sum := temp
   end;
   comment note the correspondence between the mathematical notation and the call to sum;
   print (sum (i, 1, 100, 1/i))
end

The above exploits call by name to produce the correct answer (5.187...). It depends on the assumption that an expression passed as an actual parameter to a procedure would be re-evaluated in the caller's context every time the corresponding formal parameter's value was required. If the last parameter to sum had been passed by value, and assuming the initial value of i were 1, the result would have been 100 × 1/1 = 100.

Moreover, the first parameter to sum, representing the "bound" variable of the summation, must also be passed by name (or at least by reference), otherwise changes to it (made within sum) would not be visible in the caller's context when computing each of the values to be added.
(On the other hand, the global variable does not have to use the same identifier, in this case i, as the formal parameter.)

Donald Knuth later proposed the Man or Boy Test as a more rigorous exercise.

code:
import kotlin.math.pow
 
var i = 0
fun sum(lo: Int, hi: Int, term: () -> Double): Double {
    var temp = 0.0
    for (i in lo..hi)
        temp += term()
    return temp
}
 
fun term_func(): Double { return 1.0 / i }
 
fun main() {
    println(sum(1, 100, ::term_func))
}

fun isPalindrome(s: String): Boolean {
    return s == s.reversed()
}

fun hs(n: Int, seq: MutableList<Int>): MutableList<Int> {
    val sequence = seq
    sequence.add(n)
    return if (n == 1) {
        sequence
    } else {
        val newn = if (n % 2 == 0) n / 2 else (3 * n) + 1
        hs(newn, sequence)
    }
}
 
fun main(args: Array<String>) {
    val n = 27
    val sequence = hs(n, mutableListOf())
    println(sequence.size.toString() + " Elements")
    val start = sequence.subList(0, 4)
    val end = sequence.subList(sequence.size - 4, sequence.size)
    println("Starting with : " + start.joinToString(",") + " and ending with : " + end.joinToString(","))
    var number = 0
    var longest = 0
    for (i in 1..99999) {
        val count = hs(i, mutableListOf()).size
        if (count > longest) {
            longest = count
            number = i
        }
    }
    println("Number < 100000 with longest Hailstone seq.: $number with length of $longest")
}

import kotlin.math.sqrt
 
enum class Action { STDDEV, MEAN, VAR, COUNT }
 
class StatObject(var sum: Double, var sum2: Double, var num: Long, var action: Action) {
 
    fun stat_obj_value(action: Action): Double {
        var num: Double
        var mean: Double
        var var: Double
        var stddev: Double
 
        if (this.num == 0.0) return 0.0
        num = this.num.toDouble()
        if (action == Action.COUNT) return num
        mean = this.sum / num
        if (action == Action.MEAN) return mean
        var = this.sum2 / num - mean * mean
        if (action == Action.VAR) return var
        stddev = sqrt(var)
        if (action == Action.STDDEV) return stddev
        return 0.0
    }
 
    fun stat_object_add(v: Double): Double {
        this.num++
        this.sum += v
        this.sum2 += v * v
        return stat_obj_value(this.action)
    }
}
 
fun NewStatObject(action: Action): StatObject {
    return StatObject(0.0, 0.0, 0, action)
}
 
fun FREE_STAT_OBJECT(so: StatObject) {
    so.sum = 0.0
    so.sum2 = 0.0
    so.num = 0
    so.action = Action.STDDEV
}

