fun show(s: String) {
    println("\nstring:         " + s + " len: " + s.length + " runes") // DZLjnj
    println("All upper case: " + s.toUpperCase()) // DZLJNJ
    println("All lower case: " + s.toLowerCase()) // dzljnj
    println("All title case: " + s.capitalize()) // DzLjNj
    println("Title words:    " + s.capitalizeWords())   // Dzljnj
    println("Swapping case:  " + s.swapCase()) // DzLjNJ
}
 
fun String.capitalizeWords(): String {
    return split(" ").joinToString(" ") { it.capitalize() }
}
 
fun String.swapCase(): String {
    return map {
        if (it.isUpperCase()) it.toLowerCase() else it.toUpperCase()
    }.joinToString("")
}

