import kotlin.math.abs
import kotlin.math.gcd
 
class Frac(var num: Int, var denom: Int) {
    init {
        if (denom == 0) {
            throw IllegalArgumentException("d cannot be zero")
        }
 
        var nn = num
        var dd = denom
        if (nn == 0) {
            dd = 1
        } else if (dd < 0) {
            nn = -nn
            dd = -dd
        }
 
        val g = abs(nn).gcd(abs(dd))
        if (g > 1) {
            nn /= g
            dd /= g
        }
 
        num = nn
        denom = dd
    }
 
    override fun toString(): String {
        return if (denom == 1) {
            num.toString()
        } else {
            "%d/%d".format(num, denom)
        }
    }
 
    operator fun unaryMinus(): Frac {
        return Frac(-num, denom)
    }
 
    operator fun plus(rhs: Frac): Frac {
        return Frac(num * rhs.denom + denom * rhs.num, rhs.denom * denom)
    }
 
    operator fun minus(rhs: Frac): Frac {
        return Frac(num * rhs.denom - denom * rhs.num, rhs.denom * denom)
    }
 
    operator fun times(rhs: Frac): Frac {
        return Frac(num * rhs.num, rhs.denom * denom)
    }
}
 
val FRAC_ZERO = Frac(0, 1)
val FRAC_ONE = Frac(1, 1)
 
fun bernoulli(n: Int): Frac {
    if (n < 0) {
        throw IllegalArgumentException("n cannot be negative")
    }
 
    val a = Array(n + 1) { FRAC_ZERO }
    a[0] = FRAC_ZERO
 
    for (m in 0..n) {
        a[m] = Frac(1, m + 1)
        for (j in m downTo 1) {
            a[j - 1] = (a[j - 1] - a[j]) * Frac(j, 1)
        }
    }
 
    return if (n!= 1) {
        a[0]
    } else {
        -a[0]
    }
}
 
fun binomial(n: Int, k: Int): Int {
    if (n < 0) {
        throw IllegalArgumentException("n cannot be negative")
    }
    if (k < 0) {
        throw IllegalArgumentException("k cannot be negative")
    }
    if (n < k) {
        throw IllegalArgumentException("n cannot be less than k")
    }
 
    if (n == 0 || k == 0) {
        return 1
    }
 
    var num = 1
    for (i in k + 1..n) {
        num *= i
    }
 
    var den = 1
    for (i in 2..n - k) {
        den *= i
    }
 
    return num / den
}
 
fun faulhaberTriangle(p: Int): Array<Frac> {
    val coeffs = Array(p + 1) { FRAC_ZERO }
    coeffs[0] = FRAC_ZERO
    val q = Frac(1, p + 1)
    var sign = -1
    for (j in 0..p) {
        sign = -sign
        coeffs[p - j] = q * Frac(sign, 1) * Frac(binomial(p + 1, j), 1) * bernoulli(j)
    }
    return coeffs
}
 
fun main() {
    for (i in 0..9) {
        val coeffs = faulhaberTriangle(i)
        coeffs.forEach { coeff ->
            print("%5s  ".format(coeff))
        }
        println()
    }
}
 
