import java.lang.String
import java.lang.System
 
fun main(args: Array<String>) {
    var num = 9876432
    val diff = intArrayOf(4, 2, 2, 2)
    var i: Int
    var j: Int
    var k = 0
    start@ while (true) {
        val str = String.format("%d", num)
        i = 0
        while (str[i + 1]!= 0.toChar()) {
            if (str[i] == '0'.toChar() || str[i] == '5'.toChar() || num % (str[i] - '0'.toChar())!= 0) {
                num -= diff[k]
                k = (k + 1) % 4
                continue@start
            }
            j = i + 1
            while (str[j]!= 0.toChar()) {
                if (str[i] == str[j]) {
                    num -= diff[k]
                    k = (k + 1) % 4
                    continue@start
                }
                j++
            }
            i++
        }
        break
    }
    System.out.printf("Number found : %d", num)
}

/*
 
Translate this
 
http://rosettacode.org/wiki/Sorting_algorithms/Cocktail_sort_with_shifting_bounds
 
based on
 
http://rosettacode.org/wiki/Sorting_algorithms/Cocktail_sort#Python
 
*/
 
fun cocktailshiftingbounds(A: MutableList<Int>) {
    var beginIdx = 0
    var endIdx = A.size - 1
 
    while (beginIdx <= endIdx) {
        var newBeginIdx = endIdx
        var newEndIdx = beginIdx
        for (ii in beginIdx..endIdx) {
            if (A[ii] > A[ii + 1]) {
                val tmp = A[ii]
                A[ii] = A[ii + 1]
                A[ii + 1] = tmp
                newEndIdx = ii
            }
        }
        endIdx = newEndIdx
 
        for (ii in endIdx downTo beginIdx - 1) {
            if (A[ii] > A[ii + 1]) {
                val tmp = A[ii]
                A[ii] = A[ii + 1]
                A[ii + 1] = tmp
                newBeginIdx = ii
            }
        }
        beginIdx = newBeginIdx + 1
    }
}
 
fun main(args: Array<String>) {
    val test1 = mutableListOf(7, 6, 5, 9, 8, 4, 3, 1, 2, 0)
    cocktailshiftingbounds(test1)
    println(test1)
 
    val test2 = mutableListOf('b', 'i', 'g','', 'f', 'j', 'o', 'r', 'd','s','', 'v', 'e', 'x','', 'q', 'u', 'i', 'c', 'k','', 'w', 'a', 'l', 't', 'z','', 'n', 'y','m', 'p', 'h')
    cocktailshiftingbounds(test2)
    println(test2.joinToString(""))
}

