import kotlin.reflect.KClass
import kotlin.reflect.full.companionObject
import kotlin.reflect.full.companionObjectInstance
import kotlin.reflect.full.isSubclassOf
import kotlin.reflect.full.primaryConstructor
import kotlin.reflect.jvm.isAccessible

class Singleton {
    companion object {
        private val instances = mutableMapOf<KClass<*>, Any>()

        fun <T : Any> instance(clazz: KClass<T>): T {
            if (instances.containsKey(clazz)) {
                return instances[clazz] as T
            }

            val constructor = clazz.primaryConstructor?: throw IllegalArgumentException("Class $clazz must have a primary constructor")
            constructor.isAccessible = true
            val instance = constructor.call()
            instances[clazz] = instance
            return instance
        }
    }
}

interface MySingleton {
    companion object : Singleton()
}

class MySingletonImpl : MySingleton

fun main() {
    val a = MySingleton.instance(MySingletonImpl::class)
    val b = MySingleton.instance(MySingletonImpl::class)
    println(a === b) // outputs "true"
}

