fun <T, R> Array<T>.bind(func: (T) -> Array<R>): Array<R> {
    return this.map(func).reduce { acc, a -> acc.concat(a) }
}
 
fun <T> Array<T>.unit(elem: T): Array<T> {
    return arrayOf(elem)
}
 
fun <T, R> Array<T>.lift(func: (T) -> R): (T) -> Array<R> {
    return { elem -> arrayOf(func(elem)) }
}
 
