package main
 
import (
    "fmt"
    "sort"
    "strings"
)
 
const stx = "\002"
const etx = "\003"
 
fun bwt(s: String): String {
    if (s.indexOf(stx) >= 0 || s.indexOf(etx) >= 0) {
        return ""
    }
    val s = stx + s + etx
    val le = s.length
    val table = arrayOfNulls<String>(le)
    table[0] = s
    for (i in 1 until le) {
        table[i] = s.substring(i) + s.substring(0, i)
    }
    sort.Strings(table)
    val lastBytes = CharArray(le)
    for (i in 0 until le) {
        lastBytes[i] = table[i][le - 1]
    }
    return String(lastBytes)
}
 
fun ibwt(r: String): String {
    val le = r.length
    val table = arrayOfNulls<String>(le)
    for (i in 0 until le) {
        for (j in 0 until le) {
            table[j] = r[j] + table[j]
        }
        sort.Strings(table)
    }
    for (row in table) {
        if (row.endsWith(etx)) {
            return row.substring(1, le - 1)
        }
    }
    return ""
}
 
fun makePrintable(s: String): String {
    // substitute ^ for STX and | for ETX to print results
    var t = s.replace(stx, "^", 1)
    return t.replace(etx, "|", 1)
}
 
fun main(args: Array<String>) {
    val tests = arrayOf(
        "banana",
        "appellee",
        "dogwood",
        "TO BE OR NOT TO BE OR WANT TO BE OR NOT?",
        "SIX.MIXED.PIXIES.SIFT.SIXTY.PIXIE.DUST.BOXES",
        "\002ABC\003"
    )
    for (test in tests) {
        println(makePrintable(test))
        println(" --> ")
        val t = bwt(test)
        if (t.isEmpty()) {
            println("ERROR: String can't contain STX or ETX")
        } else {
            println(makePrintable(t))
        }
        val r = ibwt(t)
        println(" --> $r \n")
    }
}

package com.github.shafirov.kotlin_examples.example1

import kotlin.reflect.KClass
import kotlin.reflect.full.declaredMemberFunctions
import kotlin.reflect.full.memberProperties
import kotlin.reflect.jvm.isAccessible

// interface types provide polymorphism, but not inheritance.
interface I {
    fun identify(): String
}

// "base" type
typealias T = Double

// "derived" type.  in Go terminology, it is simply a struct with an
// anonymous field.  fields and methods of anonymous fields however,
// can be accessed without additional qualification and so are
// "inherited" in a sense.
data class S(val t: T, val kōan: String)

// another type with an "embedded" t field.  (t is the *type*, this field
// has no *name*.)
data class R(val t: T, val ch: Int)

// a method on t.  this method makes t satisfy interface i.
// since a t is embedded in types s and r, they automatically "inherit"
// the method.
fun T.identify(): String {
    return "I'm a t!"
}

// the same method on s.  although s already satisfied i, calls to identify
// will now find this method rather than the one defined on t.
// in a sense it "overrides" the method of the "base class."
fun S.identify(): String {
    return "I'm an s!"
}

fun main() {
    // three variables with different types, initialized from literals.
    val t1: T = 5.0
    val s1: S = S(6.0, "one")
    val r1: R = R(7.0, 0)

    // variables declared with the same type.  initial value is nil.
    var i1: I? = null
    var i2: I? = null
    var i3: I? = null
    println("Initial (zero) values of interface variables:")
    println("i1: $i1")
    println("i2: $i2")
    println("i3: $i3")

    // in the terminology of the Go language reference, i1, i2, and i3
    // still have static type i, but now have different dynamic types.
    i1 = t1
    i2 = s1
    i3 = r1
    println("\nPolymorphic:")
    println("i1: $i1 / ${i1?.identify()} / ${i1?.javaClass}")
    println("i2: $i2 / ${i2?.identify()} / ${i2?.javaClass}")
    println("i3: $i3 / ${i3?.identify()} / ${i3?.javaClass}")

    // copy: declare and assign in one step using "short declaration."
    val i1c = i1
    val i2c = i2
    val i3c = i3

    // modify first set of polymorphic variables.
    i1 = S(3.0, "dog")
    i2 = R(1.0, 0)
    i3 = 2.0

    // demonstrate that copies are distinct from first set
    // and that types are preserved.
    println("\nFirst set now modified:")
    println("i1: $i1 / ${i1?.identify()} / ${i1?.javaClass}")
    println("i2: $i2 / ${i2?.identify()} / ${i2?.javaClass}")
    println("i3: $i3 / ${i3?.identify()} / ${i3?.javaClass}")

    println("\nCopies made before modifications:")
    println("i1c: $i1c / ${i1c?.identify()} / ${i1c?.javaClass}")
    println("i2c: $i2c / ${i2c?.identify()} / ${i2c?.javaClass}")
    println("i3c: $i3c / ${i3c?.identify()} / ${i3c?.javaClass}")
}

fun indexOf(haystack: IntArray, needle: Int): Int {
    var idx = 0
    for (straw in haystack) {
        if (straw == needle) {
            return idx
        } else {
            idx++
        }
    }
    return -1
}
 
fun getDigits(n: Int, le: Int, digits: IntArray): Boolean {
    var n = n
    var le = le
    while (n > 0) {
        val r = n % 10
        if (r == 0 || indexOf(digits, r) >= 0) {
            return false
        }
        le--
        digits[le] = r
        n = (n / 10).toInt()
    }
    return true
}
 
val POWS = intArrayOf(1, 10, 100, 1000, 10000)
fun removeDigit(digits: IntArray, le: Int, idx: Int): Int {
    var sum = 0
    var pow = POWS[le - 2]
    var i = 0
    while (i < le) {
        if (i == idx) {
            i++
            continue
        }
        sum += digits[i] * pow
        pow = (pow / 10).toInt()
        i++
    }
    return sum
}
 
fun main(args: Array<String>) {
    val lims = arrayOf(intArrayOf(12, 97), intArrayOf(123, 986), intArrayOf(1234, 9875), intArrayOf(12345, 98764))
    val count = IntArray(5)
    val omitted = Array(5) { IntArray(10) }
 
    var i = 0
    for (lim in lims) {
        var n = lim[0]
        while (n < lim[1]) {
            val nDigits = IntArray(i + 2)
            val nOk = getDigits(n, i + 2, nDigits)
            if (!nOk) {
                n++
                continue
            }
            var d = n + 1
            while (d <= lim[1] + 1) {
                val dDigits = IntArray(i + 2)
                val dOk = getDigits(d, i + 2, dDigits)
                if (!dOk) {
                    d++
                    continue
                }
                var nix = 0
                while (nix < nDigits.size) {
                    val digit = nDigits[nix]
                    val dix = indexOf(dDigits, digit)
                    if (dix >= 0) {
                        val rn = removeDigit(nDigits, i + 2, nix)
                        val rd = removeDigit(dDigits, i + 2, dix)
                        if (1.0 * n / d == 1.0 * rn / rd) {
                            count[i] = count[i] + 1
                            omitted[i][digit] = omitted[i][digit] + 1
                            if (count[i] <= 12) {
                                println("%d/%d = %d/%d by omitting %d's".format(n, d, rn, rd, digit))
                            }
                        }
                    }
                    nix++
                }
                d++
            }
            n++
        }
        println()
        i++
    }
 
    i = 2
    while (i <= 5) {
        println("There are %d %d-digit fractions of which:".format(count[i - 2], i))
        var j = 1
        while (j <= 9) {
            if (omitted[i - 2][j] == 0) {
                j++
                continue
            }
            println("%6s have %d's omitted".format(omitted[i - 2][j], j))
            j++
        }
        println()
        i++
    }
}

fun fib(n: Int): Int {
    if (n < 2) {
        return n
    } else {
        return fib(n - 2) + fib(n - 1)
    }
}

fun divisors(n: Int): List<Int> {
    val divs = mutableListOf(1)
    val divs2 = mutableListOf<Int>()
    for (i in 2..Math.sqrt(n.toDouble()).toInt()) {
        if (n % i == 0) {
            val j = n / i
            divs.add(i)
            if (i!= j) {
                divs2.add(j)
            }
        }
    }
    for (i in divs2.size - 1 downTo 0) {
        divs.add(divs2[i])
    }
    return divs
}
 
fun sum(divs: List<Int>): Int {
    var tot = 0
    for (div in divs) {
        tot += div
    }
    return tot
}
 
fun sumStr(divs: List<Int>): String {
    var s = ""
    for (div in divs) {
        s += "$div + "
    }
    return s.substring(0, s.length - 3)
}
 
fun abundantOdd(searchFrom: Int, countFrom: Int, countTo: Int, printOne: Boolean): Int {
    var count = countFrom
    var n = searchFrom
    while (count < countTo) {
        val divs = divisors(n)
        val tot = sum(divs)
        if (tot > n) {
            count++
            if (printOne && count < countTo) {
                continue
            }
            val s = sumStr(divs)
            if (!printOne) {
                println("$count. ${n.toString().padStart(5)} < $s = $tot")
            } else {
                println("$n < $s = $tot")
            }
        }
        n += 2
    }
    return n
}
 
fun main(args: Array<String>) {
    val max = 25
    println("The first $max abundant odd numbers are:")
    var n = abundantOdd(1, 0, max, false)
 
    println("\nThe one thousandth abundant odd number is:")
    abundantOdd(n, max, 1000, true)
 
    println("\nThe first abundant odd number above one billion is:")
    abundantOdd(1000000001, 0, 1, true)
}

fun <T> insert_after(N: Node<T>, data: T) {
    val node = Node(N, N.next, data)
    if (N.next!= null) {
        N.next!!.prev = node
    }
    N.next = node
}

object MoveToFront {
    private val ABC = ('a'..'z').toList()
    fun encode(str: String): List<Int> {
        var ar = ABC.toMutableList()
        return str.map { char ->
            val i = ar.indexOf(char)
            ar = m2f(ar, i)
            i
        }
    }
    fun decode(indices: List<Int>): String {
        var ar = ABC.toMutableList()
        return indices.map { i ->
            val char = ar[i]
            ar = m2f(ar, i)
            char
        }.joinToString("")
    }
    private fun m2f(ar: MutableList<Char>, i: Int): MutableList<Char> {
        val char = ar.removeAt(i)
        return mutableListOf(char) + ar
    }
}
fun main(args: Array<String>) {
    val words = listOf("broood", "bananaaa", "hiphophiphop")
    words.forEach { word ->
        println(word == MoveToFront.decode(MoveToFront.encode(word)))
    }
}

