fun sortDisjointSublist(data: MutableList<Int>, indices: Set<Int>) {
	val sortedIndices = indices.sorted()
	val sortedValues = sortedIndices.map { data[it] }.sorted()
	for ((index, value) in sortedIndices.zip(sortedValues)) {
		data[index] = value
	}
}
 
