import kotlin.math.ceil
import kotlin.math.floor
import kotlin.math.sqrt
 
fun gcd(a: Int, b: Int): Int {
    var rem = 1
    var dividend = 0
    var divisor = 0
    if (a < b) {
        dividend = b
        divisor = a
    } else {
        dividend = a
        divisor = b
    }
    while (rem!= 0) {
        rem = dividend % divisor
        if (rem!= 0) {
            dividend = divisor
            divisor = rem
        }
    }
    return divisor
}
 
data class Triangle(val a: Int, val b: Int, val c: Int)
 
fun perimeter(triangle: Triangle): Int {
    return triangle.a + triangle.b + triangle.c
}
 
fun area(t: Triangle): Double {
    val p_2 = perimeter(t) / 2.0
    val area_sq = p_2 * (p_2 - t.a) * (p_2 - t.b) * (p_2 - t.c)
    return sqrt(area_sq)
}
 
fun generate_triangles(side_limit: Int = 200): List<Triangle> {
    val result = mutableListOf<Triangle>()
    for (a in 1..side_limit) {
        for (b in 1..a) {
            for (c in a + 1 - b..b) { // skip too-small values of c, which will violate triangle inequality
                val t = Triangle(a, b, c)
                val t_area = area(t)
                if (t_area == 0.0) continue
                if (floor(t_area) == ceil(t_area) && gcd(a, gcd(b, c)) == 1) {
                    result.add(t)
                }
            }
        }
    }
    return result
}
 
fun compare(lhs: Triangle, rhs: Triangle): Boolean {
    return Triple(area(lhs), perimeter(lhs), maxOf(lhs.a, maxOf(lhs.b, lhs.c))) <
            Triple(area(rhs), perimeter(rhs), maxOf(rhs.a, maxOf(rhs.b, rhs.c)))
}
 
class area_compare {
    operator fun invoke(t: Triangle, i: Int): Boolean {
        return area(t) < i
    }
    operator fun invoke(i: Int, t: Triangle): Boolean {
        return i < area(t)
    }
}
 
fun main() {
    val tri = generate_triangles()
    println("There are ${tri.size} primitive Heronian triangles with sides up to 200\n")
 
    println("First ten when ordered by increasing area, then perimeter, then maximum sides:")
    tri.sortWith(compare(lhs, rhs))
    println("area\tperimeter\tsides")
    for (i in 0 until 10) {
        println("${area(tri[i])}\t${perimeter(tri[i])}\t\t${tri[i].a}x${tri[i].b}x${tri[i].c}")
    }
 
    println("\nAll with area 210 subject to the previous ordering:")
    val range = tri.partition(area_compare(210))
    println("area\tperimeter\tsides")
    for (it in range.first) {
        println("${area(it)}\t${perimeter(it)}\t\t${it.a}x${it.b}x${it.c}")
    }
}

import kotlinx.coroutines.*
import java.util.concurrent.locks.ReentrantLock
import kotlin.random.Random
 
const val N = 5
val names = arrayOf("Aristotle", "Kant", "Spinoza", "Marx", "Russell")
val forks = Array(N) { ReentrantLock() }
 
const val M = 5 /* think bubbles */
val topic = arrayOf("Spaghetti!", "Life", "Universe", "Everything", "Bathroom")
 
fun print(y: Int, x: Int, fmt: String, vararg args: Any) {
	synchronized(print) {
		xy(y + 1, x)
		println(fmt.format(*args))
		xy(N + 1, 1)
	}
}
 
fun eat(id: Int) {
	val f = IntArray(2)
	f[0] = f[1] = id
 
	/* make some (but not all) philosophers leftie.
	   could have been f[!id] = (id + 1) %N; for example */
	f[id and 1] = (id + 1) % N
 
	clear_eol(id)
	print(id, 12, "..oO (forks, need forks)")
 
	for (i in 0..1) {
		forks[f[i]].lock()
		if (i == 0) clear_eol(id)
 
		print(id, 12 + (f[i]!= id) * 6, "fork%d", f[i])
		/* delay 1 sec to clearly show the order of fork acquisition */
		Thread.sleep(1000)
	}
 
	for (i in 0 until 3 + Random.nextInt(8))
		print(id, 24 + i * 4, "nom")
 
	/* done nomming, give up forks (order doesn't matter) */
	for (i in 0..1) forks[f[i]].unlock()
}
 
fun think(id: Int) {
	var i: Int
	var t: Int
	var buf = ""
 
	do {
		clear_eol(id)
		buf = "..oO (${topic[t = Random.nextInt(M)]})"
 
		for (i in 0 until buf.length) {
			print(id, i+12, "%c", buf[i])
			if (i < 5) Thread.sleep(200)
		}
		Thread.sleep(500 + Random.nextInt(1000))
	} while (t!= 0)
}
 
fun philosophize(id: Int) = runBlocking {
	print(id, 1, "%10s", names[id])
	while (true) think(id), eat(id)
}
 
fun main() {
	val jobs = List(N) { i ->
		GlobalScope.launch { philosophize(i) }
	}
	runBlocking {
		jobs.forEach { it.join() }
	}
}

import java.io.EOFException
import java.io.InputStream
import java.io.OutputStream
import java.io.PrintStream
import java.util.Scanner
 
fun owp(odd: Boolean, stdin: InputStream, stdout: PrintStream): Int {
    val ch = stdin.read()
    if (!odd) {
        stdout.print(ch.toChar())
        if (ch == -1 || ch == '.'.toInt())
            return -1
        if (ch.toChar().isPunct())
            return 0
        return owp(odd, stdin, stdout)
    } else {
        if (ch.toChar().isPunct())
            return ch
        val ret = owp(odd, stdin, stdout)
        stdout.print(ch.toChar())
        return ret
    }
}
 
fun main(args: Array<String>) {
    var ch = 1
    while (true) {
        try {
            ch = owp(!ch, System.`in`, System.out)
        } catch (e: EOFException) {
            break
        }
        if (ch!= -1)
            System.out.print(ch.toChar())
        if (ch == '.'.toInt())
            break
    }
}
 
fun Char.isPunct(): Boolean {
    return this == '!' || this == '?' || this == ',' || this == ';' || this == ':'
}

