import java.lang.Math.sqrt
import java.math.BigInteger
import java.text.DecimalFormat
import java.text.DecimalFormatSymbols
import java.util.*
 
fun isqrt(x: BigInteger): BigInteger {
    var q = BigInteger.ONE
    while (q <= x) {
        q = q.shiftLeft(2)
    }
    var r = BigInteger.ZERO
    while (q > BigInteger.ONE) {
        q = q.shiftRight(2)
        val t = x - r - q
        r = r.shiftRight(1)
        if (t >= BigInteger.ZERO) {
            x = t
            r += q
        }
    }
    return r
}
 
fun commatize(n: BigInteger): String {
    val symbols = DecimalFormatSymbols(Locale.US)
    val formatter = DecimalFormat("#,###", symbols)
    return formatter.format(n)
}
 
fun main() {
    println("Integer square root for numbers 0 to 65:")
    for (n in 0..65) {
        print("${isqrt(BigInteger.valueOf(n.toLong()))} ")
    }
    println("\n")
 
    println("Integer square roots of odd powers of 7 from 1 to 73:")
    val powerWidth = 83
    val isqrtWidth = 42
    println(" n |" + " ".repeat(powerWidth) + "7 ^ n" + " |" + " ".repeat(isqrtWidth) + "isqrt(7 ^ n)")
    println("-".repeat(6 + powerWidth + isqrtWidth))
    var p = BigInteger.valueOf(7)
    for (n in 1..73 step 2) {
        println("%2d |".format(n) + " ".repeat(powerWidth) + commatize(p) + " |" + " ".repeat(isqrtWidth) + commatize(isqrt(p)))
        p *= BigInteger.valueOf(49)
    }
}

