}

import java.util.*
 
fun chowla(n: Int): Int {
	var sum = 0
	for (i in 2..Math.sqrt(n.toDouble()).toInt() step 1)
		if (n % i == 0) sum += i + if (i == n / i) 0 else n / i
	return sum
}
 
fun sieve(limit: Int): BooleanArray {
	// True denotes composite, false denotes prime.
	// Only interested in odd numbers >= 3
	val c = BooleanArray(limit)
	for (i in 3..limit / 3 * 2 step 2)
		if (!c[i] && chowla(i) == 0)
			for (j in 3 * i..limit step 2 * i)
				c[j] = true
	return c
}
 
fun main(args: Array<String>) {
	Locale.setDefault(Locale.US)
	for (i in 1..37)
		println("chowla($i) = ${chowla(i)}")
	var count = 1
	var limit = 1e7.toInt()
	var power = 100
	val c = sieve(limit)
	for (i in 3..limit step 2) {
		if (!c[i]) count++
		if (i == power - 1) {
			println("Count of primes up to $power = $count")
			power *= 10
		}
	}
 
	count = 0
	limit = 35000000
	var k = 2
	var kk = 3
	var p: Int
	for (i in 2..limit) {
		p = k * kk
		if (p > limit) break
		if (chowla(p) == p - 1) {
			println("$p is a number that is perfect")
			count++
		}
		k = kk + 1
		kk += k
	}
	println("There are $count perfect numbers <= 35,000,000")
}

