fun bernoulli(n: Int): BigInteger {
    val out = ArrayList<BigInteger>()
 
    for (m in 0..n) {
        out.add(BigInteger.ONE.divide(BigInteger.valueOf(m + 1)))
        for (j in m downTo 1) {
            out[j - 1] = BigInteger.valueOf(j).multiply(out[j - 1].subtract(out[j]))
        }
    }
    return out[0]
}
 
fun main(args: Array<String>) {
    for (n in 0..60 step if (n >= 2) 2 else 1) {
        val b = bernoulli(n)
        println("B(" + String.format("%2d", n) + ") = " + String.format("%44s", b.toString()) + " / " + b.denominator())
    }
}

import java.util.Arrays

fun chol(a: Array<DoubleArray>): Array<DoubleArray> {
    val m = a.size
    val l = Array(m) { DoubleArray(m) }
    for (i in 0 until m) {
        for (k in 0..i) {
            var sum = 0.0
            for (j in 0 until k) {
                sum += l[i][j] * l[k][j]
            }
            l[i][k] = if (i == k) Math.sqrt(a[i][i] - sum) else 1.0 / l[k][k] * (a[i][k] - sum)
        }
    }
    return l
}

