    println(Arrays.deepToString(chol(test1)))
    val test2 = arrayOf(doubleArrayOf(18.0, 22.0, 54.0, 42.0), doubleArrayOf(22.0, 70.0, 86.0, 62.0), doubleArrayOf(54.0, 86.0, 174.0, 134.0), doubleArrayOf(42.0, 62.0, 134.0, 106.0))
