import kotlin.math.pow
import kotlin.math.sqrt
 
fun rk4(f: (Double, Double) -> Double, dx: Double, x: Double, y: Double): Double {
	val k1 = dx * f(x, y)
	val k2 = dx * f(x + dx / 2, y + k1 / 2)
	val k3 = dx * f(x + dx / 2, y + k2 / 2)
	val k4 = dx * f(x + dx, y + k3)
	return y + (k1 + 2 * k2 + 2 * k3 + k4) / 6
}
 
fun rate(x: Double, y: Double): Double {
	return x * sqrt(y)
}
 
