	println("x\ty\trel. err.")
	println("------------")
	for (i = 0; i < y.size; i += 10) {
		x = 0.0 + 0.1 * i
		y2 = (x * x / 4 + 1).pow(2)
		println("${x}\t${y[i]}\t${y[i] / y2 - 1}")
	}
}

package main
 
import (
    "fmt"
    "math"
    "math/rand"
    "os"
    "strconv"
    "time"
)
 
const sSuits = "CDHS"
const sNums = "A23456789TJQK"
const rMax32 = math.MaxInt32
 
var seed = 1
 
fun rnd() : Int {
    seed = (seed*214013 + 2531011) and rMax32
    return seed shr 16
}
 
fun deal(s : Int) : IntArray {
    seed = s
    val t = IntArray(52)
    for (i in 0..51) {
        t[i] = 51 - i
    }
    for (i in 0..50) {
        val j = 51 - rnd() % (52 - i)
        val tmp = t[i]
        t[i] = t[j]
        t[j] = tmp
    }
    return t
}
 
fun show(cs : IntArray) {
    for (i in cs.indices) {
        print(" ${sNums[cs[i] / 4]}${sSuits[cs[i] % 4]}")
        if (i + 1) % 8 == 0 || i + 1 == cs.size {
            println()
        }
    }
}
 
fun main(args : Array<String>) {
    var game = 0
    when (args.size) {
        0 -> {
            rand.seed(time.Now().UnixNano())
            game = 1 + rand.Intn(32000)
        }
        1 -> {
            val err = 0
            game = strconv.Atoi(args[0])
            if (err == 0 && game >= 1 && game <= 32000) {
                break
            }
            // fallthrough
        }
        else -> {
            println("usage: deal [game]")
            println("       where game is a number in the range 1 to 32000")
            return
        }
    }
    println("\nGame #$game")
    show(deal(game))
}

