const val boxW = 41      // Galton box width
const val boxH = 37      // Galton box height.
const val pinsBaseW = 19 // Pins triangle base.
const val nMaxBalls = 55 // Number of balls.
 
const val centerH = pinsBaseW + (boxW-pinsBaseW*2+1)/2 - 1
 
const val empty  =''
const val ball   = 'o'
const val wall   = '|'
const val corner = '+'
const val floor  = '-'
const val pin    = '.'
 
class Ball(var x: Int, var y: Int)
 
fun newBall(x: Int, y: Int): Ball {
    if (box[y][x]!= empty) {
        throw Exception("Tried to create a new ball in a non-empty cell. Program terminated.")
    }
    val b = Ball(x, y)
    box[y][x] = ball
    return b
}
 
fun Ball.doStep() {
    if (y <= 0) {
        return // Reached the bottom of the box.
    }
    val cell = box[y-1][x]
    when (cell) {
        empty -> {
            box[y][x] = empty
            y--
            box[y][x] = ball
        }
        pin -> {
            box[y][x] = empty
            y--
            if (box[y][x-1] == empty && box[y][x+1] == empty) {
                x += Random.nextInt(2)*2 - 1
                box[y][x] = ball
                return
            } else if (box[y][x-1] == empty) {
                x++
            } else {
                x--
            }
            box[y][x] = ball
        }
        else -> {
            // It's frozen - it always piles on other balls.
        }
    }
}
 
typealias Cell = Char
 
/* Galton box. Will be printed upside down. */
val box = Array(boxH) { Array(boxW) { empty } }
 
fun initializeBox() {
    // Set ceiling and floor
    box[0][0] = corner
    box[0][boxW-1] = corner
    for (i in 1 until boxW-1) {
        box[0][i] = floor
    }
    for (i in 0 until boxW) {
        box[boxH-1][i] = box[0][i]
    }
 
    // Set walls
    for (r in 1 until boxH-1) {
        box[r][0] = wall
        box[r][boxW-1] = wall
    }
 
    // Set rest to empty initially
    for (i in 1 until boxH-1) {
        for (j in 1 until boxW-1) {
            box[i][j] = empty
        }
    }
 
    // Set pins
    for (nPins in 1..pinsBaseW) {
        for (p in 0 until nPins) {
            box[boxH-2-nPins][centerH+1-nPins+p*2] = pin
        }
    }
}
 
fun drawBox() {
    for (r in boxH - 1 downTo 0) {
        for (c in 0 until boxW) {
            print(box[r][c])
        }
        println()
    }
}
 
fun main() {
    initializeBox()
    val balls = mutableListOf<Ball>()
    for (i in 0 until nMaxBalls+boxH) {
        println("\nStep $i :")
        if (i < nMaxBalls) {
            balls.add(newBall(centerH, boxH-2)) // add ball
        }
        drawBox()
 
        // Next step for the simulation.
        // Frozen balls are kept in balls slice for simplicity
        for (b in balls) {
            b.doStep()
        }
    }
}

