import java.util.ArrayList
import java.util.Arrays
import java.util.Collections
import java.util.List
 
class Edit(val c1: Char, val c2: Char, val n: Int, val next: Edit?)
 
fun leven(a: String, b: String) {
	val la = a.length
	val lb = b.length
	val tbl = Array(la + 1) { arrayOfNulls<Edit>(lb + 1) }
	for (i in 0..la) {
		for (j in 0..lb) {
			tbl[i][j] = Edit(' ','', 0, null)
		}
	}
 
	for (i in la downTo 0) {
		val aa = a.substring(i)
		for (j in lb downTo 0) {
			val bb = b.substring(j)
			if (aa.isEmpty() && bb.isEmpty()) continue
 
			val e = tbl[i][j]
			val repl = tbl[i + 1][j + 1]
			val dela = tbl[i + 1][j]
			val delb = tbl[i][j + 1]
 
			e.c1 = aa[0]
			e.c2 = bb[0]
			if (aa.isEmpty()) {
				e.next = delb
				e.n = e.next!!.n + 1
				continue
			}
			if (bb.isEmpty()) {
				e.next = dela
				e.n = e.next!!.n + 1
				continue
			}
 
			e.next = repl
			if (aa[0] == bb[0]) {
				e.n = e.next!!.n
				continue
			}
 
			if (e.next!!.n > delb.n) {
				e.next = delb
				e.c1 =''
			}
			if (e.next!!.n > dela.n) {
				e.next = dela
				e.c1 = aa[0]
				e.c2 =''
			}
			e.n = e.next!!.n + 1
		}
	}
 
	var p = tbl[0][0]
	println("${a} -> ${b}: ${p.n} edits")
 
	while (p.next!= null) {
		if (p.c1 == p.c2)
			print(p.c1)
		else {
			print('(')
			if (p.c1!='') print(p.c1)
			print(',')
			if (p.c2!='') print(p.c2)
			print(')')
		}
 
		p = p.next!!
	}
	println()
}
 
fun main(args: Array<String>) {
	leven("raisethysword", "rosettacode")
}

