import kotlin.math.round
import kotlin.system.measureTimeMillis

fun main() {
    val n = 100
    val ts = mutableListOf<Int>()
    val mc = mutableListOf(1)
    val sums = mutableSetOf(2)
    val st = measureTimeMillis {
        for (i in 1 until n) {
            for (j in mc[i - 1] + 1 until Int.MAX_VALUE) {
                mc.add(j)
                for (k in 0..i) {
                    val sum = mc[k] + j
                    if (sums.contains(sum)) {
                        ts.clear()
                        break
                    }
                    ts.add(sum)
                }
                if (ts.isNotEmpty()) {
                    sums.addAll(ts)
                    break
                }
            }
        }
    }
    val et = (System.currentTimeMillis() - st).toDouble()
    val s = " of the Mian-Chowla sequence are:\n"
    println("The first 30 terms$s${mc.subList(0, 29).joinToString(" ")}")
    println("\nTerms 91 to 100$s${mc.subList(90, 99).joinToString(" ")}")
    println("\nComputation time was ${round(et)}ms.")
}

