// weirds :: Gen [Int]
fun weirds(): Sequence<Int> = sequence {
    var x = 1
    var i = 1
    while (true) {
        x = until(isWeird, ::succ, x)
        println("$i -> $x")
        yield(x)
        x = 1 + x
        i = 1 + i
    }
}

// isWeird :: Int -> Bool
fun isWeird(n: Int): Boolean {
    val ds = descProperDivisors(n)
    val d = sum(ds) - n
    return 0 < d &&!hasSum(d, ds)
}

// hasSum :: Int -> [Int] -> Bool
fun hasSum(n: Int, xs: List<Int>): Boolean {
    fun go(n: Int, xs: List<Int>): Boolean =
        if (0 < xs.size) {
            val h = xs[0]
            val t = xs.slice(1 until xs.size)
            n < h || n == h || hasSum(n - h, t) || hasSum(n, t)
        } else false
    return go(n, xs)
}

// descProperDivisors :: Int -> [Int]
fun descProperDivisors(n: Int): List<Int> {
    val rRoot = Math.sqrt(n.toDouble())
    val intRoot = Math.floor(rRoot).toInt()
    val blnPerfect = rRoot == intRoot.toDouble()
    val lows = enumFromThenTo(intRoot, intRoot - 1, 1)
       .filter { x -> (n % x) == 0 }
    return (reverse(lows)
       .slice(1 until lows.size)
       .map { x -> n / x })
       .plus((if (blnPerfect) tail else id)(lows))
}

// GENERIC FUNCTIONS ----------------------------

// enumFromThenTo :: Int -> Int -> Int -> [Int]
fun enumFromThenTo(x1: Int, x2: Int, y: Int): List<Int> {
    val d = x2 - x1
    return List(Math.floor(y - x2 / d + 2).toInt()) { x1 + (d * it) }
}

// id :: a -> a
fun <A> id(x: A): A = x

// reverse :: [a] -> [a]
fun <A> reverse(xs: List<A>): List<A> =
    xs.reversed()

// succ :: Enum a => a -> a
fun succ(x: Int): Int = 1 + x

// sum :: [Num] -> Num
fun sum(xs: List<Int>): Int = xs.sum()

// tail :: [a] -> [a]
fun <A> tail(xs: List<A>): List<A> =
    if (0 < xs.size) xs.slice(1 until xs.size) else emptyList()

// take :: Int -> [a] -> [a]
// take :: Int -> String -> String
fun <A> take(n: Int, xs: List<A>): List<A> =
    xs.slice(0 until n)

// until :: (a -> Bool) -> (a -> a) -> a -> a
fun <A> until(p: (A) -> Boolean, f: (A) -> A, x: A): A {
    var v = x
    while (!p(v)) v = f(v)
    return v
}

