import kotlin.random.Random
 
fun isSorted(seq: List<Int>): Boolean {
    if (seq.size < 2) {
        return true
    }
    // Look for any instance where the previous number is larger than the following
    return!seq.zip(seq.drop(1)).any { (prev, foll) -> prev > foll }
}
 
fun main() {
    println(
        """Number reversal game:
    Given a jumbled list of the numbers 1 to 9, put the numbers in order.
    Each attempt you can reverse up to n digits starting from the left.
    The score is the count of the reversals needed to attain the ascending order."""
    )
    val sequence: MutableList<Int> = (1..9).toMutableList()
    while (isSorted(sequence)) {
        sequence.shuffle()
    }
 
    var attempt = 1
    while (!isSorted(sequence)) {
        println("Attempt $attempt: $sequence - How many numbers do you want to flip?")
        val flip = readLine()!!.toInt()
        sequence.subList(0, flip).reverse()
        attempt++
    }
    println("Congrats! It took you ${attempt - 1} attempts to sort the sequence.")
}

import kotlin.math.sqrt

class PrimeGenerator {
    private var current = 1
    private var primes = mutableListOf<Int>()

    fun next(): Int {
        current++
        while (!isPrime(current)) {
            current++
        }
        primes.add(current)
        return current
    }

    fun take(n: Int): List<Int> {
        while (primes.size < n) {
            next()
        }
        return primes.subList(0, n)
    }

    private fun isPrime(n: Int): Boolean {
        if (n <= 1) return false
        if (n == 2) return true
        if (n % 2 == 0) return false
        for (i in 3..sqrt(n.toDouble()).toInt() step 2) {
            if (n % i == 0) return false
        }
        return true
    }
}

fun main() {
    val pg = PrimeGenerator()
    println(pg.take(10))
    println(pg.next())
}

