fun subleq(a: IntArray) {
    var i = 0
    try {
        while (i >= 0) {
            if (a[i] == -1) {
                a[a[i + 1]] = readLine()!![0].toInt()
            } else if (a[i + 1] == -1) {
                print(a[a[i]].toChar())
            } else {
                a[a[i + 1]] -= a[a[i]]
                if (a[a[i + 1]] <= 0) {
                    i = a[i + 2]
                    continue
                }
            }
            i += 3
        }
    } catch (e: Exception) {
        println("abort")
        println(a.contentToString())
    }
}
 
