import java.util.ArrayList
import java.util.Arrays
 
val STR_DEMO = "one^|uno||three^^^^|four^^^|^cuatro|"
val SEP = '|'
val ESC = '^'
 
typealias Str = String
 
fun main(args: Array<String>) {
    val s = STR_DEMO
    val q = ElQ(s, SEP, ESC)
    val list = Tokenize(s, SEP, ESC, q)
 
    if (list!= null) {
        println("\n Original string: $STR_DEMO\n\n")
        println(" $q tokens:\n\n")
 
        for (i in 0 until q) {
            println(" ${i + 1}. ${list[i]}")
        }
    }
}
 
fun ElQ(s: String, sep: Char, esc: Char): Int {
    var q = 1
    var e = 0
 
    for (c in s) {
        if (c == esc) {
            e = if (e == 0) 1 else 0
        } else if (c == sep) {
            q += if (e == 0) 1 else 0
        } else {
            e = 0
        }
    }
 
    return q
}
 
fun Tokenize(s: String, sep: Char, esc: Char, q: Int): Array<String>? {
    var list: Array<String>? = null
 
    list = Array(q, { "" })
 
    if (list!= null) {
        var e = 0
        var i = 0
        list[i++] = s
 
        for (c in s) {
            if (c == esc) {
                e = if (e == 0) 1 else 0
            } else if (c == sep && e == 0) {
                list[i++] = c.toString()
            } else {
                e = 0
            }
        }
    }
 
    return list
}

