import java.util.List
import java.util.Map
import java.util.Objects
 
fun main(args: Array<String>) {
    val nbl = listOf(
        mapOf(10L to -2),
        mapOf(146L to -3),
        mapOf(15L to -10),
        mapOf(-4393346L to -62)
    )
    for (p in nbl) {
        val ns = encodeNegBase(p.keys.first(), p.values.first())
        println(String.format("%12d encoded in base %-3d = %s", p.keys.first(), p.values.first(), ns))
        val n = decodeNegBase(ns, p.values.first())
        println(String.format("%12s decoded in base %-3d = %d", ns, p.values.first(), n))
    }
}
 
private fun encodeNegBase(n: Long, b: Int): String {
    if (b < -62 || b > -1) throw IllegalArgumentException("Parameter b is out of bounds")
    if (n == 0L) return "0"
    val out = StringBuilder()
    var nn = n
    while (nn!= 0L) {
        val rem = (nn % b).toInt()
        nn /= b
        if (rem < 0) {
            nn++
            rem -= b
        }
        out.append(DIGITS[rem])
    }
    out.reverse()
    return out.toString()
}
 
private fun decodeNegBase(ns: String, b: Int): Long {
    if (b < -62 || b > -1) throw IllegalArgumentException("Parameter b is out of bounds")
    if (Objects.equals(ns, "0")) return 0
    var total = 0L
    var bb = 1L
    for (i in ns.length - 1 downTo 0) {
        val c = ns[i]
        total += DIGITS.indexOf(c) * bb
        bb *= b
    }
    return total
}
 
private const val DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"

import kotlin.math.abs
import kotlin.math.sqrt
 
data class Point(val x: Double, val y: Double)
 
// Returns the distance from point p to the line between p1 and p2
fun perpendicularDistance(p: Point, p1: Point, p2: Point): Double {
    val dx = p2.x - p1.x
    val dy = p2.y - p1.y
    val d = sqrt(dx * dx + dy * dy)
    return abs(p.x * dy - p.y * dx + p2.x * p1.y - p2.y * p1.x) / d
}
 
// Simplify an array of points using the Ramer–Douglas–Peucker algorithm.
// Returns the number of output points.
fun douglasPeucker(points: Array<Point>, n: Int, epsilon: Double, dest: Array<Point>, destlen: Int): Int {
    assert(n >= 2)
    assert(epsilon >= 0.0)
    var maxDist = 0.0
    var index = 0
    for (i in 1 until n - 1) {
        val dist = perpendicularDistance(points[i], points[0], points[n - 1])
        if (dist > maxDist) {
            maxDist = dist
            index = i
        }
    }
    if (maxDist > epsilon) {
        val n1 = douglasPeucker(points, index + 1, epsilon, dest, destlen)
        if (destlen >= n1 - 1) {
            destlen -= n1 - 1
            dest += n1 - 1
        } else {
            destlen = 0
        }
        val n2 = douglasPeucker(points + index, n - index, epsilon, dest, destlen)
        return n1 + n2 - 1
    }
    if (destlen >= 2) {
        dest[0] = points[0]
        dest[1] = points[n - 1]
    }
    return 2
}
 
fun printPoints(points: Array<Point>, n: Int) {
    for (i in 0 until n) {
        if (i > 0)
            print(" ")
        print("(${points[i].x}, ${points[i].y})")
    }
    println()
}
 
fun main() {
    val points = arrayOf(
        Point(0.0, 0.0), Point(1.0, 0.1), Point(2.0, -0.1), Point(3.0, 5.0), Point(4.0, 6.0),
        Point(5.0, 7.0), Point(6.0, 8.1), Point(7.0, 9.0), Point(8.0, 9.0), Point(9.0, 9.0)
    )
    val len = points.size
    val out = Array(len) { Point(0.0, 0.0) }
    val n = douglasPeucker(points, len, 1.0, out, len)
    printPoints(out, n)
}

