import java.util.ArrayList
import java.util.List
 
fun main(args: Array<String>) {
    val set = listOf("iced", "jam", "plain")
    val combinations = generateCombinations(set, 2)
 
    for (combination in combinations) {
        val combinationStr = combination.joinToString(" ")
        println(combinationStr)
    }
 
    val donuts = (1..10).toList()
 
    val donutsCombinationsNumber = generateCombinations(donuts, 3).size
 
    println("$donutsCombinationsNumber ways to order 3 donuts given 10 types")
}
 
fun <T> generateCombinations(combinationList: List<T>, k: Int): List<List<T>> {
    val combinations = ArrayList<List<T>>()
 
    if (k == 0) {
        val emptyCombination = ArrayList<T>()
        combinations.add(emptyCombination)
 
        return combinations
    }
 
    if (combinationList.isEmpty()) {
        return combinations
    }
 
    val head = combinationList[0]
    val copiedCombinationList = ArrayList(combinationList)
 
    val subcombinations = generateCombinations(copiedCombinationList, k - 1)
 
    for (subcombination in subcombinations) {
        subcombination.add(0, head)
        combinations.add(subcombination)
    }
 
    combinationList.removeAt(0)
    combinations.addAll(generateCombinations(combinationList, k))
 
    return combinations
}

/**
 * RDoc is documented here[http://www.ruby-doc.org/core/classes/RDoc.html].
 *
 * This is a class documentation comment.  This text shows at the top of the page
 * for the class.
 *
 * Comments can be written inside "=begin rdoc"/"end" blocks or
 * in normal '#' comment blocks.
 *
 * There are no '@parameters' like javadoc, but 'name-value' lists can be written:
 * Author:: 
 * Date:: today
 */
class Doc {
    /**
     * This is a comment for a Constant
     */
    val Constant: Any? = null

    /**
     * This is a method comment.  Parameters and return values can be named
     * with the "call-seq" directive.
     *
     * call-seq:
     *   a_method(first_arg, second_arg) -> return_value
     */
    fun a_method(arg1: Any?, arg2: String = "default value"): Any? {
        return do_stuff()
    }

    /**
     * Class methods will be shown in a separate section of the generated documentation.
     */
    fun class_method(): Any? {
        return Constant
    }
}

