object Josephus {
    fun init(n: Int): Josephus {
        val head = Josephus()
        var current = head
        for (i in 0 until n - 1) {
            current.label = i + 1
            current.next = Josephus()
            current.next!!.prev = current
            current = current.next!!
        }
        current.label = n
        current.next = head
        head.prev = current
        return head
    }

    fun kill(spacing: Int): Int {
        var current = this
        while (current.next!= this) {
            for (i in 0 until spacing - 1) {
                current = current.next!!
            }
            current.prev!!.next = current.next
            current.next!!.prev = current.prev
            current = current.next!!
        }
        return current.label
    }

    var label: Int = 0
    var next: Josephus? = null
    var prev: Josephus? = null
}

