class BinarySearchTree {
    private var root: Node? = null
 
    private inner class Node(var key: Int) {
        var left: Node? = null
        var right: Node? = null
    }
 
    fun insert(key: Int): Boolean {
        if (root == null) {
            root = Node(key)
        } else {
            var n = root
            var parent: Node
            while (true) {
                if (n!!.key == key)
                    return false
 
                parent = n
                val goLeft = key < n.key
                n = if (goLeft) n.left else n.right
 
                if (n == null) {
                    if (goLeft) {
                        parent.left = Node(key)
                    } else {
                        parent.right = Node(key)
                    }
                    break
                }
            }
        }
        return true
    }
 
    fun display() {
        val height = 5
        val width = 64
 
        val len = width * height * 2 + 2
        val sb = StringBuilder(len)
        for (i in 1..len)
            sb.append(if (i < len - 2 && i % width == 0) "\n" else'')
 
        displayR(sb, width / 2, 1, width / 4, width, root, " ")
        println(sb)
    }
 
    private fun displayR(sb: StringBuilder, c: Int, r: Int, d: Int, w: Int, n: Node?, edge: String) {
        if (n!= null) {
            displayR(sb, c - d, r + 2, d / 2, w, n.left, " /")
 
            val s = n.key.toString()
            val idx1 = r * w + c - (s.length + 1) / 2
            val idx2 = idx1 + s.length
            val idx3 = idx1 - w
            if (idx2 < sb.length)
                sb.replace(idx1, idx2, s).replace(idx3, idx3 + 2, edge)
 
            displayR(sb, c + d, r + 2, d / 2, w, n.right, "\\ ")
        }
    }
}

