// inverted index representation
var index map[String]List<Int> // ints index into indexed
var indexed List<Doc>
 
data class Doc(val file: String, val title: String)
 
fun main(args: Array<String>) {
    // initialize representation
    index = HashMap()
 
    // build index
    if (indexDir("docs")) {
        fmt.Println(err)
        return
    }
 
    // run user interface
    ui()
}
 
fun indexDir(dir: String): Boolean {
    val df = File(dir)
    if (!df.exists()) {
        return false
    }
    val fis = df.listFiles()
    if (fis.size == 0) {
        return false
    }
    var indexed = 0
    for (fi in fis) {
        if (!fi.isDirectory) {
            if (indexFile(dir + "/" + fi.name)) {
                indexed++
            }
        }
    }
    return true
}
 
fun indexFile(fn: String): Boolean {
    val f = File(fn)
    if (!f.exists()) {
        return false
    }
 
    // register new file
    val x = indexed.size
    indexed.add(Doc(fn, fn))
    val pdoc = indexed[x]
 
    // scan lines
    val r = BufferedReader(FileReader(f))
    var lines = 0
    while (true) {
        val b = r.readLine()
        when {
            b == null -> return true
            b.length > 0 -> {
                // in a real program you would write code
                // to skip the Gutenberg document header
                // and not index it.
                pdoc.title = b
            }
        }
        // index line of text in b
        // again, in a real program you would write a much
        // nicer word splitter.
        wordLoop@ for (bword in b.split(" ")) {
            val bword = bword.trim(".,-~?!\"'`;:()<>[]{}\\|/=_+*&^%$#@")
            if (bword.length > 0) {
                val word = bword
                val dl = index[word]
                for (d in dl) {
                    if (d == x) {
                        continue@wordLoop
                    }
                }
                index[word] = dl.add(x)
            }
        }
    }
    return true
}
 
fun ui() {
    println(index.size, "words indexed in", indexed.size, "files")
    println("enter single words to search for")
    println("enter a blank line when done")
    var word: String
    while (true) {
