            }
            else -> {
                println(dl.size, "matches:")
                for (d in dl) {
                    println("   ", indexed[d].file, indexed[d].title)
                }
            }
        }
    }
}

fun doubleEvenMagicSquare(n: Int): Array<IntArray> {
    if (n % 4 > 0) throw IllegalArgumentException("Need multiple of four")
    val block_size = n / 4
    val max = n * n
    val pre_pat = booleanArrayOf(true, false, false, true, false, true, true, false)
    val pattern = pre_pat.flatMap { b -> List(block_size) { b } } * block_size
    val flat_ar = pattern.mapIndexed { num, yes -> if (yes) num + 1 else max - num }
    return flat_ar.chunked(n).toTypedArray()
}
 
fun toString(square: Array<IntArray>): String {
    val n = square.size
    val fmt = "%${(n * n).toString().length + 1}d".repeat(n)
    return square.joinToString("\n") { row -> fmt.format(*row.toTypedArray()) }
}
 
println(toString(doubleEvenMagicSquare(8)))

fun <T> comb(arr: Array<T>, n: Int) {
  val inclArr = BooleanArray(arr.size, { false })
  combIntern(arr, n, inclArr, 0)
}
 
fun <T> combIntern(arr: Array<T>, n: Int, inclArr: BooleanArray, index: Int) {
  if (arr.size < n + index) { return }
  if (n == 0) {
    for (i in 0..arr.size - 1) {
      if (inclArr[i]) { print("${arr[i]} ") }
    }
    print("\n")
    return
  }
 
  inclArr[index] = true
  combIntern(arr, n - 1, inclArr, index + 1)
  inclArr[index] = false
 
  combIntern(arr, n, inclArr, index + 1)
}
 
fun main(args: Array<String>) {
  val arr1 = arrayOf(1, 2, 3, 4, 5)
  comb(arr1, 3)
 
  val arr2 = arrayOf("A", "B", "C", "D", "E")
  comb(arr2, 3)
}

class LinkedList(value: Int, next: LinkedList?) {
    var _value: Int = value
    var _next: LinkedList? = next

    fun value(): Int {
        return _value
    }

    fun value(value: Int) {
        _value = value
    }

    fun next(): LinkedList? {
        return _next
    }

    fun next(next: LinkedList?) {
        _next = next
    }
}

fun createLinkedListFromArray(ary: IntArray): LinkedList {
    val head = LinkedList(ary[0], null)
    var prev = head
    for (i in 1..ary.size - 1) {
        val node = LinkedList(ary[i], null)
        prev.next(node)
        prev = node
    }
    return head
}

val head = createLinkedListFromArray(intArrayOf(10, 20, 30, 40))

class SimpleMovingAverage(val period: Int) {
    val numbers = mutableListOf<Int>()
 
    fun addNumber(number: Int): Double {
        numbers.add(number)
 
        if (numbers.size > period) {
            numbers.removeAt(0)
        }
 
        if (numbers.isEmpty()) {
            return 0.0
        } else {
            val sum = numbers.sum()
            return sum.toDouble() / numbers.size
        }
    }
}
 
fun main(args: Array<String>) {
    for (period in listOf(3, 5)) {
        println("Moving average with period $period")
 
        val sma = SimpleMovingAverage(period)
        for (i in listOf(1, 2, 3, 4, 5, 5, 4, 3, 2, 1)) {
            println("Number: $i | Average: ${sma.addNumber(i)}")
        }
    }
}

import kotlin.system.exitProcess
import kotlinx.cinterop.*
import platform.posix.*
 
fun talk(s: String) {
	val pid = fork()
	if (pid < 0) {
		perror("fork")
		exitProcess(1)
	}
 
	if (pid == 0) {
		execlp("espeak", "espeak", s, null)
		perror("espeak")
		_exit(1)
	}
 
	val status = malloc(4)
	waitpid(pid, status, 0)
	if (!WIFEXITED(status) || WEXITSTATUS(status)!= 0)
		exitProcess(1)
}
 
fun main() {
	talk("This is an example of speech synthesis.")
}

class XorShiftStar {
    private val MAGIC = 0x2545F4914F6CDD1D.toLong()
    private var state: Long = 0
 
    fun seed(num: Long) {
        state = num
    }
 
    fun nextInt(): Int {
        var x: Long
        var answer: Int
 
        x = state
        x = x xor (x ushr 12)
        x = x xor (x shl 25)
        x = x xor (x ushr 27)
        state = x
        answer = (x * MAGIC).toInt() ushr 32
 
        return answer
    }
 
    fun nextFloat(): Float {
        return Integer.toUnsignedLong(nextInt()).toFloat() / (1L shl 32)
    }
 
    companion object {
        @JvmStatic
        fun main(args: Array<String>) {
            val rng = XorShiftStar()
            rng.seed(1234567)
            println(Integer.toUnsignedString(rng.nextInt()))
            println(Integer.toUnsignedString(rng.nextInt()))
            println(Integer.toUnsignedString(rng.nextInt()))
            println(Integer.toUnsignedString(rng.nextInt()))
            println(Integer.toUnsignedString(rng.nextInt()))
            println()
 
            val counts = intArrayOf(0, 0, 0, 0, 0)
            rng.seed(987654321)
            for (i in 0..99999) {
                val j = Math.floor(rng.nextFloat() * 5.0).toInt()
                counts[j]++
            }
            for (i in counts.indices) {
                println(String.format("%d: %d", i, counts[i]))
            }
        }
    }
}

import java.util.*
 
class Node(val n: Int) {
    var lowLink: Int = 0
    var index: Int = -1
}
 
class Graph(val v: HashSet<Node>, val adj: HashMap<Node, HashSet<Node>>) {
    fun tarjan() {
        var index = 0
        val s = Stack<Node>()
 
        fun strongConnect(v: Node) {
            v.index = index
            v.lowLink = index
 
            index++
            s.push(v)
 
            for (w in adj[v]!!) {
                if (w.index < 0) {
                    strongConnect(w)
                    v.lowLink = Math.min(v.lowLink, w.lowLink)
                } else if (s.contains(w)) {
                    v.lowLink = Math.min(v.lowLink, w.index)
                }
            }
 
            if (v.lowLink == v.index) {
                print("SCC: ")
 
                var w: Node
                do {
                    w = s.pop()
                    print("${w.n} ")
                } while (w!= v)
 
                println()
            }
        }
 
        for (v in v) {
            if (v.index < 0) {
                strongConnect(v)
            }
        }
    }
}

// Parses the input string for the numerators and denominators
fun compile(prog: String, numArr: MutableList<String>, denArr: MutableList<String>): List<MutableList<String>> {
    val regex = Regex("\\s*(\\d*)\\s*/\\s*(\\d*)\\s*(.*)", RegexOption.MULTILINE)
    var result: MatchResult?
    while (result = regex.find(prog)) {
        numArr.add(result.groupValues[1])
        denArr.add(result.groupValues[2])
        prog = result.groupValues[3]
    }
    return listOf(numArr, denArr)
}
 
// Outputs the result of the compile stage
fun dump(numArr: MutableList<String>, denArr: MutableList<String>): String {
    var output = ""
    for (i in numArr.indices) {
        output += "${numArr[i]}/${denArr[i]} "
    }
    return "$output<br>"
}
 
// Step
fun step(val: Int, numArr: MutableList<String>, denArr: MutableList<String>): Int {
    var i = 0
    while (i < denArr.size && val % denArr[i].toInt()!= 0) i++
    return numArr[i].toInt() * val / denArr[i].toInt()
}
 
// Executes Fractran
fun exec(val: Int, i: Int, limit: Int, numArr: MutableList<String>, denArr: MutableList<String>): String {
    var output = ""
    while (val!= 0 && i < limit) {
        output += "$i: $val<br>"
        val = step(val, numArr, denArr)
        i++
    }
    return output
}
 
