fun divisors(n: Int): List<Int> {
    val divs = mutableListOf(1)
    for (ii in 2..(n.toDouble().pow(0.5).toInt() + 3)) {
        if (n % ii == 0) {
            divs.add(ii)
            divs.add((n / ii).toInt())
        }
    }
    divs.add(n)
    return divs.distinct()
}
 
 
fun isPrime(n: Int): Boolean {
    return divisors(n).size == 2
}
 
 
fun primes(): Sequence<Int> {
    var ii = 1
    return generateSequence {
        ii += 1
        if (isPrime(ii)) {
            ii
        } else {
            null
        }
    }
}
 
 
fun prime(n: Int): Int {
    return primes().elementAt(n - 1)
}
 
 
fun nDivisors(n: Int): Sequence<Int> {
    var ii = 0
    return generateSequence {
        ii += 1
        if (divisors(ii).size == n) {
            ii
        } else {
            null
        }
    }
}
 
 
fun sequence(maxN: Int? = null): Sequence<Int> {
    if (maxN!= null) {
        return generateSequence {
            var ii = 1
            while (ii <= maxN) {
                if (isPrime(ii)) {
                    return@generateSequence prime(ii).toDouble().pow(ii - 1).toInt()
                } else {
                    val generator = nDivisors(ii)
                    for (jj in 0 until ii - 1) {
                        generator.elementAt(jj)
                    }
                    return@generateSequence generator.elementAt(ii - 1)
                }
                ii += 1
            }
        }
    } else {
        var ii = 1
        return generateSequence {
            if (isPrime(ii)) {
                return@generateSequence prime(ii).toDouble().pow(ii - 1).toInt()
            } else {
                val generator = nDivisors(ii)
                for (jj in 0 until ii - 1) {
                    generator.elementAt(jj)
                }
                return@generateSequence generator.elementAt(ii - 1)
            }
            ii += 1
        }
    }
}
 
 
fun main() {
    sequence(15).forEach { println(it) }
}

import java.util.Calendar
import java.util.GregorianCalendar
 
object DiscordianDate {
    val seasons = arrayOf("Chaos", "Discord", "Confusion", "Bureaucracy", "The Aftermath")
 
    val weekday = arrayOf("Sweetmorn", "Boomtime", "Pungenday", "Prickle-Prickle", "Setting Orange")
 
    val apostle = arrayOf("Mungday", "Mojoday", "Syaday", "Zaraday", "Maladay")
 
    val holiday = arrayOf("Chaoflux", "Discoflux", "Confuflux", "Bureflux", "Afflux")
 
    fun discordianDate(date: GregorianCalendar): String {
        var y = date.get(Calendar.YEAR)
        var yold = y + 1166
        var dayOfYear = date.get(Calendar.DAY_OF_YEAR)
 
        if (date.isLeapYear(y)) {
            if (dayOfYear == 60)
                return "St. Tib's Day, in the YOLD " + yold
            else if (dayOfYear > 60)
                dayOfYear--
        }
 
        dayOfYear--
 
        var seasonDay = dayOfYear % 73 + 1
        if (seasonDay == 5)
            return apostle[dayOfYear / 73] + ", in the YOLD " + yold
        if (seasonDay == 50)
            return holiday[dayOfYear / 73] + ", in the YOLD " + yold
 
        val season = seasons[dayOfYear / 73]
        val dayOfWeek = weekday[dayOfYear % 5]
 
        return String.format("%s, day %s of %s in the YOLD %s",
                dayOfWeek, seasonDay, season, yold)
    }
 
    @JvmStatic
    fun main(args: Array<String>) {
 
        println(discordianDate(GregorianCalendar()))
 
        test(2010, 6, 22, "Pungenday, day 57 of Confusion in the YOLD 3176")
        test(2012, 1, 28, "Prickle-Prickle, day 59 of Chaos in the YOLD 3178")
        test(2012, 1, 29, "St. Tib's Day, in the YOLD 3178")
        test(2012, 2, 1, "Setting Orange, day 60 of Chaos in the YOLD 3178")
        test(2010, 0, 5, "Mungday, in the YOLD 3176")
        test(2011, 4, 3, "Discoflux, in the YOLD 3177")
        test(2015, 9, 19, "Boomtime, day 73 of Bureaucracy in the YOLD 3181")
    }
 
    private fun test(y: Int, m: Int, d: Int, result: String) {
        assert(discordianDate(GregorianCalendar(y, m, d)) == result)
    }
}

fun printVerse(name: String) {
    val firstLetterAndConsonantsRe = Regex("^.[^aeiyou]*", RegexOption.IGNORE_CASE)
    val fullName = name.capitalize()
    val suffixed = when (fullName[0]) {
        'A', 'E', 'I', 'O', 'U' -> name.toLowerCase()
        else -> fullName.replaceFirst(firstLetterAndConsonantsRe, "")
    }
    val bName = "b$suffixed"
    val fName = "f$suffixed"
    val mName = "m$suffixed"
    when (fullName[0]) {
        'B' -> bName = suffixed
        'F' -> fName = suffixed
        'M' -> mName = suffixed
    }
    println("""
        $fullName, $fullName, bo-$bName
        Banana-fana fo-$fName
        Fee-fi-mo-$mName
        $fullName!
    """.trimIndent())
}

fun main(args: Array<String>) {
    listOf("Gary", "Earl", "Billy", "Felix", "Mary", "Steve", "Chris", "Byron").forEach {
        printVerse(it)
    }
}

import kotlin.math.floor
import kotlin.math.roundToInt
 
fun median(x: DoubleArray, start: Int, endInclusive: Int): Double {
    val size = endInclusive - start + 1
    if (size <= 0) {
        println("Array slice cannot be empty")
        exitProcess(1)
    }
    val m = start + size / 2
    return if (size % 2 == 1) x[m] else (x[m - 1] + x[m]) / 2.0
}
 
fun fivenum(x: DoubleArray, result: DoubleArray, xLen: Int): Int {
    for (i in 0 until xLen) {
        if (x[i].isNaN()) {
            println("Unable to deal with arrays containing NaN")
            return 1
        }
    }
    x.sort()
    result[0] = x[0]
    result[2] = median(x, 0, xLen - 1)
    result[4] = x[xLen - 1]
    val m = xLen / 2
    val lowerEnd = if (xLen % 2 == 1) m else m - 1
    result[1] = median(x, 0, lowerEnd)
    result[3] = median(x, m, xLen - 1)
    return 0
}
 
fun show(result: DoubleArray, places: Int) {
    val f = "%.${places}lf"
    print("[")
    for (i in 0..4) {
        print(f.format(result[i]))
        if (i < 4) print(", ")
    }
    println("]")
}
 
fun main() {
    val result = DoubleArray(5)
 
    val x1 = doubleArrayOf(15.0, 6.0, 42.0, 41.0, 7.0, 36.0, 49.0, 40.0, 39.0, 47.0, 43.0)
    if (fivenum(x1, result, 11) == 0) show(result, 1)
 
    val x2 = doubleArrayOf(36.0, 40.0, 7.0, 39.0, 41.0, 15.0)
    if (fivenum(x2, result, 6) == 0) show(result, 1)
 
    val x3 = doubleArrayOf(
        0.14082834, 0.09748790, 1.73131507, 0.87636009, -1.95059594, 0.73438555,
        -0.03035726, 1.46675970, -0.74621349, -0.72588772, 0.63905160, 0.61501527,
        -0.98983780, -1.00447874, -0.62759469, 0.66206163, 1.04312009, -0.10305385,
        0.75775634, 0.32566578
    )
    if (fivenum(x3, result, 20) == 0) show(result, 9)
}

import java.util.ArrayList
import java.util.Collections
import java.util.Comparator
import java.util.HashSet
import java.util.TreeSet
import kotlin.math.sqrt
 
fun main(args: Array<String>) {
    val primes = ArrayList<Int>()
    val strongPrimes = TreeSet<Int>()
    val weakPrimes = TreeSet<Int>()
    var i = 2
    while (i < 1000000) {
        if (isPrime(i)) {
            primes.add(i)
            if (primes.size > 2) {
                val a = primes[primes.size - 3]
                val b = primes[primes.size - 2]
                val c = primes[primes.size - 1]
                if (b > a + c - b) {
                    strongPrimes.add(b)
                } else if (b < a + c - b) {
                    weakPrimes.add(b)
                }
            }
        }
        i++
    }
    println("First 36 strong primes:")
    println(strongPrimes.take(36))
    println("First 37 weak primes:")
    println(weakPrimes.take(37))
    println("1000000 strong primes: " + strongPrimes.size)
    println("1000000 weak primes: " + weakPrimes.size)
}
 
fun isPrime(n: Int): Boolean {
    if (n == 2) {
        return true
    }
    if (n % 2 == 0) {
        return false
    }
    val limit = sqrt(n.toDouble()).toInt()
    var i = 3
    while (i <= limit) {
        if (n % i == 0) {
            return false
        }
        i += 2
    }
    return true
}

