fun degToRad(a: Int): Double {
    return Math.PI / 180 * a
}

fun meanAngleDeg(a: List<Int>): Double {
    return 180 / Math.PI * Math.atan2(
        sum(a.map { degToRad(it) }.map { Math.sin(it) }) / a.size,
        sum(a.map { degToRad(it) }.map { Math.cos(it) }) / a.size
    )
}

