    fun customSort() {
        val items = arrayOf("Here", "are", "some", "sample", "strings", "to", "be", "sorted")
        val list = ArrayList(items.asList())
 
        displayList("Unsorted", list)
 
        list.sortWith(Comparator { x, y ->
            var result = -x.length.compareTo(y.length)
            if (result == 0) {
                result = x.toLowerCase().compareTo(y.toLowerCase())
            }
 
            result
        })
        displayList("Descending Length", list)
 
        list.sort()
        displayList("Ascending order", list)
    }
 
    // Output routine
    fun displayList(header: String, theList: List<String>) {
        println(header)
        println("".padStart(header.length, '*'))
        for (str in theList) {
            println(str)
        }
        println()
    }
}
 
