import kotlin.math.*
 
fun main() {
    val sw = System.Diagnostics.Stopwatch.StartNew()
    val fmt = "%9d twin primes below %13d"
    TabulateTwinPrimes(1_000_000_000)
    sw.Stop()
    var p = 1
    for (j in 1..ri) {
        println(fmt.format(res[j], p))
        p *= 10
    }
    println("${sw.Elapsed.TotalSeconds} sec")
}
 
var res = IntArray(10)
var ri = 1
var p = 10
var count = 0
 
fun TabulateTwinPrimes(bound: Int) {
    if (bound < 5) return
    count++
    val cl = (bound - 1) shr 1
    var i = 1
    var j: Int
    val limit = (sqrt(bound.toDouble()) - 1).toInt() shr 1
    val comp = BooleanArray(cl)
    for (j in 3 until cl step 3) comp[j] = true
    while (i < limit) {
        if (!comp[i]) {
            val pr = (i shl 1) + 3
            for (j in (pr * pr - 2) shr 1 until cl step pr)
                comp[j] = true
        }
        if (!comp[++i]) {
            val pr = (i shl 1) + 3
            if (!comp[i]) {
                if (pr > p) {
                    res[ri++] = count
                    p *= 10
                }
                count++
                i++
            }
            for (j in (pr * pr - 2) shr 1 until cl step pr)
                comp[j] = true
        }
    }
    cl--
    while (i < cl) {
        if (!comp[i++]) {
            if (!comp[i] &&!comp[--i]) {
                if ((i++ shl 1) + 3 > p) {
                    res[ri++] = count
                    p *= 10
                }
                count++
            }
        }
    }
    res[ri] = count
}

