import java.util.ArrayList
import java.util.Collections
 
fun deranged(depth: Int, len: Int, d: IntArray, show: Boolean): Long {
    var count = 0L
    if (depth == len) {
        if (show) {
            for (i in 0 until len) {
                print(d[i] + 'a'.toInt())
            }
            println()
        }
        return 1
    }
    for (i in len - 1 downTo depth) {
        if (i == d[depth]) {
            continue
        }
        val tmp = d[i]
        d[i] = d[depth]
        d[depth] = tmp
        count += deranged(depth + 1, len, d, show)
        val tmp2 = d[i]
        d[i] = d[depth]
        d[depth] = tmp2
    }
    return count
}
 
fun gen_n(n: Int, show: Boolean): Long {
    var i = 0
    val a = IntArray(1024)
    while (i < n) {
        a[i] = i
        i++
    }
    return deranged(0, n, a, show)
}
 
fun sub_fact(n: Int): Long {
    return if (n < 2) {
        1 - n
    } else (sub_fact(n - 1) + sub_fact(n - 2)) * (n - 1)
}
 
fun main() {
    println("Deranged Four:")
    gen_n(4, true)
    println("\nCompare list vs calc:")
    for (i in 0..9) {
        println(i.toString() + ":\t" + gen_n(i, false) + "\t" + sub_fact(i))
    }
    println("\nfurther calc:")
    for (i in 10..20) {
        println(i.toString() + ":\t" + sub_fact(i))
    }
}

fun halve(i: Int): Int {
