}
 
fun isEven(i: Int): Boolean {
    return i % 2 == 0
}
 
fun ethMulti(i: Int, j: Int): Int {
    var r = 0
    for (i in halve(i) downTo 0) {
        if (!isEven(i)) {
            r += j
        }
        j = double(j)
    }
    return r
}
 
