fun fft(vec: List<Complex>): List<Complex> {
    if (vec.size <= 1) return vec
    val evensOdds = vec.partition { it.index % 2 == 0 }
    val evens = fft(evensOdds.first)
    val odds = fft(evensOdds.second)
    return evens.zip(odds).mapIndexed { i, (even, odd) ->
        even + odd * Complex(0.0, -2.0 * Math.PI * i / vec.size)
    }
}
 
