fun main(args: Array<String>) {
    val err = removeLines("foobar.txt", 1, 2)
    if (err!= null) {
        println(err)
    }
}
 
fun removeLines(fn: String, start: Int, n: Int): String? {
    if (start < 1) {
        return "invalid request.  line numbers start at 1."
    }
    if (n < 0) {
        return "invalid request.  negative number to remove."
    }
    var f: RandomAccessFile? = null
    try {
        f = RandomAccessFile(File(fn), "rw")
        val b = f.channel.map(RandomAccessFile.MapMode.READ_WRITE, 0, f.length())
        val cut = skip(b, start - 1)
        if (!cut.ok) {
            return String.format("less than %d lines", start)
        }
        if (n == 0) {
            return null
        }
        val tail = skip(cut.b, n)
        if (!tail.ok) {
            return String.format("less than %d lines after line %d", n, start)
        }
        f.setLength(b.limit() - cut.b.limit())
        if (tail.b.limit() > 0) {
            f.channel.write(tail.b)
        }
    } catch (e: IOException) {
        return e.message
    } finally {
        if (f!= null) {
            try {
                f.close()
            } catch (e: IOException) {
                return e.message
            }
        }
    }
    return null
}
 
fun skip(b: ByteBuffer, n: Int): Pair<ByteBuffer, Boolean> {
    var n = n
    while (n > 0) {
        if (b.limit() == 0) {
            return Pair(b, false)
        }
        val x = b.indexOf(10)
        if (x < 0) {
            x = b.limit()
        } else {
            x++
        }
        b.position(x)
        n--
    }
    return Pair(b, true)
}
 
fun ByteBuffer.indexOf(b: Int): Int {
    val p = Pattern.compile(String.format("[\\s\\S]*?%c", b.toChar()))
    val m = p.matcher(Charset.defaultCharset().decode(this))
    if (m.find()) {
        return m.start()
    }
    return -1
}

var op_priority = mapOf("+" to 0, "-" to 0, "*" to 1, "/" to 1)

class TreeNode(var info: String, var left: TreeNode? = null, var right: TreeNode? = null) {
    fun leaf(): Boolean {
        return left == null && right == null
    }

    fun to_s(order: String): String {
        if (leaf()) {
            return info
        } else {
            val left_s = left?.to_s(order)
            val right_s = right?.to_s(order)

            val strs = when (order) {
                "prefix" -> listOf(info, left_s, right_s)
                "infix" -> listOf(left_s, info, right_s)
                "postfix" -> listOf(left_s, right_s, info)
                else -> listOf()
            }

            return "(" + strs.joinToString(" ") + ")"
        }
    }

    fun eval(): Float {
        if (!leaf() && operator(info)) {
            return OP_FUNCTION[info]!!.invoke(left!!.eval(), right!!.eval())
        } else {
            return info.toFloat()
        }
    }
}

val OP_FUNCTION = mapOf(
    "+" to { x: Float, y: Float -> x + y },
    "-" to { x: Float, y: Float -> x - y },
    "*" to { x: Float, y: Float -> x * y },
    "/" to { x: Float, y: Float -> x / y }
)

fun tokenize(exp: String): List<String> {
    return exp
       .replace("(", " ( ")
       .replace(")", " ) ")
       .replace("+", " + ")
       .replace("-", " - ")
       .replace("*", " * ")
       .replace("/", " / ")
       .split(" ")
}

fun operator(token: String): Boolean {
    return op_priority.containsKey(token)
}

fun pop_connect_push(op_stack: MutableList<TreeNode>, node_stack: MutableList<TreeNode>) {
    val temp = op_stack.removeAt(op_stack.size - 1)
    temp.right = node_stack.removeAt(node_stack.size - 1)
    temp.left = node_stack.removeAt(node_stack.size - 1)
    node_stack.add(temp)
}

fun infix_exp_to_tree(exp: String): TreeNode {
    val tokens = tokenize(exp)
    val op_stack = mutableListOf<TreeNode>()
    val node_stack = mutableListOf<TreeNode>()

    for (token in tokens) {
        if (operator(token)) {
            // clear stack of higher priority operators
            while (!op_stack.isEmpty() &&
                op_stack.last().info!= "(" &&
                op_priority[op_stack.last().info]!! < op_priority[token]!!
            ) {
                pop_connect_push(op_stack, node_stack)
            }

            op_stack.add(TreeNode(token))
        } else if (token == "(") {
            op_stack.add(TreeNode(token))
        } else if (token == ")") {
            while (op_stack.last().info!= "(") {
                pop_connect_push(op_stack, node_stack)
            }

            // throw away the '('
            op_stack.removeAt(op_stack.size - 1)
        } else {
            node_stack.add(TreeNode(token))
        }
    }

    while (!op_stack.isEmpty()) {
        pop_connect_push(op_stack, node_stack)
    }

    return node_stack.last()
}

