import java.awt.image.BufferedImage
import java.io.File
import javax.imageio.ImageIO
import kotlin.math.abs
import kotlin.math.roundToInt
import kotlin.math.sin
import kotlin.math.sqrt
 
// Framebuffer dimensions
const val WIDTH = 640
const val HEIGHT = 480
 
/**
 * Formula for plasma at any particular address
 */
fun plasmaPixel(x: Double, y: Double): Double {
    return ((x / 16.0).sin()
            + (y / 8.0).sin()
            + ((x + y) / 16.0).sin()
            + ((x * x + y * y).sqrt() / 8.0).sin()
            + 4.0)
            / 8.0
}
 
/**
 * Precalculate plasma field lookup-table for performance
 */
fun createPlasmaLut(): Array<DoubleArray> {
    val plasma = Array(HEIGHT) { DoubleArray(WIDTH) }
    for (y in 0 until HEIGHT) {
        for (x in 0 until WIDTH) {
            plasma[y][x] = plasmaPixel(x.toDouble(), y.toDouble())
        }
    }
    return plasma
}
 
/**
 * Convert from HSV float(1.0,1.0,1.0) to RGB u8 tuple (255,255,255).
 * From https://crates.io/crates/palette 0.5.0 rgb.rs, simplified for example
 */
fun hsvToRgb(hue: Double, saturation: Double, value: Double): Triple<Int, Int, Int> {
    val c = value * saturation
    val h = hue * 6.0
    val x = c * (1.0 - (h % 2.0 - 1.0).abs())
    val m = value - c
    val (red, green, blue) = when ((h % 6.0).toInt()) {
        0 -> Triple(c, x, 0.0)
        1 -> Triple(x, c, 0.0)
        2 -> Triple(0.0, c, x)
        3 -> Triple(0.0, x, c)
        4 -> Triple(x, 0.0, c)
        else -> Triple(c, 0.0, x)
    }
    // Convert back to RGB (where components are integers from 0 to 255)
    return Triple(
            ((red + m) * 255.0).roundToInt(),
            ((green + m) * 255.0).roundToInt(),
            ((blue + m) * 255.0).roundToInt()
    )
}
 
fun main() {
    // The bitmap/framebuffer for our application. 3 u8 elements per output pixel
    val framebuffer = Array(HEIGHT) { IntArray(WIDTH) }
    // Generate a lookup table so we don't do too much math for every pixel.
    // Do it in a function so that the local one can be immutable.
    val plasmaLookupTable = createPlasmaLut()
    // For each (r,g,b) pixel in our output buffer
    for (y in 0 until HEIGHT) {
        for (x in 0 until WIDTH) {
            // Lookup the precalculated plasma value
            val hueLookup = plasmaLookupTable[y][x] % 1.0
            val (red, green, blue) = hsvToRgb(hueLookup, 1.0, 1.0)
            framebuffer[y][x] = (red shl 16) or (green shl 8) or blue
        }
    }
    // Save our plasma image to out.png
    val outputPath = File("out.png")
    val image = BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_RGB)
    for (y in 0 until HEIGHT) {
        for (x in 0 until WIDTH) {
            image.setRGB(x, y, framebuffer[y][x])
        }
    }
    ImageIO.write(image, "png", outputPath)
    println("Output written to:\n${outputPath.absolutePath}")
}

