import java.io.FileDescriptor
import java.io.FileOutputStream
import java.io.IOException
import java.nio.file.Files
import java.nio.file.Paths
import kotlin.system.exitProcess
 
fun main(args: Array<String>) {
	val ws = getWinSize()
	println("${ws.ws_row} rows by ${ws.ws_col} columns")
	println("(${ws.ws_xpixel} by ${ws.ws_ypixel} pixels)")
}
 
fun getWinSize(): winsize {
	val fd = open("/dev/tty", O_RDWR)
	if (fd < 0) {
		err(1, "/dev/tty")
	}
	val ws = winsize()
	if (ioctl(fd, TIOCGWINSZ, ws) < 0) {
		err(1, "/dev/tty")
	}
	close(fd)
	return ws
}
 
fun err(code: Int, msg: String) {
	println(msg)
	exitProcess(code)
}
 
fun open(path: String, flags: Int): Int {
	val fd = FileDescriptor()
	try {
		fd.fd = Files.newByteChannel(Paths.get(path)).use { it.open(flags) }
	} catch (e: IOException) {
		return -1
	}
	return fd.fd
}
 
fun close(fd: Int) {
	try {
		FileOutputStream(fd).close()
	} catch (e: IOException) {
	}
}
 
fun ioctl(fd: Int, request: Int, ws: winsize): Int {
	return try {
		FileOutputStream(fd).channel.use { it.ioctl(request, ws) }
	} catch (e: IOException) {
		-1
	}
}
 
class winsize {
	var ws_row: Int = 0
	var ws_col: Int = 0
	var ws_xpixel: Int = 0
	var ws_ypixel: Int = 0
}
 
const val O_RDWR = 0x0002
const val TIOCGWINSZ = 0x5413

import java.util.*
 
class Entry_ {
	var expr_: String = ""
	var op_: String = ""
}
 
fun PrecedenceLess(lhs: String, rhs: String, assoc: Boolean): Boolean {
	val KNOWN = mapOf("+" to 1, "-" to 1, "*" to 2, "/" to 2, "^" to 3)
	val ASSOCIATIVE = setOf("+", "*")
	return (KNOWN[lhs]?: 0) < (KNOWN[rhs]?: 0) + (if (assoc &&!ASSOCIATIVE.contains(rhs)) 1 else 0)
}
 
fun Parenthesize(old: Entry_, token: String, assoc: Boolean) {
	if (old.op_.isNotEmpty() && PrecedenceLess(old.op_, token, assoc))
		old.expr_ = '(' + old.expr_ + ')'
}
 
fun AddToken(stack: Stack<Entry_>, token: String) {
	if (token.indexOfFirst { it in '0'..'9' }!= -1)
		stack.push(Entry_().apply { expr_ = token }) // it's a number, no operator
	else { // it's an operator
		if (stack.size < 2)
			println("Stack underflow")
		val rhs = stack.pop()
		Parenthesize(rhs, token, false)
		val lhs = stack.pop()
		Parenthesize(lhs, token, true)
		stack.peek().apply { expr_ = lhs.expr_ +'' + token +'' + rhs.expr_ }
		stack.peek().op_ = token
	}
}
 
fun ToInfix(src: String): String {
	val stack = Stack<Entry_>()
	for (start in src.indices) {
		val p = src.indexOf(' ', start)
		if (p == -1) {
			AddToken(stack, src.substring(start))
			break
		}
		AddToken(stack, src.substring(start, p))
		start = p + 1
	}
	if (stack.size!= 1)
		println("Incomplete expression")
	return stack.peek().expr_
}
 
fun main(args: Array<String>) {
	try {
		println(ToInfix("3 4 2 * 1 5 - 2 3 ^ ^ / +"))
		println(ToInfix("1 2 + 3 4 + ^ 5 6 + ^"))
	} catch (e: Exception) {
		println("Failed")
	}
}

import java.io.ByteArrayOutputStream
import java.io.IOException
import java.security.MessageDigest
import java.security.NoSuchAlgorithmException
import java.security.SecureRandom
import java.sql.Connection
import java.sql.DriverManager
import java.sql.PreparedStatement
