class User(val username: String, val passSalt: ByteArray, val passMd5: ByteArray)
 
fun connectDB(): Connection {
    Class.forName("com.mysql.jdbc.Driver")
    return DriverManager.getConnection("jdbc:mysql://localhost/rc", "rosetta", "code")
}
 
fun createUser(db: Connection, user: String, pwd: String): Boolean {
    val salt = ByteArray(16)
    SecureRandom().nextBytes(salt)
    val stmt = db.prepareStatement("insert into users (username, pass_salt, pass_md5) values (?, ?, ?)")
    stmt.setString(1, user)
    stmt.setBytes(2, salt)
    stmt.setBytes(3, saltHash(salt, pwd))
    return stmt.executeUpdate() == 1
}
 
fun authenticateUser(db: Connection, user: String, pwd: String): Boolean {
    val stmt = db.prepareStatement("select pass_salt, pass_md5 from users where username=?")
    stmt.setString(1, user)
    val rs = stmt.executeQuery()
    if (!rs.next()) {
        return false
    }
    val salt = rs.getBytes(1)
    val hash = rs.getBytes(2)
    return Arrays.equals(saltHash(salt, pwd), hash)
}
 
fun saltHash(salt: ByteArray, pwd: String): ByteArray {
    val md = MessageDigest.getInstance("MD5")
    md.update(salt)
    md.update(pwd.toByteArray())
    return md.digest()
}
 
fun main(args: Array<String>) {
    // demonstrate
    val db = connectDB()
    createUser(db, "sam", "123")
    if (authenticateUser(db, "sam", "123")) {
        println("User sam authenticated")
    }
 
    // extra
    println()
    // show contents of database
    val stmt = db.prepareStatement("select username, pass_salt, pass_md5 from users")
    val rs = stmt.executeQuery()
    while (rs.next()) {
        val user = rs.getString(1)
        val salt = rs.getBytes(2)
        val hash = rs.getBytes(3)
        println("$user ${bytesToHex(salt)} ${bytesToHex(hash)}")
    }
    // try creating same user again
    if (!createUser(db, "sam", "123")) {
        println("User sam already exists")
    }
    // try authenticating unknown user
    if (!authenticateUser(db, "pam", "123")) {
        println("User pam unknown")
    }
    // try wrong password
    if (!authenticateUser(db, "sam", "1234")) {
        println("User sam invalid password")
    }
    // clear table to run program again
    db.prepareStatement("truncate table users").executeUpdate()
}
 
fun bytesToHex(bytes: ByteArray): String {
    val buf = ByteArrayOutputStream()
    for (b in bytes) {
        buf.write(Character.forDigit(b.toInt() shr 4 and 0xF, 16).toInt())
        buf.write(Character.forDigit(b.toInt() and 0xF, 16).toInt())
    }
    return buf.toString()
}

fun main(args: Array<String>) {
    val n = doubleArrayOf(-42.0, 0.0, -12.0, 1.0)
    val d = doubleArrayOf(-3.0, 1.0)
    println("N: " + Arrays.toString(n))
    println("D: " + Arrays.toString(d))
    val (q, r, ok) = pld(n, d)
    if (ok) {
        println("Q: " + Arrays.toString(q))
        println("R: " + Arrays.toString(r))
    } else {
        println("error")
    }
}
 
fun degree(p: DoubleArray): Int {
    for (d in p.size - 1 downTo 0) {
        if (p[d]!= 0.0) {
            return d
        }
    }
    return -1
}
 
fun pld(nn: DoubleArray, dd: DoubleArray): Triple<DoubleArray, DoubleArray, Boolean> {
    if (degree(dd) < 0) {
        return Triple(doubleArrayOf(), doubleArrayOf(), false)
    }
    val r = doubleArrayOf()
    val n = DoubleArray(r.size + nn.size)
    System.arraycopy(r, 0, n, 0, r.size)
    System.arraycopy(nn, 0, n, r.size, nn.size)
    if (degree(n) >= degree(dd)) {
        val q = DoubleArray(degree(n) - degree(dd) + 1)
        while (degree(n) >= degree(dd)) {
            val d = DoubleArray(degree(n) + 1)
            System.arraycopy(dd, degree(n) - degree(dd), d, 0, dd.size)
            q[degree(n) - degree(dd)] = n[degree(n)] / d[degree(d)]
            for (i in d.indices) {
                d[i] *= q[degree(n) - degree(dd)]
                n[i] -= d[i]
            }
        }
        return Triple(q, n, true)
    }
    return Triple(doubleArrayOf(), doubleArrayOf(), false)
}

