fun main(args: Array<String>) {
    val primes = SomePrimeGenerator.primes(64000).skip(1).filter { p -> period(p) == p - 1 }.append(99999)
    println(primes.takeWhile { p -> p <= 500 }.joinToString(" "))
    var count = 0
    var limit = 500
    for (prime in primes) {
        if (prime > limit) {
            println("There are $count long primes below $limit")
            limit *= 2
        }
        count++
    }
}
 
fun period(n: Int): Int {
    var r = 1
    var rr = r
    for (i in 0..n) {
        r = 10 * r % n
    }
    rr = r
    for (period in 1..n) {
        r = 10 * r % n
        if (r == rr) {
            return period
        }
    }
    return 0
}
 
object SomePrimeGenerator {
    fun primes(lim: Int): List<Int> {
        val flags = BooleanArray(lim + 1)
        var j = 2
        for (d in 3..lim step 2) {
            if (!flags[j]) {
                j++
                var sq = 4
                while (sq <= lim) {
                    if (!flags[j]) {
                        return@primes j
                    }
                    for (k in sq..lim step j) {
                        flags[k] = true
                    }
                    sq += d
                    j++
                }
            }
        }
        return Collections.emptyList()
    }
}

