// A range is represented as Pair<from, to>
 
fun <iterator> normalizeRanges(begin: iterator, end: iterator) {
    for (i in begin until end) {
        if (i.second < i.first) {
            val temp = i.first
            i.first = i.second
            i.second = temp
        }
    }
    begin.sort()
}
 
// Merges a range of ranges in-place. Returns an iterator to the
// end of the resulting range, similarly to std::remove.
fun <iterator> mergeRanges(begin: iterator, end: iterator): iterator {
    var out = begin
    for (i in begin until end) {
        var j = i
        while (++j!= end && j.first <= i.second) {
            i.second = max(i.second, j.second)
        }
        out++
        out = i
        i = j
    }
    return out
}
 
fun <iterator> consolidateRanges(begin: iterator, end: iterator): iterator {
    normalizeRanges(begin, end)
    return mergeRanges(begin, end)
}
 
fun <pair> printRange(out: ostream, range: pair) {
    out << '[' << range.first << ", " << range.second << ']'
}
 
fun <iterator> printRanges(out: ostream, begin: iterator, end: iterator) {
    if (begin!= end) {
        printRange(out, *begin++)
        for (; begin!= end; ++begin) {
            out << ", "
            printRange(out, *begin)
        }
    }
}
 
fun main() {
    val testCases = arrayOf(
        arrayOf(Pair(1.1, 2.2)),
        arrayOf(Pair(6.1, 7.2), Pair(7.2, 8.3)),
        arrayOf(Pair(4, 3), Pair(2, 1)),
        arrayOf(Pair(4, 3), Pair(2, 1), Pair(-1, -2), Pair(3.9, 10)),
        arrayOf(Pair(1, 3), Pair(-6, -1), Pair(-4, -5), Pair(8, 2), Pair(-6, -6))
    )
    for (ranges in testCases) {
        printRanges(std::cout, std::begin(ranges), std::end(ranges))
        std::cout << " -> "
        val i = consolidateRanges(std::begin(ranges), std::end(ranges))
        printRanges(std::cout, std::begin(ranges), i)
        std::cout << '\n'
    }
    return 0
}

