fun filter(img: Image, K: DoubleArray, Ks: Int, b: Double, c: Double): Image {
    val w = img.width
    val h = img.height
    val d = img.depth
    val out = Image(w, h, d)
    for (k in 0 until d) {
        for (i in 0 until w) {
            for (j in 0 until h) {
                var acc = 0.0
                for (l in 0 until Ks) {
                    for (m in 0 until Ks) {
                        val x = i + l - Ks / 2
                        val y = j + m - Ks / 2
                        if (x >= 0 && x < w && y >= 0 && y < h) {
                            acc += img.get(x, y, k) * K[l * Ks + m]
                        }
                    }
                }
                out.set(i, j, k, b * acc + c)
            }
        }
    }
    return out
}

fun escapeRegex(string: String): String {
    return string.replace(Regex("[-/\\\\^$*+?.()|[\\]{}]"), "\\$&")
