class Swapper(private val i: Int, private val j: Int) {
    private val lock1 = Any()
    private val lock2 = Any()

    fun swap() {
        synchronized(lock1) {
            synchronized(lock2) {
                val temp = i
                i = j
                j = temp
            }
        }
    }
}

import kotlin.random.Random
 
class Node<T : Comparable<T>>(var value: T, var left: Node<T>? = null, var right: Node<T>? = null)
 
fun <T : Comparable<T>> insert(root: Node<T>?, v: T): Node<T>? {
    if (root == null) return Node(v)
    if (v < root.value) {
        root.left = insert(root.left, v)
    } else {
        root.right = insert(root.right, v)
    }
    return root
}
 
fun <T : Comparable<T>> new(v: T): Node<T> = Node(v)
 
