class ListNode(val value: Any, var succ: ListNode? = null) {
    fun insertAfter(searchValue: Any, newValue: Any) {
        if (searchValue == value) {
            succ = ListNode(newValue, succ)
        } else if (succ == null) {
            throw Exception("value $searchValue not found in list")
        } else {
            succ!!.insertAfter(searchValue, newValue)
        }
    }
}
 
