import java.util.*
 
enum class GameState {
    PlayerWin,
    ComputerWin,
    Draw,
    Playing
}
 
typealias Board = Array<Array<Char>>
 
fun main(args: Array<String>) {
    val rng = Random()
 
    var board: Board = arrayOf(arrayOf('1', '2', '3'), arrayOf('4', '5', '6'), arrayOf('7', '8', '9'))
 
    drawBoard(board)
    while (true) {
        playerTurn(board)
        if (checkWin(board)!= GameState.Playing) {
            break
        }
        computerTurn(rng, board)
        if (checkWin(board)!= GameState.Playing) {
            break
        }
        drawBoard(board)
    }
 
    drawBoard(board)
    val announcement = when (checkWin(board)) {
        GameState.PlayerWin -> "The Player has won!"
        GameState.ComputerWin -> "The Computer has won!"
        GameState.Draw -> "Draw!"
        GameState.Playing -> throw IllegalStateException()
    }
    println(announcement)
}
 
fun isEmpty(cell: Char): Boolean {
    return cell!= 'X' && cell!= 'O'
}
 
fun checkWin(board: Board): GameState {
    // check for win
    for (i in 0..2) {
        if (board[i][0] == board[i][1] && board[i][0] == board[i][2]) {
            return whichWin(board[i][0])
        } else if (board[0][i] == board[1][i] && board[0][i] == board[2][i]) {
            return whichWin(board[0][i])
        }
    }
    if (board[0][0] == board[1][1] && board[0][0] == board[2][2]) {
        return whichWin(board[0][0])
    } else if (board[0][2] == board[1][1] && board[0][2] == board[2][0]) {
        return whichWin(board[0][2])
    }
 
    // check if it's not a draw
    val isDraw = board.any { row -> row.any { isEmpty(it) } }
    return if (isDraw) {
        GameState.Playing
    } else {
        GameState.Draw
    }
}
 
fun whichWin(s: Char): GameState {
    return when (s) {
        'X' -> GameState.PlayerWin
        'O' -> GameState.ComputerWin
        else -> throw IllegalStateException()
    }
}
 
fun playerTurn(board: Board) {
    println("Player, enter your field of choice!: ")
    val choice = readLine()!!.toInt()
    val row = (choice - 1) / 3
    val col = (choice - 1) % 3
 
    if (board[row][col] == 'X' || board[row][col] == 'O') {
        println("Someone already took this field!")
        playerTurn(board)
    } else {
        board[row][col] = 'X'
    }
}
 
fun computerTurn(rng: Random, board: Board) {
    val possibleChoices = board
       .flatMapIndexed { i, row -> row.mapIndexed { j, c -> i * 3 + j to c } }
       .filter { (_, c) -> isEmpty(c) }
       .map { (i, _) -> i }
 
    val choice = possibleChoices[rng.nextInt(possibleChoices.size)]
    println("Computer chose: $choice")
    val row = choice / 3
    val col = choice % 3
    board[row][col] = 'O'
}
 
fun drawBoard(board: Board) {
    for (row in board) {
        println("${row[0]} ${row[1]} ${row[2]}")
    }
}

