fun common_len(names: List<String>, n: Int, sep: Char): Int {
    var pos: Int
    for (pos_0: Int in 0..2147483647) {
        pos = pos_0
        var i: Int
        for (i_0: Int in 0..n - 1) {
            i = i_0
            if (names[i][pos]!= '\u0000'.toInt() && names[i][pos] == names[0][pos]) {
                continue
            }
            while (pos > 0 && names[0][--pos]!= sep) {
            }
            return pos
        }
    }
    return 0
}

