    }
}

import java.util.*
 
fun isHumble(i: Int): Boolean {
    if (i <= 1) return true
    if (i % 2 == 0) return isHumble(i / 2)
    if (i % 3 == 0) return isHumble(i / 3)
    if (i % 5 == 0) return isHumble(i / 5)
    if (i % 7 == 0) return isHumble(i / 7)
    return false
}
 
fun main(args: Array<String>) {
    val limit = Short.MAX_VALUE
    val humble = HashMap<Int, Int>()
    var count = 0
    var num = 1
 
    while (count < limit) {
        if (isHumble(num)) {
            val str = num.toString()
            val len = str.length
            if (humble.containsKey(len)) {
                humble[len] = humble[len]!! + 1
            } else {
                humble[len] = 1
            }
            if (count < 50) print("$num ")
            count++
        }
        num++
    }
    println("\n")
 
    println("Of the first $count humble numbers:")
    num = 1
    while (num < humble.size - 1) {
        if (humble.containsKey(num)) {
            val c = humble[num]
            println("%5d have %2d digits".format(c, num))
            num++
        } else {
            break
        }
    }
}

/*
 * Arithmetic-Geometric Mean of 1 & 1/sqrt(2)
 * 
 * 5/29/12
 */
fun agm(a: Double, g: Double): Double {
    var a1 = a
    var g1 = g
    while (Math.abs(a1 - g1) >= 1.0e-14) {
        val arith = (a1 + g1) / 2.0
        val geom = Math.sqrt(a1 * g1)
        a1 = arith
        g1 = geom
    }
    return a1
}
 
fun main(args: Array<String>) {
    println(agm(1.0, 1.0 / Math.sqrt(2.0)))
}

class Roman {
	companion object {
		private fun decodeSingle(letter: Char): Int {
			return when (letter) {
				'M' -> 1000
				'D' -> 500
				'C' -> 100
				'L' -> 50
				'X' -> 10
				'V' -> 5
				'I' -> 1
				else -> 0
			}
		}
		fun decode(roman: String): Int {
			var result = 0
			val uRoman = roman.toUpperCase() //case-insensitive
			for (i in 0 until uRoman.length - 1) { //loop over all but the last character
				//if this character has a lower value than the next character
				if (decodeSingle(uRoman[i]) < decodeSingle(uRoman[i + 1])) {
					//subtract it
					result -= decodeSingle(uRoman[i])
				} else {
					//add it
					result += decodeSingle(uRoman[i])
				}
			}
			//decode the last character, which is always added
			result += decodeSingle(uRoman[uRoman.length - 1])
			return result
		}
	}
}
fun main(args: Array<String>) {
	println(Roman.decode("MCMXC")) //1990
	println(Roman.decode("MMVIII")) //2008
	println(Roman.decode("MDCLXVI")) //1666
}

