import java.util.Map
 
fun main(args: Array<String>) {
    println(String.format("Entropy of file \"%s\" = %.12f.", "src/EntropyNarcissist.java", getEntropy("src/EntropyNarcissist.java")))
}
 
fun getEntropy(fileName: String): Double {
    val characterCount = HashMap<Char, Int>()
    var length = 0
 
    try {
        val reader = BufferedReader(FileReader(File(fileName)))
        var c = 0
        while ( { c = reader.read(); c }()!= -1) {
            characterCount.merge(c.toChar(), 1, { v1, v2 -> v1 + v2 })
            length++
        }
    } catch (e: IOException) {
        throw RuntimeException(e)
    }
 
    var entropy = 0.0
    for (key in characterCount.keys) {
        val fraction = characterCount[key]!!.toDouble() / length
        entropy -= fraction * Math.log(fraction)
    }
 
    return entropy / Math.log(2)
}

