fun <T : Number> Iterable<T>.arithmeticMean(): Double {
    return this.sumByDouble { it.toDouble() } / this.count()
}
 
fun <T : Number> Iterable<T>.geometricMean(): Double {
    return this.map { it.toDouble() }.reduce { acc, d -> acc * d }.pow(1.0 / this.count())
}
 
fun <T : Number> Iterable<T>.harmonicMean(): Double {
    return this.count() / this.map { 1.0 / it.toDouble() }.sum()
}
 
fun <T : Number> ClosedRange<T>.arithmeticMean(): Double {
    return this.toList().arithmeticMean()
}
 
fun <T : Number> ClosedRange<T>.geometricMean(): Double {
    return this.toList().geometricMean()
}
 
fun <T : Number> ClosedRange<T>.harmonicMean(): Double {
    return this.toList().harmonicMean()
}
 
fun main(args: Array<String>) {
    val a = (1..10).arithmeticMean()
    val g = (1..10).geometricMean()
    val h = (1..10).harmonicMean()
    println("a = $a")
    println("g = $g")
    println("h = $h")
    println("g.between(h, a) = ${g.between(h, a)}")
}

