fun powerset(ary: Array<Int>): List<List<Int>> {
    var ps = listOf(listOf<Int>())
    for (i in 0..ary.size - 1) {
        for (j in 0..ps.size - 1) {
            ps = ps + ps[j] + ary[i]
        }
    }
    return ps
}
 
