var cache = mutableMapOf<Int, List<Int>>()
fun selfReferentialSequence_cached(n: Int, seen: List<Int> = listOf()): List<Int> {
    if (cache.containsKey(n)) {
        return cache[n]!!
    }
    if (seen.contains(n)) {
        return listOf()
    }
    val digitCount = IntArray(10)
    n.toString().forEach {
        digitCount[it.toString().toInt()]++
    }
    var term = ""
    for (d in 9 downTo 0) {
        if (digitCount[d] > 0) {
            term += digitCount[d].toString() + d.toString()
        }
    }
    term = term.toInt()
    cache[n] = listOf(n) + selfReferentialSequence_cached(term, listOf(n) + seen)
    return cache[n]!!
}
 
val limit = 1_000_000
var maxLen = 0
var maxVals = mutableListOf<Int>()
 
for (n in 1..limit - 1) {
    val seq = selfReferentialSequence_cached(n)
    if (seq.size > maxLen) {
        maxLen = seq.size
        maxVals = mutableListOf(n)
    } else if (seq.size == maxLen) {
        maxVals.add(n)
    }
}
 
println("values: ${maxVals.toString()}")
println("iterations: $maxLen")
println("sequence:")
selfReferentialSequence_cached(maxVals[0]).forEachIndexed { idx, val ->
    println("%2d %d".format(idx + 1, val))
}

data class BinaryTreeNode(val value: Int, val left: BinaryTreeNode?, val right: BinaryTreeNode?) {
    fun walkNodes(order: List<String>, block: (BinaryTreeNode) -> Unit) {
        order.forEach { node ->
            when (node) {
                "left" -> left?.walkNodes(order, block)
                "self" -> block(this)
                "right" -> right?.walkNodes(order, block)
            }
        }
    }

    fun eachPreorder(block: (BinaryTreeNode) -> Unit) = walkNodes(listOf("self", "left", "right"), block)
    fun eachInorder(block: (BinaryTreeNode) -> Unit) = walkNodes(listOf("left", "self", "right"), block)
    fun eachPostorder(block: (BinaryTreeNode) -> Unit) = walkNodes(listOf("left", "right", "self"), block)

    fun eachLevelorder(block: (BinaryTreeNode) -> Unit) {
        val queue = mutableListOf(this)
        while (queue.isNotEmpty()) {
            val node = queue.removeAt(0)
            block(node)
            node.left?.let { queue.add(it) }
            node.right?.let { queue.add(it) }
        }
    }
}

fun main(args: Array<String>) {
    val root = BinaryTreeNode(1,
            BinaryTreeNode(2,
                    BinaryTreeNode(4,
                            BinaryTreeNode(7, null, null),
                            BinaryTreeNode(5, null, null)),
                    null),
            BinaryTreeNode(3,
                    BinaryTreeNode(6,
                            BinaryTreeNode(8, null, null),
                            BinaryTreeNode(9, null, null)),
                    null))

    listOf("preorder", "inorder", "postorder", "levelorder").forEach { order ->
        print("${order}: ")
        root.javaClass.kotlin.members.find { it.name == "each${order.capitalize()}" }?.call(root) { node -> print("${node.value} ") }
        println()
    }
}

package main
 
import (
    "fmt"
    "math/big"
    "strconv"
)
 
fun main() {
    // package strconv:  the most common string to int conversion,
    // base 10 only.
    x, _ = strconv.Atoi("13")
    println(x)
 
    // ParseInt handles arbitrary bases from 2 to 36, and returns
    // a result of the requested size (64 bits shown here.)
    // If the base argument is zero the base is determined by prefix
    // as with math/big below.
    x64, _ = strconv.ParseInt("3c2", 19, 64)
    println(x64)
 
    // package fmt:  allows direct conversion from strings, standard
    // input, or from an io.Reader (file, buffer, etc) to integer types
    // for bases 2, 8, 10, and 16 or to any type that implements the
    // fmt.Scanner interface (e.g. a big.Int).
    // (Fscanf and Scanf are more common for reading from
    // an io.Reader or stdin than Sscanf for reading from strings.)
    fmt.Sscanf("1101", "%b", &x)
    println(x)
 
    fmt.Sscanf("15", "%o", &x)
    println(x)
 
    fmt.Sscanf("13", "%d", &x)
    println(x)
 
    fmt.Sscanf("d", "%x", &x)
    println(x)
 
    // package math/big:  allows conversion from string to big integer.
    // any base from 2 to 36 can be specified as second parameter.
    var z big.Int
    z.SetString("111", 3)
    println(&z)
 
    // if second parameter is 0, base is determined by prefix, if any
    z.SetString("0b1101", 0) // 0b -> base 2
    println(&z)
 
    z.SetString("015", 0) // 0 -> base 8
    println(&z)
 
    z.SetString("13", 0) // no prefix -> base 10
    println(&z)
 
    z.SetString("0xd", 0) // 0x -> base 16
    println(&z)
 
    // As mentioned, a big.Int (or any type implementing fmt.Scanner)
    // can also be use with any of the fmt scanning functions.
    fmt.Sscanf("15", "%o", &z)
    println(&z)
}

