fun main() {
    SwingUtilities.invokeLater {
        val clock = Clock()
        clock.isVisible = true
    }
}
 
class Clock : JFrame() {
    private val margin = 20
    private val degrees06 = Math.PI / 30
    private val degrees30 = degrees06 * 5
    private val degrees90 = degrees30 * 3
    private var p0 = Point(0, 0)
 
    init {
        defaultCloseOperation = EXIT_ON_CLOSE
        preferredSize = Dimension(500, 500)
        add(ClockPanel())
        addComponentListener(object : ComponentAdapter() {
            override fun componentResized(e: ComponentEvent) {
                resetSize()
            }
        })
        addWindowListener(object : WindowAdapter() {
            override fun windowOpened(e: WindowEvent) {
                resetSize()
            }
        })
    }
 
    private fun resetSize() {
        p0 = Point(width / 2, height / 2)
        repaint()
    }
 
    private inner class ClockPanel : JPanel() {
        override fun paintComponent(g: Graphics) {
            super.paintComponent(g)
            val g2d = g as Graphics2D
            g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON)
 
            drawFace(g2d)
 
            val time = Calendar.getInstance()
            val second = time.get(Calendar.SECOND)
            val minute = time.get(Calendar.MINUTE)
            val hour = time.get(Calendar.HOUR)
 
            var angle = degrees90 - (degrees06 * second)
            drawHand(g2d, Color.RED, angle, 0.95)
 
            val minsecs = minute + second / 60.0
            angle = degrees90 - (degrees06 * minsecs)
            drawHand(g2d, Color.BLACK, angle, 0.9)
 
            val hourmins = hour + minsecs / 60.0
            angle = degrees90 - (degrees30 * hourmins)
            drawHand(g2d, Color.BLACK, angle, 0.6)
        }
 
        private fun drawFace(g: Graphics2D) {
            val radius = min(p0.x, p0.y) - margin
            g.color = Color.WHITE
            g.fillOval(p0.x - radius, p0.y - radius, radius * 2, radius * 2)
 
            for (h in 0..11)
                drawHand(g, Color.LIGHT_GRAY, h * degrees30, -0.05)
 
            for (m in 0..59)
                drawHand(g, Color.LIGHT_GRAY, m * degrees06, -0.025)
        }
 
        private fun drawHand(g: Graphics2D, color: Color, angle: Double, size: Double) {
            val radius = min(p0.x, p0.y) - margin
 
            val x0 = p0.x + (if (size > 0) 0 else (radius * (1 + size) * cos(angle)).toInt())
            val y0 = p0.y + (if (size > 0) 0 else (radius * (1 + size) * sin(-angle)).toInt())
 
            val x1 = p0.x + (radius * (if (size > 0) size else 1) * cos(angle)).toInt()
            val y1 = p0.y + (radius * (if (size > 0) size else 1) * sin(-angle)).toInt()
 
            g.color = color
            g.drawLine(x0, y0, x1, y1)
        }
    }
}

