fun isPrime(n: Int): Boolean {
    return when {
        n < 2 -> false
        n % 2 == 0 -> n == 2
        n % 3 == 0 -> n == 3
        else -> {
            var d = 5
            while (d * d <= n) {
                if (n % d == 0) {
                    return false
                }
                d += 2
                if (n % d == 0) {
                    return false
                }
                d += 4
            }
            true
        }
    }
}
 
fun countPrimeFactors(n: Int): Int {
    return when {
        n == 1 -> 0
        isPrime(n) -> 1
        else -> {
            var count = 0
            var f = 2
            while (true) {
                if (n % f == 0) {
                    count++
                    n /= f
                    if (n == 1) {
                        return count
                    }
                    if (isPrime(n)) {
                        f = n
                    }
                } else if (f >= 3) {
                    f += 2
                } else {
                    f = 3
                }
            }
            count
        }
    }
}
 
fun main() {
