class Position(val x: Int, val y: Int) {
    override fun toString(): String {
        return "(%d, %d)".format(x, y)
    }
}
 
fun isAttacking(queen: Position, pos: Position): Boolean {
    return queen.x == pos.x ||
            queen.y == pos.y ||
            (queen.x - pos.x).absoluteValue == (queen.y - pos.y).absoluteValue
}
 
fun place(m: Int, n: Int, blackQueens: MutableList<Position>, whiteQueens: MutableList<Position>): Boolean {
    if (m == 0) {
        return true
    }
    var placingBlack = true
    for (i in 0 until n) {
        for (j in 0 until n) {
            val pos = Position(i, j)
            for (queen in blackQueens) {
                if (pos == queen ||!placingBlack && isAttacking(queen, pos)) {
                    continue@for
                }
            }
            for (queen in whiteQueens) {
                if (pos == queen || placingBlack && isAttacking(queen, pos)) {
                    continue@for
                }
            }
            if (placingBlack) {
                blackQueens.add(pos)
                placingBlack = false
            } else {
                whiteQueens.add(pos)
                if (place(m - 1, n, blackQueens, whiteQueens)) {
                    return true
                }
                blackQueens.removeAt(blackQueens.size - 1)
                whiteQueens.removeAt(whiteQueens.size - 1)
                placingBlack = true
            }
        }
    }
    if (!placingBlack) {
        blackQueens.removeAt(blackQueens.size - 1)
    }
    return false
}
 
fun printBoard(n: Int, blackQueens: List<Position>, whiteQueens: List<Position>) {
    // initialize the board
    val board = Array(n) { Array(n) {'' } }
    for (i in 0 until n) {
        for (j in 0 until n) {
            if (i % 2 == j % 2) {
                board[i][j] = '•'
            } else {
                board[i][j] = '◦'
            }
        }
    }
 
    // insert the queens
    for (queen in blackQueens) {
        board[queen.y][queen.x] = 'B'
    }
    for (queen in whiteQueens) {
        board[queen.y][queen.x] = 'W'
    }
 
    // print the board
    for (row in board) {
        for (cell in row) {
            print("$cell ")
        }
        println()
    }
    println()
}
 
