fun main() {
    println(count89s(1_000_000))
    println(count89s(100_000_000))
}
 
fun count89s(limit: Int): Int {
    if (limit < 1) return 0
    val end = IntArray(min(limit, 9 * 9 * 9 + 2))
    var result = 0
 
    for (i in 1 until end.size) {
        for (end[i] = i; end[i]!= 1 && end[i]!= 89; end[i] = squareDigitSum(end[i])) { }
        if (end[i] == 89) result++
    }
    for (i in end.size until limit) {
        if (end[squareDigitSum(i)] == 89) result++
    }
    return result
 
    fun squareDigitSum(n: Int): Int {
        var sum = 0
        var n = n
        while (n > 0) {
            val digit = n % 10
            sum += digit * digit
            n /= 10
        }
        return sum
    }
}

