fun placeKings(brd: Array<Array<String>>) {
	while (true) {
		val rankWhite = Random.nextInt(0, 7)
		val fileWhite = Random.nextInt(0, 7)
		val rankBlack = Random.nextInt(0, 7)
		val fileBlack = Random.nextInt(0, 7)
		val diffList = arrayOf(Math.abs(rankWhite - rankBlack), Math.abs(fileWhite - fileBlack))
		if (diffList.sum() > 2 || diffList.toSet().size == 2) {
			brd[rankWhite][fileWhite] = "K"
			brd[rankBlack][fileBlack] = "k"
			break
		}
	}
}
 
fun populateBoard(brd: Array<Array<String>>, wp: Int, bp: Int) {
	for (x in 0..1) {
		var pieceAmount: Int
		var pieces: Array<String>
		if (x == 0) {
			pieceAmount = wp
			pieces = pieceList
		} else {
			pieceAmount = bp
			pieces = pieceList.map { it.toLowerCase() }.toTypedArray()
		}
		while (pieceAmount!= 0) {
			val pieceRank = Random.nextInt(0, 7)
			val pieceFile = Random.nextInt(0, 7)
			val piece = pieces.random()
			if (brd[pieceRank][pieceFile] == " " &&!pawnOnPromotionSquare(piece, pieceRank)) {
				brd[pieceRank][pieceFile] = piece
				pieceAmount--
			}
		}
	}
}
 
fun fenFromBoard(brd: Array<Array<String>>): String {
	var fen = ""
	for (x in brd) {
		var n = 0
		for (y in x) {
			if (y == " ") {
				n++
			} else {
				if (n!= 0) {
					fen += n.toString()
				}
				fen += y
				n = 0
			}
		}
		if (n!= 0) {
			fen += n.toString()
		}
		fen += if (fen.count { it == '/' } < 7) "/" else ""
	}
	fen += " w - - 0 1\n"
	return fen
}
 
fun pawnOnPromotionSquare(pc: String, pr: Int): Boolean {
	return if (pc == "P" && pr == 0) {
		true
	} else pc == "p" && pr == 7
}

