data class Record(
        val account: String,
        val password: String,
        val uid: Int,
        val gid: Int,
        val gecos: List<String>,
        val directory: String,
        val shell: String
) {
    override fun toString() = "$account:$password:$uid:$gid:${gecos.joinToString(",")}:$directory:$shell"
 
    companion object {
        fun parse(text: String): Record {
            val tokens = text.split(":")
            return Record(
                    tokens[0],
                    tokens[1],
                    tokens[2].toInt(),
                    tokens[3].toInt(),
                    tokens[4].split(","),
                    tokens[5],
                    tokens[6]
            )
        }
    }
}

fun newSpeller(blocks: String): (String) -> Boolean {
    val bl = blocks.split(" ")
    return { word: String -> r(word, bl) }
}
 
fun r(word: String, bl: List<String>): Boolean {
    if (word.isEmpty()) {
        return true
    }
    val c = word[0].toLowerCase()
    for (i in bl.indices) {
        if (c == bl[i][0].toLowerCase() || c == bl[i][1].toLowerCase()) {
            val tmp = bl[i]
            bl[i] = bl[0]
            bl[0] = tmp
            if (r(word.substring(1), bl.subList(1, bl.size))) {
                return true
            }
            bl[i] = bl[0]
            bl[0] = tmp
        }
    }
    return false
}
 
fun main(args: Array<String>) {
    val sp = newSpeller(
        "BO XK DQ CP NA GT RE TG QD FS JW HU VI AN OB ER FS LY PC ZM")
    for (word in arrayOf("A", "BARK", "BOOK", "TREAT", "COMMON", "SQUAD", "CONFUSE")) {
        println("$word ${sp(word)}")
    }
}

