fun main(args: Array<String>) {
    val h = HashMap<Long, Int>()
    for (dir in args) {
        dodir(dir, h)
    }
 
    var s = 0L
    var n = 0
    for ((k, v) in h.entries.sortedBy { it.key }) {
        println("Size $k -> $v file(s)")
        n += v
        s += k * v
    }
    println("Total $s bytes for $n files")
}
 
fun dodir(path: String, h: MutableMap<Long, Int>) {
    val dir = File(path)
    for (name in dir.list()) {
        val p = File(dir, name)
 
        if (p.isSymbolicLink) {
            // pass
        } else if (p.isFile) {
            h[p.length()] = h.getOrDefault(p.length(), 0) + 1
        } else if (p.isDirectory) {
            dodir(p.absolutePath, h)
        } else {
            // pass
        }
    }
}

import java.util.Arrays
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors
import java.util.concurrent.Future
import java.util.stream.IntStream
import java.util.stream.Stream
import kotlin.math.min

object VogelsApproximationMethod {
    val demand = intArrayOf(30, 20, 70, 30, 60)
    val supply = intArrayOf(50, 60, 50, 50)
    val costs = arrayOf(
        intArrayOf(16, 16, 13, 22, 17),
        intArrayOf(14, 14, 13, 19, 15),
        intArrayOf(19, 19, 20, 23, 50),
        intArrayOf(50, 12, 50, 15, 11)
    )

    val nRows = supply.size
    val nCols = demand.size

    var rowDone = BooleanArray(nRows)
    var colDone = BooleanArray(nCols)
    var result = Array(nRows) { IntArray(nCols) }

    val es: ExecutorService = Executors.newFixedThreadPool(2)

    @JvmStatic
    fun main(args: Array<String>) {
        var supplyLeft = IntStream.of(*supply).sum()
        var totalCost = 0

        while (supplyLeft > 0) {
            val cell = nextCell()
            val r = cell[0]
            val c = cell[1]

            val quantity = min(demand[c], supply[r])
            demand[c] -= quantity
            if (demand[c] == 0)
                colDone[c] = true

            supply[r] -= quantity
            if (supply[r] == 0)
                rowDone[r] = true

            result[r][c] = quantity
            supplyLeft -= quantity

            totalCost += quantity * costs[r][c]
        }

        Stream.of(*result).forEach { a -> println(Arrays.toString(a)) }
        println("Total cost: $totalCost")

        es.shutdown()
    }

    fun nextCell(): IntArray {
        val f1: Future<IntArray> = es.submit { maxPenalty(nRows, nCols, true) }
        val f2: Future<IntArray> = es.submit { maxPenalty(nCols, nRows, false) }

        val res1 = f1.get()
        val res2 = f2.get()

        return if (res1[3] == res2[3])
            if (res1[2] < res2[2]) res1 else res2
        else if (res1[3] > res2[3]) res2 else res1
    }

    fun diff(j: Int, len: Int, isRow: Boolean): IntArray {
        var min1 = Int.MAX_VALUE
        var min2 = Int.MAX_VALUE
        var minP = -1
        for (i in 0 until len) {
            if (isRow && colDone[i] ||!isRow && rowDone[i])
                continue
            val c = if (isRow) costs[j][i] else costs[i][j]
            if (c < min1) {
                min2 = min1
                min1 = c
                minP = i
            } else if (c < min2)
                min2 = c
        }
        return intArrayOf(min2 - min1, min1, minP)
    }

    fun maxPenalty(len1: Int, len2: Int, isRow: Boolean): IntArray {
        var md = Int.MIN_VALUE
        var pc = -1
        var pm = -1
        var mc = -1
        for (i in 0 until len1) {
            if (isRow && rowDone[i] ||!isRow && colDone[i])
                continue
            val res = diff(i, len2, isRow)
            if (res[0] > md) {
                md = res[0]  // max diff
                pm = i       // pos of max diff
                mc = res[1]  // min cost
                pc = res[2]  // pos of min cost
            }
        }
        return if (isRow) intArrayOf(pm, pc, mc, md) else intArrayOf(pc, pm, mc, md)
    }
}

fun horner(x: Long, c: List<Long>): Long {
    var acc: Long = 0
    for (i in c.size - 1 downTo 0) {
        acc = acc * x + c[i]
    }
    return acc
}
 
fun main(args: Array<String>) {
    println(horner(3, listOf(-19L, 7L, -4L, 6L)))
}

fun pernicious(w: Int): Boolean {
    val ff = 1 shl 32 - 1
    val mask1 = ff / 3
    val mask3 = ff / 5
    val maskf = ff / 17
    val maskp = ff / 255
    var w = w
    w -= w shr 1 and mask1
    w = w and mask3 + w shr 2 and mask3
    w = (w + w shr 4) and maskf
    return 0xa08a28ac shr (w * maskp shr 24) and 1!= 0
}
 
fun main(args: Array<String>) {
    var i = 0
    var n = 1
    while (i < 25) {
        if (pernicious(n)) {
            print("$n ")
            i++
        }
        n++
    }
    println()
    for (n in 888888877..888888888) {
        if (pernicious(n)) {
            print("$n ")
        }
    }
    println()
}

fun main() {
    val tableA = arrayOf(
