    for (i in tableA.indices) {
        val r = tableA[i]
        h.getOrPut(r.key) { mutableListOf() }.add(i)
    }
    // join phase
    for (x in tableB) {
        for (a in h[x.key]!!) {
            println(tableA[a], x)
        }
    }
}

