fun grabInput(msg: String): String? {
    val buf = StringBuilder()
    System.out.print("$msg: ")
    System.out.flush()
 
    val reader = BufferedReader(InputStreamReader(System.`in`))
    try {
        buf.append(reader.readLine())
    } catch (e: IOException) {
        return null
    }
 
    return buf.toString()
}
 
fun exitErr(msg: String, code: Int): Nothing {
    System.err.println(msg)
    System.exit(code)
}

fun hDist(p1: List<Double>, p2: List<Double>) = Math.hypot(*p1.mapIndexed { i, e -> e - p2[i] }.toDoubleArray()) / 2
fun pAng(p1: List<Double>, p2: List<Double>) = Math.atan(p1.mapIndexed { i, e -> e - p2[i] }.reduce { p, c -> c / p })
fun solveF(p: List<Double>, r: Double) = { t: Double -> r * Math.cos(t) + p[0] to r * Math.sin(t) + p[1] }
fun diamPoints(p1: List<Double>, p2: List<Double>) = p1.mapIndexed { i, e -> e + (p2[i] - e) / 2 }
 
fun findC(p1: List<Double>, p2: List<Double>, s: Double): String {
    val solve = solveF(p1, s)
    val halfDist = hDist(p1, p2)
    var msg = "p1: $p1, p2: $p2, r:$s Result: "
    return when (Math.signum(s - halfDist)) {
        0.0 -> if (s == 0.0) "Radius Zero" else "Points on diameter. Circle at: ${diamPoints(p1, p2)}"
        1.0 -> if (halfDist == 0.0) "Coincident point. Infinite solutions"
        else {
            val theta = pAng(p1, p2)
            val theta2 = Math.acos(halfDist / s)
            listOf(1, -1).map { e -> solve(theta + e * theta2) }.forEach { e -> msg += "Circle at $e " }
            msg
        }
        -1.0 -> "No intersection. Points further apart than circle diameter"
        else -> "Error"
    }
}
 
fun main(args: Array<String>) {
    listOf(
        listOf(0.1234, 0.9876) to listOf(0.8765, 0.2345) to 2.0,
        listOf(0.0000, 2.0000) to listOf(0.0000, 0.0000) to 1.0,
        listOf(0.1234, 0.9876) to listOf(0.1234, 0.9876) to 2.0,
        listOf(0.1234, 0.9876) to listOf(0.8765, 0.2345) to 0.5,
        listOf(0.1234, 0.9876) to listOf(0.1234, 0.9876) to 0.0
    ).forEachIndexed { i, t -> println("Test: $i: ${findC(t.first, t.second, t.third)}") }
}

import kotlin.math.max
 
enum class Color {
    B,
    R
}
 
data class Tree(
    val color: Color,
    val left: Tree?,
    val value: Int,
    val right: Tree?
) {
    fun insert(val: Int): Tree {
        return this._insert(val).makeBlack()
    }
 
    fun _insert(val: Int): Tree {
        return when (compare(val, this.value)) {
            -1 -> {
                assert(this.left!= null)
                Tree(
                    this.color,
                    this.left!!._insert(val),
                    this.value,
                    this.right
                ).balance()
            }
            1 -> {
                assert(this.right!= null)
                Tree(
                    this.color,
                    this.left,
                    this.value,
                    this.right!!._insert(val)
                ).balance()
            }
            else -> this
        }
    }
 
    fun balance(): Tree {
        return when (this) {
            Tree(Color.B, Tree(Color.R, Tree(Color.R, a, x, b), y, c), z, d) -> {
                Tree(Color.R, Tree(Color.B, a, x, b), y, Tree(Color.B, c, z, d))
            }
            Tree(Color.B, Tree(Color.R, a, x, Tree(Color.R, b, y, c)), z, d) -> {
                Tree(Color.R, Tree(Color.B, a, x, b), y, Tree(Color.B, c, z, d))
            }
            Tree(Color.B, a, x, Tree(Color.R, Tree(Color.R, b, y, c), z, d)) -> {
                Tree(Color.R, Tree(Color.B, a, x, b), y, Tree(Color.B, c, z, d))
            }
            Tree(Color.B, a, x, Tree(Color.R, b, y, Tree(Color.R, c, z, d))) -> {
                Tree(Color.R, Tree(Color.B, a, x, b), y, Tree(Color.B, c, z, d))
            }
            else -> this
        }
    }
 
    fun makeBlack(): Tree {
        return this.copy(color = Color.B)
    }
 
    override fun toString(): String {
        return if (this == EMPTY) {
            "[]"
        } else {
            "[${if (this.color == Color.R) "R" else "B"}${this.value}]"
        }
    }
 
    fun print(indent: Int = 0) {
        if (this!= EMPTY) {
            assert(this.right!= null)
            this.right!!.print(indent + 1)
        }
 
        println("${" ".repeat(indent * 4)}$this")
 
        if (this!= EMPTY) {
            assert(this.left!= null)
            this.left!!.print(indent + 1)
        }
    }
}
 
