    println("Those values of d in 1..$n that can't be represented: ${quad(n)}")
}

class Matrix(val mtx: Array<IntArray>) {
    val height = mtx.size
    val width = mtx[0].size

    override fun toString(): String {
        val s = StringBuilder()
        for (i in 0 until height) {
            for (j in 0 until width) {
                s.append(mtx[i][j])
                if (j < width - 1) s.append(",")
            }
            if (i < height - 1) s.append("\n")
        }
        return s.toString()
    }

    fun transpose(): Matrix {
        val transposed = Array(width) { IntArray(height) }
        for (i in 0 until width) {
            for (j in 0 until height) {
                transposed[i][j] = mtx[j][i]
            }
        }
        return Matrix(transposed)
    }
}

