    """.trimMargin())
}   
 
fun main(args: Array<String>) {
    if (args.size == 1 && (args[0] == "-h" || args[0] == "-help")) {
       printHelp()
       return
    }
 
    println("Please enter the following and press return after each one")
 
    var pwdLen: Int?
